window.__D("text/torat-shmuel/c054",{"p":[[2001910163,"ח) <b>והנה</b> אח\"כ כתי' והסירותי מחלה מקרבך<sup data-n=\"1191\">71</sup>, מחלה קאי על היצה\"ר, וכמארז\"ל במד\"ר פ' מצורע פט\"ז<sup data-n=\"1192\">72</sup> שחולי קאי על היצה\"ר, וכן נק' מחלה. והענין הוא דהנה מחלה הוא היפך מבחי' לחם, שהלחם הוא מחבר הנפש עם הגוף, והמחלה הוא היפך מזה והיינו שהמחלה מפריד הנפש מן הגוף, וכך התורה היא מקשר ומחבר שיומשך המשכת אלקות בעולמות, משא\"כ היצה\"ר הוא מפריד ומבדיל כו', וכמ\"ש עונותיכם היו מבדילים כו' (ישעי' נ\"ט ב'). ולהבין זה יש להקדים מ\"ש הן האדם הי' כאחד ממנו<sup data-n=\"1193\">73</sup>, וארז\"ל במד\"ר בראשית פך\"א<sup data-n=\"1194\">74</sup> כיחידו של עולם, ועוד יש פי' במד\"ר שם כאחד ממנו כגבריאל שנא' והנה איש אחד לבוש בדים (דניאל יו\"ד ה'), ולכאו' אינו מובן למה תפס בגבריאל יותר מכל המלאכים בשלמא לפי' הראשון שמפרש כיחידו של עולם ניחא, אבל למ\"ד כגבריאל אינו מובן למה גבריאל דוקא. אך הענין הוא דהנה כתי' וייצר הוי' אלקים את האדם<sup data-n=\"1195\">75</sup> בב' יודין וארז\"ל כנגד שתי יצירות יצ\"ט ויצה\"ר<sup data-n=\"1196\">76</sup>, וצ\"ל שהרי משמע שמתחלה קודם החטא לא הי' יצה\"ר כלל שהרי כתי' ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"1197\">77</sup>, שהג\"ע הוא עתה תשלום שכר ואם הי' לו יצה\"ר איך יכול להיות בג\"ע, וגם זה אין לומר שלא הי' לו יצה\"ר כלל איך<sup data-n=\"1198\">78</sup> ניתן לו תומ\"צ וכמ\"ש לעבדה ולשמרה לעבדה זו רמ\"ח מ\"ע ולשמרה זו שס\"ה מל\"ת<sup data-n=\"1199\">79</sup>, שהרי המלאכים ביקשו את התורה<sup data-n=\"1200\">80</sup> ולא ניתנה להם, והשיב להם כלום יצה\"ר יש ביניכם<sup data-n=\"1201\">81</sup>, שמשמע שהתורה ניתנה בשביל בירור היצה\"ר דוקא, ואם לא הי' לו יצה\"ר כלל איך ניתן לו תומ\"צ, וגם מדרש הפסוק בגמ' ברכות דס\"א ע\"א משמע שהי' לו יצה\"ר, וייצר בשני יודי\"ן.\n<b>אך</b> הענין הוא דהנה מתחלה אף שהי' לו יצר אך לא הי' רע כלל כי בשרש היצה\"ר אינו רע<sup data-n=\"1202\">82</sup> כלל, וזהו וייצר הוי' אלקים ששרש שני היצרים הוא מש' הוי' וש'",[["1191","71","<b>והסירותי מחלה מקרבך</b>: משפטים כג, כה."],["1192","72","<b>במד\"ר פ' מצורע פט\"ז</b>: סימן ח. ראה גם לקו\"ש מצורע כרך לז ע' 43 ובהערה 16. חגה\"פ כרך יב ע' 156.\nמובא גם בסה\"מ תר\"ם ח\"א ע' קא."],["1193","73","<b>הן האדם . . ממנו</b>: בראשית ג, כב. ראה אוה\"ת בראשית כרך ג ע' 1160 ואילך."],["1194","74","<b>במד\"ר בראשית פך\"א</b>: סימן ה."],["1195","75","<b>וייצר . . את האדם</b>: בראשית ב, ז."],["1196","76","<b>בב' יודין . . יצ\"ט ויצה\"ר</b>: ראה ברכות סא, א (הובא בסוף פיסקא זו). זהר תזריע מו, ב. תרגום יוב\"ע שם. אוה\"ת בראשית כרך ג ע' 1044 ואילך."],["1197","77","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["1198","78","<b>כלל איך</b>: כ\"ה גם בסה\"מ תרל\"ג כאן. אלא ששם ניתוסף בפנים בין חצאי ריבוע תיבת [דא\"כ]."],["1199","79","<b>לעבדה זו רמ\"ח . . שס\"ה מל\"ת</b>: ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["1200","80","<b>המלאכים ביקשו את התורה</b>: שבת פח, ב."],["1201","81","<b>כלום יצה\"ר יש ביניכם</b>: ראה שם פט, א. לקמן מאמר ד\"ה שלש רגלים תחוג לי ספ\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תסט בהערה. אוה\"ת בראשית כרך ג ע' תקסג. סה\"מ תר\"ם ח\"ב ע' תרד."],["1202","82","<b>בשרש היצה\"ר אינו רע</b>: ראה גם אוה\"ת בראשית כרך ג ע' 1044. [וכן צ\"ל ב] סה\"מ תרל\"ח ע' קצו. וש\"נ."]]],[2001910164,"אלקים<sup data-n=\"1203\">83</sup>, וש' הוי' וש' אלקים נק' שני המאורות הגדולים<sup data-n=\"1204\">84</sup> וכמ\"ש בזהר, וז\"ש גדול הוי' ומהולל מאד<sup data-n=\"1205\">85</sup> בעיר אלקינו, וארז\"ל אימתי הוא גדול כשהוא בעיר אלקינו<sup data-n=\"1206\">86</sup>, מכלל דשם אלקים נק' ג\"כ גדול, והיינו שבשרש הם חסד וגבורה ששרש היצ\"ט הוא מבחי' חסד, ושרש היצה\"ר הוא מבחי' גבורה<sup data-n=\"1207\">87</sup>, והנה למעלה הם גבורות קדושות, שאדרבה גבורה הוא תוקף ההתגברות<sup data-n=\"1208\">88</sup> לאלקות, וכמו גבורות גשמים<sup data-n=\"1209\">89</sup> שיורדין בגבורה, שהוא תוקף החסד, שאם לא היו יורדים בגבורה הי' מבול ח\"ו, או כמו הדם הוא הנפש שהוא בחי' גבורה והדם דוקא הוא מחי' את האדם, וכך למעלה הגבורה הוא תוקף ההתגברות לאלקות, וז\"ע היצר שהי' לאדה\"ר קודם החטא היינו שהי' כמו בשרשו שהוא בחי' גבורות קדושות, כדי שעי\"ז יוכל לעבוד את ה', ואם לא הי' לו יצר כלל לא הי' יכול לעבוד את ה' וכמו שלמלאכים לא ניתנה התורה, וזהו שא' כאחד ממנו כגבריאל לפי שגבריאל הוא בחי' גבורות<sup data-n=\"1210\">90</sup> קדושות, ומ\"מ לא ניתנה תורה לגבריאל לפי שהמלאכים אינם בעלי בחירה<sup data-n=\"1211\">91</sup>, אך לאחר חטא עה\"ד נפל בשבירה ונעשה ממנו יצה\"ר גמור כי בחי' גבורה כשנופל למטה נעשה רע גמור כמ\"ש בזהר<sup data-n=\"1213\">93</sup>, משא\"כ החסדים<sup data-n=\"1212\">92</sup> אף כשנופל למטה אינו מתהוה רע גמור כו', וזהו שלאחר החטא עה\"ד דוקא אז נכנס בו יצה\"ר היינו כמו שהוא עתה כו' ונעשה היצה\"ר בחי' מחלה שהוא להפריד את אלקות מעולמות, וע\"ז נא' והסירותי מחלה מקרבך היינו שיהי' היצה\"ר ע\"ד שהי' קודם החטא שהי' ג\"כ טוב, ואדרבה כשהיצה\"ר נהפך אז נעשה בחי' גבוה יותר מכמו שהי', ועד\"מ כשעושין מרקחת מדבש וצנון<sup data-n=\"1214\">94</sup> שהוא מר ביותר, וכשהדבש מהפך את הצנון אזי נעשה מרקחת שהוא יותר טוב מהדבש בעצמו, וזהו שארז\"ל טוב זה יצ\"ט, מאד זה יצה\"ר<sup data-n=\"1215\">95</sup>, והיינו יצה\"ר",[["1203","83","<b>שני היצרים . . מש' הוי' וש' אלקים</b>: ראה גם אוה\"ת בראשית שם. ישעי' ע' רכט ס\"ו. תהלים ע' תלט ס\"ג (בשם המאו\"א אות יו\"ד, סכ\"ב). ביאוה\"ז — להצ\"צ — כרך ב ע' תתקה [ושם: ומשמע]. סה\"מ תר\"ם ח\"א ע' קח. וש\"נ."],["1204","84","<b>וש' הוי' וש' אלקים . . המאורות הגדולים</b>: בראשית א, טז. זהר בראשית כ, א."],["1205","85","<b>גדול הוי' ומהולל מאד</b>: תהלים מח, ב."],["1206","86","<b>אימתי הוא גדול כשהוא בעיר אלקינו</b>: ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תרכ\"ז ס\"ע ר. וש\"נ."],["1207","87","<b>היצ\"ט . . חסד . . היצה\"ר . . גבורה</b>: ראה רמ\"ז תזריע מו, ב ד\"ה וייצר."],["1208","88","<b>גבורה הוא תוקף ההתגבורת</b>: ראה תו\"א נח ט, ג. סה\"מ תרכ\"ז ס\"ע רמט. וש\"נ. לקו\"ש תולדות כרך ל ע' 108. וש\"נ. לקמן מאמר ד\"ה וירא ישראל את היד הגדולה פ\"ג."],["1209","89","<b>גבורות גשמים</b>: תענית ב, א. ראה גם לקו\"ת ואתחנן יג, ג. סה\"מ תר\"ם ח\"א ע' פא. וש\"נ."],["1210","90","<b>שגבריאל . . גבורות</b>: ראה זהר ויחי רלה, ב. סה\"מ תרל\"ח ע' קטז. וש\"נ."],["1211","91","<b>שהמלאכים אינם בעלי בחירה</b>: ראה תניא רפל\"ט. ולהעיר מלקו\"ת בהר מג, סע\"ד: שיש להם בחירה . . במט\"ט. אוה\"ת תבוא ע' תתרצג (והוא דרוש אדה\"ז משנת תקס\"ו): וכמו מיכאל גבריאל ומט\"ט . . שלפרקי' רחוקי' יחטאו . . והגם שהן בעלי בחירה. אוה\"ת איוב כרך א ע' תרס ואילך. תו\"ח וירא צט, ד ובהערה 41. ביאוה\"ז בלק צט, ב: ואין בהם קבלת עונש כ\"כ כמו בנשמות. מאמר ד\"ה להבין מה שארז\"ל כל הנהנה מסעודת חתן פ' שופטים תרל\"ה (ריש פיסקא ולהבין זה). סה\"מ תרל\"ג ח\"ב כאן ע' תמ בשולי היריעה."],["1213","93","<b>גבורה . . רע גמור כמ\"ש בזהר</b>: בסה\"מ תרל\"ג כאן ע' תמ ניתוסף: רישא [דעשו] בעטפוי דיצחק — ראה בשולי היריעה שם."],["1212","92","<b>גבורה . . רע . . משא\"כ החסדים</b>: ראה גם לקמן מאמר ד\"ה וירא ישראל את היד הגדולה ובהערה 151."],["1214","94","<b>מרקחת מדבש וצנון</b>: מובא בכ\"מ ומהם: מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ע. תקס\"ג ח\"ב ע' תשדמ. סה\"מ תרל\"ג כאן ע' תמ. תרס\"ב כאן ע' רפד. תר\"ם ח\"א ע' לג. וש\"נ."],["1215","95","<b>טוב . . מאד זה יצה\"ר</b>: ילקוט שמעוני בראשית א, לא (רמז טז — ירושלים תשל\"ג ע' 46. וש\"נ). ראה תו\"א יתרו סט, ד. מאמרי אדה\"ז תקס\"ד ע' קד ואילך. סה\"מ תרכ\"ט ע' שכג. תרל\"ג כאן. תרל\"ח ע' קלה ואילך ובהערה 703. תר\"ם ח\"א ע' לג ואילך. תרס\"ב כאן."]]],[2001910165,"לאחר הבירור, שכשהיצה\"ר נהפך לטוב אזי הוא טוב מאד כו', וזהו ע\"י התורה, וכמשארז\"ל שהתורה עושה שלום בפמשמ\"ע ובפשמ\"ט<sup data-n=\"1216\">96</sup>, והיינו כי פשמ\"ע היינו שהתורה מחבר ש' הוי' וש' אלקים שהם שרש של שני היצרים, ובפשמ\"ט היינו כמו שנמשכו למטה התורה מחבר ג\"כ שגם היצה\"ר נהפך לטוב ממש, לפי ששרש המחבר מה שהוא יכול לחבר שני הפכים שרשו גבוה מאד<sup data-n=\"1217\">97</sup> כו' ולכן ש' הוי' הוא בת\"ת<sup data-n=\"1218\">98</sup> דוקא היינו גם בכלי הת\"ת<sup data-n=\"1219\">99</sup> לפי שהת\"ת מחבר חו\"ג<sup data-n=\"1220\">100</sup>, ומה שיש בכחו לחבר זהו מצד ששרשו גבוה מאד<sup data-n=\"1221\">101</sup> כנ\"ל לכן יכול לחבר חו\"ג, וכך התורה מפני ששרשה גבוה מאד לכן היא עושה שלום בפשמ\"ע ובפשמ\"ט שהתורה עושה שלום בין היצ\"ט ויצה\"ר שגם היצה\"ר יהפך לטוב, ויהי' היצה\"ר כמו שהוא בשרשו שנק' שניהם שני המאורות הגדולים, וזהו והסירותי מחלה הוא היצה\"ר שעכשיו הוא מחלה שמונע ומעכב, אבל ע\"י התורה יסור המחלה, ואומרו והסירותי לשון נוכח שזה קאי על המספר התורה והיינו כמ\"ש הרמב\"ן ז\"ל<sup data-n=\"1222\">102</sup> כשלישי המדבר שזהו בחי' אני ראשון כו', וכנ\"ל בענין אני הוי'<sup data-n=\"1223\">103</sup> כו', והיינו שענין ובירך כו' זהו בחי' ש' הוי' שממשיך הברכה מא\"א, אבל להיות והסירותי מחלה מכל וכל שהיצה\"ר יהי' כמו קודם החטא וכמו שהוא בשרשו בשני המאורות הגדולים זהו ע\"י בחי' אני אוא\"ס בחי' אני ראשון כו'.",[["1216","96","<b>שלום בפמשמ\"ע ובפמשמ\"ט</b>: סנהדרין צט, ב."],["1217","97","<b>ששרש המחבר . . שרשו גבוה מאד</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תריב ואילך. מאמרי אדה\"א שמות ח\"א ע' רלג ואילך. וש\"נ. ח\"ב ע' תקפה. וש\"נ. דברים ח\"ד ע' א'ריד וש\"נ."],["1218","98","<b>ש' הוי' הוא בת\"ת</b>: ראה זהר ויקרא יא, א. ע\"ח שער השמות שער מ\"ד, פ\"ג. פ\"ו. סידור שער המועדים ריז, ג. תו\"ח בראשית מא, א הערה 7."],["1219","99","<b>ש' הוי' . . בכלי הת\"ת</b>: ראה תו\"א נח י, סע\"ב ואילך. תו\"ח נח סד, ג ואילך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשפד."],["1220","100","<b>שהת\"ת מחבר חו\"ג</b>: ראה גם לקו\"ת תזריע כג, ג. לקמן מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' ובהערה 49. סה\"מ תר\"ם ח\"א ע' רלא-רלג."],["1221","101","<b>שהת\"ת . . ששרשו גבוה מאד</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט."],["1222","102","<b>כמ\"ש הרמב\"ן ז\"ל</b>: ראה פתיחת הרמב\"ן על התורה. לעיל מאמר ד\"ה ועבדתם את ה\"א הערה 8."],["1223","103","<b>וכנ\"ל בענין אני הוי'</b>: ראה לעיל שם על יד הערה 19 ואילך."]]],[2001910166,"<h3>במשנה וכו' ר' נהוראי</h3>\n<b>תצוה</b>\n<b>במשנה</b> סוף קדושין ר' נהוראי אומר<sup data-n=\"1224\">1</sup> מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה<sup data-n=\"1225\">2</sup>, וצ\"ל דהא מצינו בדברי רז\"ל ששיבחו את המלאכה כמארז\"ל באבות פ\"א משנה יו\"ד שמעי' אומר אהוב את המלאכה, וכן ארז\"ל (ברכות דף ח' סע\"א) גדול הנהנה מיגיעו יותר מירא שמים דאילו גבי יר\"ש כתי' אשרי איש ירא<sup data-n=\"1226\">3</sup> כו' ואילו גבי נהנה מיגיעו כתי' יגיע כפיך כו' אשריך וטוב לך<sup data-n=\"1227\">4</sup> כו'. וצ\"ל מ\"ע גדלות מעלת המלאכה כ\"כ. הנה כתי' ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"1228\">5</sup>, וארז\"ל במד\"ר ס\"פ ט\"ז<sup data-n=\"1229\">6</sup> ויניחהו מצות שבת מסר לו<sup data-n=\"1230\">7</sup> כד\"א וינח ביום השביעי<sup data-n=\"1231\">8</sup>, לעבדה ששת ימים תעבוד<sup data-n=\"1232\">9</sup> כו', וצ\"ל שהרי פי' לעבדה ולשמרה הוא ציוי, ואיך מפרש המד\"ר לעבדה הוא כמ\"ש ששת ימים תעבוד שהם<sup data-n=\"1234\">11</sup> רשות<sup data-n=\"1233\">10</sup>. ויובן בהקדם מ\"ש ויכל אלקים ביום השביעי מלאכתו אשר עשה, וישבת כו' מכל מלאכתו<sup data-n=\"1235\">12</sup> כו', ואח\"כ כי בו שבת מכל מלאכתו אשר ברא כו' ולכאו' אינו מובן הלא כתי' בדבר ה' שמים נעשו, ובע\"מ",[["1224","1","<b>במשנה . . ר' נהוראי אומר</b>: מאמר זה הוא חלק — ד\"פ הראשונים — ממאמר ד\"ה ויקח ה\"א את האדם (י\"ל בקונט' בפ\"ע — תשס\"ד), שנדפס בסה\"מ תרל\"א ח\"א ע' א. א) בשינוי התחלה ב) וכן ניתוסף כאן שתי שורות בסיומו.\nהמאמר דתרל\"א הוא מאמר ד\"ה אבות מלאכות שנדפס בסה\"מ תר\"ל ע' רמט ואילך (בשינויים וכו'). וראה גם שם ע' רמב ואילך [במהדורת תשמ\"ג. ובמהדורת תשל\"ג ע' רמב-רמג. ע' רמד ואילך]. ומיוסד על אוה\"ת יתרו ע' תתקנא ואילך. ובתוס' הגהות וכו' בסה\"מ עטר\"ת ע' לח ואילך. תרח\"ץ ע' עז ואילך.\nהמאמר נכתב בכת\"י מעתיק פרט לההתחלה (עד להלן: צ\"ל ההפרש בין מחשבה לדבור), ושתי שורות בסיום המאמר.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה — רק איזה שורות — נדפסה לקמן בחלק הנחותיו."],["1225","2","<b>במשנה סוף קדושין . . אלא תורה</b>: פ\"ד, מי\"ד (פב, א)."],["1226","3","<b>אשרי איש ירא</b>: תהלים קיב, א. סה\"מ עטר\"ת ותרח\"ץ כאן: האיש. וכן הוא לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן."],["1227","4","<b>יגיע כפיך . . וטוב לך</b>: תהלים קכח, ב."],["1228","5","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["1229","6","<b>במד\"ר ס\"פ ט\"ז</b>: ב\"ר פט\"ז, ה."],["1230","7","<b>מצות שבת מסר לו</b>: וכ\"ה באוה\"ת חוקת כרך ו ע' א'תתעא. כרך ה ע' א'תרכ [ובמהדורת תשנ\"ח כרך א בהוספות ע' 24 וע' 30]. סה\"מ תר\"ל ע' רמט כאן. תרל\"א כאן. לקמן מאמר ד\"ה ושאבתם מים בששון פ\"א.\nבב\"ר שם: נתן לו מצות שבת — וכ\"ה באוה\"ת יתרו ע' תתקכו. סה\"מ תר\"ל כאן ע' רמב־ עטר\"ת ותרח\"ץ כאן."],["1231","8","<b>וינח ביום השביעי</b>: יתרו כ, יא."],["1232","9","<b>ששת ימים תעבוד</b>: יתרו שם, ט. ראה גם סה\"מ תרל\"ב ח\"א ע' ס."],["1234","11","<b>ששת ימים תעבוד שהם רשות</b>: ראה גם (בנוסף להערה 1) לעיל מאמר (והנחה) ד\"ה זכור את יום השבת בתחילתו. לקמן ספ\"ג. ד\"ה ושאבתם מים בששון פ\"א. מכילתא הובא בדרשות ר' יהושע אבן שועיב פ' וישב [ע' עג ד\"ה ובספר חובת הלבבות]. מנחה בלולה יתרו כ, ט. לקו\"ש בשלח כרך יג ע' 71 הערה 54. י\"ב תמוז כרך לג ע' 143. רשימות חוב' יב ע' 4. מאמרי אדה\"א הנחות תקע\"ז ע' ערה. סה\"מ פר\"ת ע' קצא ואילך.\nהספר מנחה בלולה שהוזכר לעיל הוא לר' אברהם מנחם בר' יעקב הכהן רפאפורט ווירונה שנ\"ד. ראה שם הגדולים ח\"ב מערכת ספרים ערך מנחה בלולה אות קמו."],["1233","10","<b>לעבדה . . ציוי . . שהם רשות</b>: ראה גם אוה\"ת יתרו שבהערה 7."],["1235","12","<b>ויכל אלקים . . מכל מלאכתו . . מלאכתו</b>: בראשית ב, ב. ג."]]],[2001910167,"נברא העולם<sup data-n=\"1236\">13</sup>, וכמארז\"ל לא בעמל ולא ביגיעה ברא<sup data-n=\"1237\">14</sup> כו' כ\"א במאמר כו', ואיך נק' בשם מלאכה, שהרי דבור אינה מלאכה<sup data-n=\"1238\">15</sup>. ולהבין זה צ\"ל ההפרש בין מחשבה לדבור<sup data-n=\"1239\">16</sup>, שאנו רואים שהמח' מתאחדת יותר עם כחות הנפש שהרי המח' היא לבוש הפנימי<sup data-n=\"1240\">17</sup> כו' וא\"א לחשוב שום שכל בלתי מח' כו', משא\"כ הדבור נעשה נפרד ויוצא לחוץ, שהדבור יוצא לאויר העולם כו', ועד\"ז יובן למעלה שרש ההפרש בין מח' לדבור שלכאו' הדבור הוא בחי' נפרד<sup data-n=\"1241\">18</sup> כב\"י, אך באמת א\"א לומר כן למעלה ח\"ו שהרי אין לך דבר שחוץ ממנו וכמשנ\"ת בסש\"ב<sup data-n=\"1242\">19</sup>, שמאחר שאת השמים ואת הארץ אני מלא<sup data-n=\"1243\">20</sup>, ולית אתר פנוי מיני'<sup data-n=\"1244\">21</sup> א\"א לומר שהדבור הוא בחי' נפרד ח\"ו, וא\"כ כשנאמר שהדבור אינו נפרד כלל, איך נתהוו מבחי' הדבור עולמות הנפרדים כעוה\"ז הגשמי, אלא עכצ\"ל שבחי' הדבור עליון נתצמצם בכמה בחי' צמצומים צמצום אחר צמצום, עד שנתהוה בחי' דבור שיוכל להתהוות מבחי' דבור זה נבראים נפרדים דעשי' שלמטה כו', וזהו מ\"ש נעשה אדם בצלמנו כדמותנו<sup data-n=\"1245\">22</sup>, פי' וענין הדמות הוא דמיון לבד, ואינו עצם הדבר כמו שהוא, וא\"כ פי' כדמותנו שזהו רק כדמיון הדבר שלמעלה ולא כמו הדבר שלמעלה עצמו, והיינו שעלמא תתאה היא רק כגוונא דעלמא עילאה<sup data-n=\"1246\">23</sup>, ולא כמו עלמא עילאה עצמה כו' והיינו שכמו שיש ד' פנים פני ארי' פני שור פני נשר פני אדם בבחי' המרכבה כו' כמו\"כ נתהוה למטה ג\"כ ד' פנים, אדם שלמטה שרשו מבחי' פני אדם, וארי' שלמטה שרשו מבחי' פני ארי' כו' וכן שור ונשר<sup data-n=\"1247\">24</sup> כו', אמנם הנה מ\"מ מה שנברא למטה הוא רק דמות לבד לגבי בחי' שרשם ומקורם בחי' ד' פנים שלמעלה, וכן אפי' המצות שלמטה שנתלבשו בדברים גשמים הם רק כמו דמות<sup data-n=\"1248\">25</sup> גבי בחי' מצות שלמעלה כמו לגבי תפילין שלמעלה היינו מה",[["1236","13","<b>בדבר הוי' . . ובע\"מ נברא העולם</b>: תהלים לג, ו. אבות רפ\"ה."],["1237","14","<b>לא בעמל ולא ביגיעה ברא</b>: ראה ב\"ר פ\"ג, ב. פי\"ב, י. סה\"מ תרל\"ב ח\"ב ע' שפז. ע' שפט."],["1238","15","<b>דבור אינה מלאכה</b>: ראה גם הדרושים שבהערה 1. לעיל מאמר ד\"ה זכור את יום השבת פ\"ד."],["1239","16","<b>ההפרש בין מחשבה לדבור</b>: ראה גם לקו\"ת בחוקותי מו, רע\"א. ביאוה\"ז בראשית כרך ב — להצ\"צ — ע' תקפח. הנסמן בסה\"מ תרל\"א כאן ע' ב."],["1240","17","<b>המח' היא לבוש הפנימי</b>: ראה גם פלח הרמון בחוקותי ע' תמ: ונק' לבוש מחובר בלשון אדמו\"ר שליט\"א [הצ\"צ]."],["1241","18","<b>הדבור הוא בחי' נפרד</b>: ראה גם סה\"מ עטר\"ת ע' לט. תרח\"ץ ע' עט. לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י פ\"א."],["1242","19","<b>בסש\"ב</b>: פכ\"א."],["1243","20","<b>שאת השמים . . אני מלא</b>: ירמי' כג, כד."],["1244","21","<b>ולית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["1245","22","<b>נעשה אדם בצלמנו כדמותנו</b>: בראשית א, כו."],["1246","23","<b>שעלמא תתאה . . כגוונא דעלמא עילאה</b>: זהר בראשית לח, א. ויגש רה, ב [צויין אליו באוה\"ת יתרו ע' תתקנב]. ביאוה\"ז ויגש כה, ד ואילך. המשך תער\"ב ח\"ב ס\"ע א'קפא ואילך."],["1247","24","<b>ד' פנים . . אדם . . פני אדם וארי' . . שור ונשר</b>: יחזקאל א, י. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ספ\"א. וש\"נ."],["1248","25","<b>המצות . . כמו דמות</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' צב. תקס\"ט ע' קט. אוה\"ת בשלח ע' תעג ואילך. לעיל מאמר ד\"ה קדש ישראל לה' פ\"ד. סה\"מ תרח\"ץ כאן ע' פא הערה 43."]]],[2001910168,"שהקב\"ה מניח תפילין<sup data-n=\"1249\">26</sup> ומתעטף בציצית<sup data-n=\"1250\">27</sup>, וכמארז\"ל במד\"ר ע\"פ מגיד כו' חוקיו ומשפטיו מה שהוא עושה<sup data-n=\"1251\">28</sup> אומר לישראל לעשות כו' הנה לגבי מצות אלו, התפילין והציצית הגשמי' שלמטה הם רק בחי' דמות ודמיון ורמז לבד, מאחר שהם נתלבשו בדברים גשמי', ועד\"ז יובן בענין הדבור שמה שנתצמצם הדבור בכדי שיוכל להיות ע\"י בחי' הדבור המצומצם בחי' התהוות נבראים נפרדים בע\"ג, הנה על בחי' דבור זה המצומצם כינו בכתוב בשם מלאכה, והיינו כי בבחי' הדבור יש ב' בחי' הא' כמו שהוא מאיר למעלה בלתי התלבשות כ\"כ אשר מבחי' דבור זה נתהוו עולמות עליונים אז אינו נק' מלאכה כלל, והב' הוא בחי' הדבור שנתצמצם בכמה צמצומים שיוכל להיות ע\"י בחי' דבור זה בחי' נבראים נפרדים בע\"ג שזהו בחי' דמות לבד, ויובן ד\"ז ע\"ד שמצינו בנבואה שיש בה ג\"כ ב' בחי' היינו בחי' צלם ודמות, וכמ\"ש גבי נביאים בהושע י\"ב פ' י\"א, וביד הנביאים אדמה, וכמארז\"ל כל הנביאים נתנבאו בכה, אבל משה נתנבא בזה<sup data-n=\"1252\">29</sup>, וכמ\"ש זה הדבר<sup data-n=\"1253\">30</sup>, והיינו שבנבואת משה הי' מאיר בו ומתגלה הדבור כמו שהוא בלתי העלם והסתר וז\"ע זה הדבר שהי' בבחי' זה והתגלות הוא בחי' אספה\"מ<sup data-n=\"1254\">31</sup> כמשל אדם הרואה דרך זכוכית בהירה שאינה מסתרת כו', משא\"כ שארי הנביאים נתנבאו בכה שהוא רק בחי' דמות לבד שלא הי' מתגלה הדבור אצלם כמו שהוא בלתי צמצום כו' כ\"א הי' מתצמצם ומתעלם עד שנמשך להנביא ולכן כתיב בהם וביד הנביאים אדמה שהוא בחי' דמות לבד הוא בחי' אספשא\"מ כו' כמשל הרואה דרך זכוכית הנק' שפיגל<sup data-n=\"1255\">32</sup> שאינו רואה עצם הדבר כ\"א הדמות מהדבר כו', ועד\"ז יובן ב' בחי' שבדבור שנעשה מקור לעולמות שיש בו ב' בחי' הא' בחי' הדבור שהוא בחי' התגלות הדבור כמו שהוא שמזה נעשו עולמות עליונים שהם בבחי' בצלמנו כו' ובחי' הדבור כמ\"ש נתצמצם ומתעלם כדי שיהיו עולמות התחתונים שהם רק כגוונא דעלמא עילאה הוא בחי' כדמותנו בחי' דמיון לבד כו'.\n(ב) <b>ועפ\"ז</b> יובן מה שע\"מ נק' מילין דהדיוטא וכמ\"ש בזהר לאו אורחא דמלכא<sup data-n=\"1256\">33</sup> לאשתעי במילין דהדיוטא, היינו מפני שע\"מ נעשו מקור לעולמות הנפרדים שנתצמצם הדבור בבחי' צמצום אחר צמצום כו' שזהו שכינו בכתוב בשם מלאכה שהוא בחי' ששת ימי בראשית בחי' ששת ימים עשה<sup data-n=\"1257\">34</sup> כו' הם ששת ימי המעשה, ולכן נק' בחי' זו מילין דהדיוטא כו', וזהו שאנו אומרים ובטובו מחדש",[["1249","26","<b>שהקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם לעיל שם ובהערה 126."],["1250","27","<b>שהקב\"ה . . ומתעטף בציצית</b>: ראה ר\"ה יז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תסז. וש\"נ."],["1251","28","<b>מגיד . . מה שהוא עושה</b>: תהלים קמז, יט. ראה שמו\"ר פ\"ל, ט. ראה גם סה\"מ תרכ\"ח ע' פח. תר\"ם ח\"ב ע' תרנט ואילך."],["1252","29","<b>כל הנביאים . . משה נתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. תו\"ח בשלח ח\"א קמד, ב הערה 29. אוה\"ת מטות ע' א'תצד. וראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"א."],["1253","30","<b>זה הדבר</b>: מטות ל, ב."],["1254","31","<b>משה . . אספה\"מ</b>: יבמות מט, ב."],["1255","32","<b>שפיגל</b>: בסה\"מ תרל\"א ע' ג (שממנו הועתק מאמר זה): שפיגול. ראה גם מאמרי אדה\"ז תקע\"א ס\"ע כד: שפיגול. תו\"א מקץ לג, א: שפיג\"ל. לקו\"ת שמע\"צ צב, ג־ שה\"ש כח, ב: שפיגע\"ל."],["1256","33","<b>שע\"מ . . לאו אורחא דמלכא</b>: נסמן לעיל במאמר ד\"ה קדש ישראל לה' פ\"ב הערה 83."],["1257","34","<b>ששת ימים עשה</b>: תשא לא, יז."]]],[2001910169,"בכי\"ת מע\"ב<sup data-n=\"1258\">35</sup>, וכתי' מה רבו מעשיך ה'<sup data-n=\"1259\">36</sup> שבחי' דבור המתצמצם בצמצום אחר צמצום בכדי להוות ולהחיות מאין ליש בחי' העולמות בע\"ג עד עולם העשי' הגשמי הוא הנק' בחי' מעשה למעלה שזהו בחי' מלאכה כו', ולכן מלאכה בגימ' אל אד'<sup data-n=\"1260\">37</sup>, והיינו לפי ששם זה אל אד' בגימ' צו<sup data-n=\"1261\">38</sup>, מאיר בעשי'<sup data-n=\"1262\">39</sup>, שהתהוות העשי' הוא מבחי' הדבור המצומצם שנק' בשם מלאכה כנ\"ל ולכן השם שמאיר בעשי' גימ' מלאכה כו'. ובזה יובן מעלת המלאכה ששיבחו אותה רז\"ל שאמרו גדול הנהנה מיגיעו כו', והוא לפי שע\"י עבודת האדם בבחי' מלאכה שלמטה שאדם עושה עי\"ז הוא ממשיך למעלה שיומשך כב\"י בבחי' צמצום הדבור שנק' מלאכה, היינו שיומשך בחי' אותיות המצומצם בבחי' דבר ה' הנצבים בנבראים דעשי' להחיותם ולהוותם מאין ליש כמ\"ש לעולם ה' דברך נצב בשמים<sup data-n=\"1263\">40</sup> וכידוע שאם הי' מסתלק כרגע ח\"ו הי' חוזר לאין ואפס כמ\"ש בסש\"ב ח\"ב פ\"א, ובתחלת הבריאה הי' זה מצד בחי' כי חפץ חסד<sup data-n=\"1264\">41</sup> ועכשיו באתעדל\"ת תליא מילתא שע\"י עבודת האדם בבחי' מלאכה עי\"ז נמשך בחי' חידוש הישינות שיומשך בחי' התחדשות החיות מאין ליש תמיד, שז\"ע משא\"א המחדש בטובו בכי\"ת מע\"ב כו'. אך הנה כ\"ז הוא כשעושה המלאכה באמונה שאין בה ח\"ו שום נדנוד עבירה היינו גזל וגניבה ח\"ו כ\"א עושה ועוסק במלאכתו באמונה, וע\"י העסק באמונה ממשיך בחי' חידוש הישינות שיומשך בחי' הדבור בצמצומים רבים שנק' מלאכה להחיות ולהוות עולמות הנפרדים שזהו בחי' מלאכה כמשנ\"ת לעיל, וכמ\"ש ביונה ששאלו לו מה מלאכתך<sup data-n=\"1265\">42</sup> ופי' המפרשים ששאלו לו אם עסק",[["1258","35","<b>ובטובו מחדש בכי\"ת מע\"ב</b>: ברכת יוצר."],["1259","36","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד."],["1260","37","<b>מלאכה בגימ' אל אד'</b>: מאו\"א מערכת מלאכה אות ל. וראה ביאיר נתיב שם מלקו\"ת [טעמי המצות] להאריז\"ל פ' בא מצות איסור מלאכה ביו\"ט. שעהמ\"צ שם. (ובנוסף להערה 1) אוה\"ת בראשית ח\"ב ע' תנח. סה\"מ תרס\"ו ע' ל. עטר\"ת ע' תקפד. תרפ\"ט ע' 221."],["1261","38","<b>אל אד' בגימ' צו</b>: ראה א) ע\"פ צו את בנ\"י — שער הכוונות דרושי תפלת השחר דרוש ג. פע\"ח שער עולם העשי' רפ\"ג [ובמהדורת מהר\"מ פאפראש שער הקרבנות רפ\"ד]. מ\"ח מסכת תפלת העשי' פ\"ד, מ\"ד ומ\"ו. סידור האריז\"ל תפלת העשי'. ב) שער מאמרי רשב\"י לזהר אד\"ר נשא קלב, א. קול ברמה שם נא, ב. מבו\"ש ש\"ב ח\"ב, פט\"ז.\nובדרושי רבותינו הובא בכ\"מ ומהם: (ובנוסף להערה 1) לקו\"ת מסעי פט, סע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרנב ושם: ”בלק\"ת ב' האריז\"ל (ע\"פ צו את בנ\"י)\". ע' תרנג (נו\"א) ”בכ' אריז\"ל\". ע' תרפח. סהמ\"צ להצ\"צ ע' 154 ”האריז\"ל\". ע' קז ”האריז\"ל ע\"פ צו את בנ\"י\". אוה\"ת פ' ראה ע' תשכו ”בפע\"ח בכוונת פ' התמיד\". שה\"ש ח\"א ע' שטו. סה\"מ תר\"ל ע' קכח. תרל\"ב ח\"א ע' קמט. ח\"ב ע' שעה. קונט' ומעין מאמר כ\"ג, פ\"א ושם: ”בפע\"ח שער התפלה בכוונת פ' התמיד\". סה\"מ תר\"ן ס\"ע תקיז (ובהנסמן שם ע' תקטז ואג\"ק מאת כ\"ק אדמו\"ר מהורש\"ב ח\"א ע' קלז) ”בלקו\"ת מהאריז\"ל\". תרס\"ט ס\"ע קא. תער\"ב ח\"ב ע' תתעג ”פע\"ח שער עולם העשי' פ\"ג\".\nויש לציין שבסה\"מ תר\"ן שם כותב לפנ\"ז ע\"פ וברכך ה\"א בכל אשר תעשה. ולכאורה כוונתו לדרוש זה במאמרי אדה\"ז תקס\"ה הנ\"ל ע' תרנב ששם מציין ללק\"ת. וראה לעיל הערה 37."],["1262","39","<b>אל אד' . . מאיר בעשי'</b>: ראה הערה שלפנ\"ז."],["1263","40","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["1264","41","<b>ובתחלת הבריאה . . חפץ חסד</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, ספ\"ו. סידור שער התפלה יט, רע\"א. לקו\"ת אחרי כה, סע\"ג. נצבים מז, ב. שעה\"י פי\"א. ש\"א ל, א הערה 15. סה\"מ תרל\"ח ס\"ע מז ואילך ובהנסמן שם."],["1265","42","<b>מה מלאכתך</b>: יונה א, ח ובמפרשים שם."]]],[2001910170,"באמונה. ועפ\"ז יובן ג\"כ משארז\"ל במד\"ר ס\"פ ויצא פע\"ד<sup data-n=\"1266\">43</sup> ר' ירמי' אמר חביבה היא המלאכה מזכות אבות כו', שהרי יעקב אמר<sup data-n=\"1267\">44</sup> את עניי ואת יגיע כפי ראה אלקים ויוכח<sup data-n=\"1269\">46</sup> אמש<sup data-n=\"1268\">45</sup> שבזה הזכיר מלאכה ולא הזכיר זכות אבות, והיינו לפי שע\"י מלאכה ממשיכים בחי' ובטובו מחדש בכי\"ת מע\"ב, בחי' אוא\"ס, שיומשך הדבור בצמצומי' רבים שנק' בשם מלאכה כו' שעי\"ז הוא קיום העולמות כו'. וזהו מ\"ש אחר ויניחהו כו' לעבדה כו' ויצו ה' אלקים על האדם מכל עץ הגן אכול תאכל<sup data-n=\"1270\">47</sup>, והיינו שע\"י העבודה בבחי' לעבדה ולשמרה עי\"ז ציוה לו לאכול אח\"כ, כי העבודה הוא בחי' גבוה. ובזה יובן ג\"כ מ\"ש בפ' שני' דק\"ש ואספת דגנך<sup data-n=\"1271\">48</sup>, שלכאו' מה\"ע ואספת דגנך לק\"ש, אך לפי משנ\"ת לעיל שע\"י המלאכה ממשיכים בחי' חידוש הישינות לכן נא' זה בק\"ש. אמנם צ\"ל ואספת דגנך שצריך לאסוף ולקבץ כל הבחי' דגנך ותירושך ויצהריך אל בחי' אחד בחי' ביטול, והיינו ע\"י שיהי' אצלינו תורתינו קבע<sup data-n=\"1272\">49</sup> ומלאכתינו עראי שהעיקר יהי' בחי' תורה כו' רק שצריך ג\"כ לעשות מלאכה, כי כל תורה שאין עמה מלאכה סופה בטילה<sup data-n=\"1273\">50</sup> כו', וגם כמשנ\"ת לעיל מעלת המלאכה שע\"י מלאכה באמונה ממשיכים חיות העולמות כו'.\n<b>ועוי\"ל</b> טעם מה שגדולה מלאכה ע\"פ מה שידוע שיש ל\"ט אבות מלאכות<sup data-n=\"1274\">51</sup>, ושרש ענין ל\"ט מלאכות הם כנגד ל\"ט קללות<sup data-n=\"1275\">52</sup> שנתקללו נחש וחוה ואדם והארץ, וע\"י העבודה באמונה בל\"ט מלאכות מתקנים את בחי' הל\"ט קללות שנתקללו עבור האכילה שלא כהוגן.\n(ג) <b>אך</b> הנה כ\"ז הוא בחול, שבששת ימי החול העבודה היא בל\"ט מלאכות לתקן כנ\"ל וכמ\"ש רז\"ל לעשות לתקן<sup data-n=\"1276\">53</sup>, וע\"י העבודה באמונה ממשיכים בחי' חידוש הישינות כנ\"ל, אמנם בשבת נא' כי בו שבת מכל מלאכתו, והיינו שבשבת",[["1266","43","<b>במד\"ר ס\"פ ויצא פע\"ד</b>: סימן יב.\nהובא גם בכ\"מ ומהם: אוה\"ת בראשית ח\"ב ע' תנח. יתרו כאן ע' תתקנב . סה\"מ תרכ\"ז ע' קלא. תר\"ל כאן ע' רנב. תרל\"א כאן ע' ה."],["1267","44","<b>שהרי יעקב אמר</b>: הוספה על הב\"ר. וראה גם סה\"מ תר\"ל ותרל\"א שבהערה שלפנ\"ז."],["1269","46","<b>ויוכח אמש</b>: וכ\"ה גם בסה\"מ תר\"ל ותרל\"א שבהערה 43. בב\"ר שם: וגו'."],["1268","45","<b>את עניי . . ויוכח אמש</b>: ויצא לא, מב."],["1270","47","<b>ויצו ה' אלקים . . תאכל</b>: בראשית ב טז [בהשמטת תיבת: לאמר]. ראה גם סה\"מ תר\"ל כאן ס\"ע רמג בשם המדרש."],["1271","48","<b>ואספת דגנך</b>: עקב יא, יד. ראה גם סה\"מ תרכ\"ו ע' קסח. ע' קעא. תרל\"ג ח\"ב ס\"ע שצו. לקמן מאמר והנחה ד\"ה כי תשא על יד הערות 23־ 30. המאמר שבהערה הבאה."],["1272","49","<b>אצלינו תורתינו קבע</b>: רמב\"ם הל' ת\"ת פ\"ג, ה\"ז. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י רפ\"ד. וש\"נ."],["1273","50","<b>כל תורה . . סופה בטילה</b>: אבות פ\"ב, מ\"ב."],["1274","51","<b>ל\"ט אבות מלאכות</b>: ראה שבת עג, א."],["1275","52","<b>ל\"ט קללות</b>: ראה זהר רע\"מ פינחס רמג, ב. תצא רפ, ב. ת\"ז תמ\"ח (פה, א). תס\"ד (צה, ב). תס\"ט (קיח, ב: ארעא . . תשע לווטין). ז\"ח רות עט, סע\"ד. זהר נח סא, ב ובאור החמה ורמ\"ז שם. במדב\"ר פ\"ה, ד. פי\"ח, כא בסופו. תנחומא ס\"פ קרח. רקאנטי בראשית ג, יב (טו, א). ציוני בראשית ג, יב (ו, א ואילך) הובאו בשל\"ה מס' שבת קלה, סע\"ב ואילך. אוה\"ת על מארז\"ל ע' לב (פ\"ג). מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ריש ע' קמח וע' רסז. המשך מים רבים תרל\"ו רפקס\"ו. אוה\"ת יתרו כאן (פ\"ג)־ סה\"מ תר\"ל־ תרל\"א כאן ע' ה ואילך."],["1276","53","<b>לעשות לתקן</b>: בתו\"ח בשלח ח\"א קלט, ד בשם הע\"ח. בסה\"מ תרכ\"ח בתחילתו: בזהר ובמד\"ר. ראה ב\"ר פי\"א, ו ובפרש\"י שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתסח. דברים ח\"ד ע' א'רט. סה\"מ תרצ\"ז ע' 214. לקמן מאמר ד\"ה ושאבתם מים בששון קיצור ד'."]]],[2001910171,"הוא עליות העולמות<sup data-n=\"1277\">54</sup> שבשבת מאיר הדבור כמו שהוא למעלה בלתי צמצומים והתלבשות כו' בחי' בצלמנו כו', וגם מאיר בשבת מלמעלה מבחי' הדבור, והיינו שהעולמות מקבלים חיות מבחי' המחשבה<sup data-n=\"1278\">55</sup> כו'. אך לפ\"ז צ\"ל מ\"ש זכור את יום השבת לקדשו<sup data-n=\"1279\">56</sup> הלא שבת מקדשא וקיימא<sup data-n=\"1280\">57</sup>, שהרי זהו מטעם כי בו שבת כו' בחי' עליות העולמות כו' ומהו לקדשו כו'. אך הענין הוא דהנה שבת הוא בחי' שבת בראשית<sup data-n=\"1281\">58</sup>, ויש ראשית וראשון<sup data-n=\"1282\">59</sup>, שראשית הוא ל' נוק' שמקבל מבחי' ראשון כו' וזהו ע\"י נש\"י שנש\"י ממשיכים בבחי' שבת, וכמארז\"ל במד\"ר בראשית ס\"פ י\"א<sup data-n=\"1283\">60</sup> אמרה שבת לפני הקב\"ה לכולם יש בן זוג ולי אין ב\"ז, א\"ל הקב\"ה כנס\"י יהי' בן זוגך, שנש\"י ממשיכים בבחי' שבת, והיינו כי ישראל הם בחי' לי ראש<sup data-n=\"1284\">61</sup>, שממשיכים בבחי' ראשית, דהנה ראש הוא אותיות אשר<sup data-n=\"1285\">62</sup> בחי' תענוג<sup data-n=\"1286\">63</sup> עליון, שממשיכים בחי' התענוג עליון בבחי' שבת שהיא בחי' ראשית חכ', וכמ\"ש וקראת לשבת ענג<sup data-n=\"1287\">64</sup> שממשיכים בחי' ענג עליון בבחי' שבת. וז\"ע שתי שבתות כהלכתן<sup data-n=\"1288\">65</sup> שהם בחי' שבת עילאה ושבת תתאה<sup data-n=\"1289\">66</sup>, שבת תתאה היא בחי' שבת בעצם שהוא בחי' שבת בראשית שהעלי' הוא מצד עצמו בחי' כי בו שבת כו' שהוא בחי' שביתה מבחי' הדבור דע\"מ, שהדבור מתעלה למקורו ושרשו, וידוע ששרש הדבור הוא מבחי' חכ'<sup data-n=\"1290\">67</sup> כנודע מענין אבא יסד ברתא<sup data-n=\"1291\">68</sup>, לכן העלי' של הדבור הוא עד בחי' חכ' ראשית ההשתל'<sup data-n=\"1292\">69</sup> כו' כמ\"ש במ\"א,",[["1277","54","<b>שבשבת הוא עליות העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. תו\"ח בא ח\"א קכז, א הערה 667."],["1278","55","<b>שהעולמות מקבלים . . מבחי' המחשבה</b>: ראה לקו\"ת שבת שובה סו, ג. סה\"מ תר\"ם ח\"א ס\"ע קמא ואילך ובהנסמן שם. לקמן מאמר ד\"ה ושאבתם מים בששון פ\"ג."],["1279","56","<b>זכור את יום השבת לקדשו</b>: יתרו כ, ח. ראה תו\"א יתרו סט, ג ואילך. לעיל מאמר ד\"ה זכור את יום השבת בתחילתו. וש\"נ. לקמן מאמר ד\"ה ושאבתם מים בששון פ\"א ואילך."],["1280","57","<b>שבת מקדשא וקיימא</b>: ביצה יז, א."],["1281","58","<b>שבת . . שבת בראשית</b>: נדרים עח, א ואילך."],["1282","59","<b>ראשית וראשון</b>: ראה תו\"א שם ע, א. סה\"מ תר\"ם ח\"א ע' קסב. וש\"נ. לעיל מאמר ד\"ה זכור פ\"ו."],["1283","60","<b>במד\"ר בראשית ס\"פ י\"א</b>: ס\"ח. ראה גם לעיל מאמר ד\"ה זכור בתחילתו. וש\"נ."],["1284","61","<b>ישראל . . לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["1285","62","<b>ראש הוא אותיות אשר</b>: ראה זהר בראשית טו, סע\"א. ע\"ח שער הולדת או\"א וזו\"ן שט\"ז, פ\"ב. סה\"מ תר\"ם ח\"א ע' קסג. וש\"נ."],["1286","63","<b>אשר בחי' תענוג</b>: ראה תו\"א תולדות יח, סע\"ב. ויצא כג, ג. שמות נג, ב. מאמרי אדה\"א נ\"ך ריש ע' שכז. וש\"נ."],["1287","64","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["1288","65","<b>שתי שבתות כהלכתן</b>: ראה שבת קיח, ב. לקו\"ת בהר מא, א. מב, ג ואילך. מג, ד ואילך. מאמרי אדה\"א בראשית ע' מז. שמות ח\"א ס\"ע קפט ואילך. ויקרא ח\"ב ע' תשיח ואילך. הנחות תקע\"ז ע' קכג ובהנסמן בהנ\"ל. תו\"ח בשלח ח\"א רח, ד. וש\"נ. סה\"מ תרל\"ד ע' ריד ואילך. ע' שנד ואילך."],["1289","66","<b>שבת עילאה ושבת תתאה</b>: זהר בהקדמה ה, ב."],["1290","67","<b>ששרש הדבור . . חכ'</b>: ראה לקו\"ת במדבר ז, ב."],["1291","68","<b>אבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. תו\"ח שמות ח\"א יב, א."],["1292","69","<b>חכ' ראשית ההשתל'</b>: ראה רמ\"ז לזהר ואתחנן רסה, ב — בדפי הספר קצד, א [ד\"ה לארקא] וסע\"ב. סה\"מ תר\"ם ח\"א ע' רי. וש\"נ."]]],[2001910172,"אמנם בחי' שבת עילאה הוא בחי' שבתא דיומא זהו מה שנש\"י ממשיכים בשבת, שהוא בחי' עלי' היותר גבוה ונעלה וכמ\"ש עולת שבת בשבתו<sup data-n=\"1293\">70</sup> בחי' שבתו של שבת, ששבת גופא עולה למעלה יותר כו'. וד\"כ יש ג' סעודות ג' בחי' בשבת<sup data-n=\"1294\">71</sup>, וסעודה השלישית הוא בחי' עלי' היותר עליונה שהוא בחי' רדכ\"ר<sup data-n=\"1295\">72</sup>, שז\"ע בחי' מתנה טובה שיש לי בבית גנזי ושבת שמה<sup data-n=\"1296\">73</sup> כו'.\n<b>והנה</b> מה שנש\"י ממשיכים בבחי' שבת זהו ע\"י ששת ימים תעבוד, שמי שטרח בע\"ש<sup data-n=\"1297\">74</sup> יאכל בשבת, והיינו ע\"י שעסק באמונה בששת ימי החול, שעי\"ז ממשיך למעלה שיתצמצם בחי' הדבור שנק' בשם מלאכה כנ\"ל שז\"ע בחי' ירידה והמשכה להוות ולהחיות כל מע\"ב מאין ליש הנה ע\"י ירידה זו נעשה אח\"כ העלי' בשבת, כי ירידה זו היא צורך עלי'<sup data-n=\"1298\">75</sup>, שע\"י הירידה דחול נעשה העלי' בשבת. וזהו שהמד\"ר מפרש לעבדה הוא בחי' ששת ימים תעבוד, והיינו לפי שששת ימים תעבוד הוא ג\"כ ציווי כמו לעבדה ולשמרה, כי ע\"י ששת ימים תעבוד כו' נעשה אח\"כ בחי' שבת, בחי' כי בו שבת כו'. וז\"ע ג\"כ מ\"ש סולם מוצב ארצה וראשו מגיע השמימה<sup data-n=\"1299\">76</sup>, שכמו ע\"י הסולם יש בחי' ירידה ועלי', כמו\"כ בחי' ששת ימים תעבוד הוא בחי' הירידה, ואח\"כ בחי' שבת הוא בחי' העלי' כו'.\n(ד) <b>אמנם</b> לפי משנ\"ת שגדולה מלאכה שעי\"ז נמשך בחי' חידוש הישינות שיומשך חידוש חיות העולמות כו', א\"כ צ\"ל מי שאינו יכול לעסוק במלאכה אלא הוא עוסק בתורה, ומאין יומשך ע\"י בחי' המשכת חיות העולמות הוא בחי' חידוש הישינות מה שבטובו מחדש בכי\"ת מע\"ב כו'. אך הענין הוא דהנה תורה נק' ג\"כ מלאכה דכתי' (משלי ך\"ד ך\"ז) הכן בחוץ מלאכתך ועתדה בשדה לך אחר ובנית ביתך, וארז\"ל בסוטה דמ\"ד ע\"א הכן בחוץ מלאכתך זה מקרא, ועתדה בשדה לך זה משנה, אחר ובנית ביתך זה גמרא, נמצא שהתורה נק' ג\"כ בחי' מלאכה, וזהו שהתו' נק' לחם<sup data-n=\"1300\">77</sup> וכמ\"ש לכו לחמו בלחמי<sup data-n=\"1301\">78</sup>, וכמו שהלחם גשמי צריך מתחלה י\"א מלאכות כדחשיב במשנה הזורע והחורש<sup data-n=\"1302\">79</sup> כו' ותנא סדורא דפת נקט<sup data-n=\"1303\">80</sup>, כמו\"כ יש בחי' אלו בלחם רוחני דתורה כמשנ\"ת במ\"א, ע' בלק\"ת בפ' בהר<sup data-n=\"1304\">81</sup> בד\"ה כי תבואו כו' ושבתה",[["1293","70","<b>עולת שבת בשבתו</b>: פינחס כח, י."],["1294","71","<b>ג' סעודות . . בשבת</b>: שבת קיז, סע\"ב."],["1295","72","<b>רדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג."],["1296","73","<b>מתנה טובה . . ושבת שמה</b>: שבת י, ב. ראה לקו\"ת במדבר יד, סע\"ג. מאמרי אדה\"ז תק\"ע ע' פז. ריש ע' צד. סה\"מ תרל\"ח ע' תעה. המשך תער\"ב ח\"ב ע' א'קכה ואילך."],["1297","74","<b>שמי שטרח בע\"ש</b>: ע\"ז ג, א."],["1298","75","<b>ירידה . . צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["1299","76","<b>סולם מוצב ארצה . . השמימה</b>: ויצא כח, יב."],["1300","77","<b>שהתו' נק' לחם</b>: ראה גם לעיל מאמר ד\"ה ובירך את לחמך ובהערה 3."],["1301","78","<b>לכו לחמו בלחמי</b>: משלי ט, ה. ראה זח\"א בהשמטות רס, א."],["1302","79","<b>הזורע והחורש</b>: שבת עג, א. ראה סה\"מ תרח\"ץ כאן ע' פד: החורש וכו' כמפורש במשנה. תו\"ח ויקהל ח\"ב תיט, א הערה 1071."],["1303","80","<b>ותנא סדורא דפת נקט</b>: ראה שבת עד, ב."],["1304","81","<b>בלק\"ת בפ' בהר</b>: מ, ב ואילך."]]],[2001910173,"פ\"ב פ\"ג. וענין בחי' העבודה בלחם רוחני דתורה הוא כמארז\"ל ע\"פ ושבתם וראיתם כו' בין עובד אלקים לאשר לא עבדו<sup data-n=\"1305\">82</sup>, אינו דומה שונה פרקו מאה פעמים לשונה פרקו מ\"פ ואחד, וע' בסש\"ב פט\"ו<sup data-n=\"1306\">83</sup>, שע\"י ששונה פרקו מאה פעמים וא' שהוא בחי' אתכפיא נק' עובד אלקים שז\"ע בחי' העבודה, וע\"י בחי' מלאכה זו שבתורה עי\"ז ממשיך למעלה ג\"כ בחי' מלאכה שיומשך בחי' חיות העולמות כו'. ועוד נוסף הוא על בחי' עבודה באמונה, שע\"י בחי' העבודה בחי' מלאכה שבתו' ממשיך מלמעלה הרבה מכמו שנמשך ע\"י סתם מלאכה, דהנה ההמשכה שע\"י בחי' הל\"ט מלאכות עי\"ז ממשיך שיהי' בבחי' העלם והסתר, והיינו שיתצמצם הדבור שזהו נק' מלאכה בכדי להוות ולהחיות עולמות הנפרדים כו', אמנם ע\"י בחי' מלאכה שבתורה עי\"ז ממשיך בחי' גילוי אוא\"ס ב\"ה הוא בחי' זה הדבר כנ\"ל גבי משה נתנבא בזה, וע\"ד כמו מלאכת המשכן שבמשכן הי' כל הל\"ט מלאכות, כי כל המלאכות נלמד ממלאכת המשכן<sup data-n=\"1307\">84</sup>, ובמלאכת המשכן הי' השראת השכינה כמ\"ש ושכנתי בתוכם<sup data-n=\"1308\">85</sup>, וכן משה אמר ויהי נועם כו' יהי רצון שתשרה שכינה במעשה ידיכם<sup data-n=\"1309\">86</sup>, ועד\"ז יובן בענין בחי' מלאכה שבתורה שהיא גבוה יותר מבחי' מלאכה דששת ימי החול כו' שע\"י מלאכה שבתורה נמשך גילוי אלקות כו' בחי' זה הדבר כו', ולכן ארז\"ל משחרב בהמ\"ק אין להקב\"ה בעולמו אלא ד' אמות של הלכה<sup data-n=\"1310\">87</sup>. וזהו שאמרו במשנה סוף קדושין ר' נהוראי אומר מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה, והיינו הגם שהמלאכה היא בחי' גדולה, וכמו שא' שמעי' אהוב את המלאכה<sup data-n=\"1311\">88</sup>, מ\"מ איני מלמד את בני אלא תורה, מפני כי מלאכתו של תורה היא יותר נעלה הרבה משארי מלאכות גם כשהם באמונה ובכשרות כו' והוא מטעם הנ\"ל שע\"י מלאכה שבתורה נמשך בחי' גילוי אלקות להיות בבחי' זה הדבר כו'.\n<b>ד'</b> אמות<sup data-n=\"1312\">89</sup> של הלכה הם ד' אותיות ש' הוי'<sup data-n=\"1313\">90</sup>, ע\"ד במקדש היו קורין השם ככתבו<sup data-n=\"1314\">91</sup>, ולפ\"ז י\"ל איני מלמד את בני אלא תורה, היינו שיהי' וכל בניך למודי הוי'<sup data-n=\"1315\">92</sup>.",[["1305","82","<b>ושבתם וראיתם. . לא עבדו</b>: מלאכי ג, יח."],["1306","83","<b>אינו דומה . . בסש\"ב פט\"ו</b>: ראה חגיגה ט, ב. הל' ת\"ת לאדה\"ז פ\"ב, ה\"ג. לקו\"ת פ' ראה כב, ב ואילך. לקו\"ש וארא ח\"א ע' 117 ואילך."],["1307","84","<b>כל המלאכות . . המשכן</b>: ראה שבת מט, ב."],["1308","85","<b>ושכנתי בתוכם</b>: תרומה כה, ח."],["1309","86","<b>משה אמר ויהי נועם . . במעשה ידיכם</b>: תהלים צ, יז. ראה רש\"י פקודי לט, מג. שבועות טו, ב ד\"ה ושיר של פגעים. לקו\"ש פקודי כרך יא ע' 169 ואילך ובהנסמן שם."],["1310","87","<b>משחרב בהמ\"ק . . של הלכה</b>: ראה ברכות ח, א. מאמרי אדה\"ז תקע\"א ע' צח. תו\"ח תרומה ח\"ב שיז, ב ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. הנחות תקע\"ז ע' ש. וש\"נ."],["1311","88","<b>שא' שמעי' אהוב את המלאכה</b>: נסמן לעיל בפנים רפ\"א."],["1312","89","<b>ד' אמות</b>: מכאן נרשם בגוכתי\"ק."],["1313","90","<b>ד' אמות . . ש' הוי'</b>: ראה גם אוה\"ת חנוכה כרך ה ע' 1834. בהעלותך ע' תטו [ובמהדורת תשנ\"ז ע' תטו]. בלק ע' תתקכג. ע' תתקלה. ע' תתקלט. מאמרי אדמו\"ר הצ\"צ הנחות ע' רנה וע' רסז. סה\"מ תרכ\"ז ע' שז. ע' שנח. תרל\"ג ח\"א ע' קסב."],["1314","91","<b>במקדש היו קורין השם ככתבו</b>: ראה תמיד פ\"ז, מ\"ב."],["1315","92","<b>וכל בניך למודי הוי'</b>: ישעי' נד, יג."]]],[2001910174,"<h3>וכך הי' מונה</h3>\n<b>בס\"ד</b>\n<b>בפ\"ה</b> דיומא משנה ג', וכך הי' מונה<sup data-n=\"1316\">1</sup> אחת<sup data-n=\"1317\">2</sup>, אחת ואחת, וצ\"ל למה צריך לספור הראשונה, הנה כתי' אחת שאלתי מאת ה'<sup data-n=\"1318\">3</sup> שצ\"ל הלא בקש דברים רבים ולמה אמר אחת שאלתי, ונודע דחז\"ל בזה ממך למדתי<sup data-n=\"1319\">4</sup>, כ\"א ליראה<sup data-n=\"1320\">5</sup> כו' ושם נת'<sup data-n=\"1321\">6</sup> שע\"י שבתי בבית ה' עי\"ז ממילא יבא לחזות בנועם כו' ופי' בית ה' הם אותיות התורה, ופי' כ\"א ליראה היינו יר\"ע ועי\"ז יבא לאה\"ר אהבה בתענוגים תרד\"מ<sup data-n=\"1322\">7</sup>, צ\"ל שזה\"ע התגלות עתיק שבבינה<sup data-n=\"1323\">8</sup>, כמ\"ש בת\"א בד\"ה לך לך<sup data-n=\"1324\">9</sup> בענין ה' דאברהם, וע' בד\"ה חכללי<sup data-n=\"1325\">10</sup> מענין אהבה בתענוגים, והנה פי' אחת שאלתי י\"ל שקאי על בחי' אחת היא<sup data-n=\"1327\">12</sup> יונתי<sup data-n=\"1326\">11</sup>, שז\"ע מה שכנס\"י היא בן זוג לשבת<sup data-n=\"1328\">13</sup> שממשיכים בחי' עונג בשבת כמ\"ש וקראת לשבת ענג<sup data-n=\"1329\">14</sup>.\n<b>נרשם</b> שלא בדיוק ואפ\"ל ממותר מא' אבות מלאכות מאמר וכך הי' מונה א' זהו האחת במלאכה שהותר בשבת וכן ביום הכפורים הזאה אחת, ע' בד\"ה אבות<sup data-n=\"1331\">16</sup> מלאכות<sup data-n=\"1330\">15</sup>.\n<b>בגמ'</b><sup data-n=\"1332\">17</sup> דף נ\"ה ע\"א<sup data-n=\"1333\">18</sup> ב' טעמים הא' שלא יטעה, הב' גזירת הכתוב מדכתי' יזה<sup data-n=\"1334\">19</sup> לימוד על הזאה ראשונה כמ\"ש רש\"י דכתי' חוקה, והרעב\"ט<sup data-n=\"1335\">20</sup> פי' שי\"ל שנצרך לסיים הזאות שלמטה בשבע ולא בשמונה, ויש להעיר מענין אז אלף על ז'",[["1316","1","<b>בפ\"ה דיומא משנה ג' וכך הי' מונה</b>: נרשם רק התחלת המאמר.\nראה עוד בענין וכך הי' מונה בלקו\"ת שה\"ש מב, א. שער האמונה נז, רע\"א. אוה\"ת (יהל אור) תהלים ע' קב."],["1317","2","<b>בפ\"ה דיומא . . מונה אחת</b>: נג, ב."],["1318","3","<b>אחת שאלתי מאת ה'</b>: תהלים כז, ד."],["1319","4","<b>ממך למדתי</b>: מדרש תהלים שם. הובא בילקוט שמעוני תהלים שם רמז תשו."],["1320","5","<b>כ\"א ליראה</b>: עקב י, יב."],["1321","6","<b>ושם נת'</b>: ראה גם לקו\"ת מסעי צו, ג-ד."],["1322","7","<b>תרד\"מ</b>: ראה גם הנסמן לעיל מאמר ד\"ה וברך את לחמך הערה 19."],["1323","8","<b>התגלות עתיק שבבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי כרך א ע' שסד."],["1324","9","<b>בת\"א בד\"ה לך לך</b>: יא, ב."],["1325","10","<b>בת\"א . . בד\"ה חכלילי</b>: מז, ג. ד ואילך."],["1327","12","<b>אחת היא יונתי</b>: שה\"ש ו, ט."],["1326","11","<b>אחת שאלתי . . אחת היא יונתי</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ס\"ע תשז. ס\"ע תשי ואילך."],["1328","13","<b>שכנס\"י . . זוג לשבת</b>: ראה ב\"ר פי\"א, ח. ראה גם לעיל מאמר ד\"ה זכור בתחילתו. וש\"נ."],["1329","14","<b>וקראת לשבת ענג</b>: ישעי' נח, יג. ראה גם המאמר שנדפס לפנ\"ז פ\"ג."],["1331","16","<b>בד\"ה אבות מלאכות</b>: סה\"מ תר\"ל ס\"ע רמה ואילך. וראה גם שם ע' רנד ואילך. תרל\"א ח\"א ע' ח פ\"ה."],["1330","15","<b>נרשם . . אבות מלאכות</b>: כ\"ז נכתב בצד הימיני של העמוד."],["1332","17","<b>בגמ'</b>: נרשם בשולי היריעה. והמשך הע' שלפנ\"ז נשאר חלק."],["1333","18","<b>בגמ' דף נ\"ה ע\"א</b>: יומא."],["1334","19","<b>מדכתי' יזה</b>: אחרי טז, יד."],["1335","20","<b>והרעב\"ט</b>: והר' עובדי' ברטנורה. ביומא שם פ\"ה, מ\"ג."]]],[2001910175,"בד\"ה אז ישיר<sup data-n=\"1336\">21</sup>, יוהכ\"פ שבת שבתון<sup data-n=\"1337\">22</sup> שבתון<sup data-n=\"1338\">23</sup>, לכן ח' הזאות והאחת שלמעלה חלוק להורות ע\"ד כדי שיעבור עליו שבת א'<sup data-n=\"1339\">24</sup>, ומ\"מ אחת ואחת בהזאות שלמטה להורות על שמונה דוקא.",[["1336","21","<b>אז אלף על ז' בד\"ה אז ישיר</b>: ראה אוה\"ת בשלח ע' תצח."],["1337","22","<b>יוהכ\"פ שבת שבתון</b>: אחרי טז, לא. אמור כג, לב."],["1338","23","<b>שבתון</b>: מכאן ואילך נכתב בהיפך העמוד ממעל לפיסקא זו (בגמ'). אולי תיבת שבתון היא מיותרת שהיא באה לציין שכאן מתחיל ההמשך מהנרשם לפנ\"ז."],["1339","24","<b>כדי שיעבור עליו שבת א'</b>: ראה ויק\"ר פכ\"ז, י. זהר רע\"מ תזריע מד, א. סה\"מ תר\"ם ח\"א ע' רמו. וש\"נ."]]],[2001910176,"<h3>ראה קראתי בשם</h3>\n<b>בס\"ד פ' תשא</b>\n<b>ראה</b> קראתי בשם<sup data-n=\"1340\">1</sup> בצלאל בן כו' למטה יהודה<sup data-n=\"1341\">2</sup>, ואמלא אותו<sup data-n=\"1342\">3</sup> כו' לחשוב מחשבות<sup data-n=\"1343\">4</sup> כו', ואח\"כ כתיב ואני הנה נתתי אתו את אהליאב בן אחיסמך למטה דן<sup data-n=\"1344\">5</sup>, וצ\"ל מ\"ש ראה קראתי בשם, דהל\"ל קראתי בשם בצלאל כו', ופי' במד\"ר<sup data-n=\"1345\">6</sup> שכשעלה משה למרום הראה לו הקב\"ה כל כלי המשכן כו' בא משה לירד סבור שהוא עושה אותו, קרא לו הקב\"ה א\"ל משה כו' אין לך רשות לעשות כו' אלא\n\n<i>נרשם בשולי היריעה:</i>\nראה קראתי בשם זח\"א דף ב' סע\"א אדכרנא שמי לאתקיימ' בצלאל על קיום אשלמותיה, ופי' במק\"מ שם אל שבשם בצלאל הוא המסייע לבצלאל<sup data-n=\"8212\">א</sup>.",[["1340","1","<b>ראה קראתי בשם</b>: מאמר זה הוא מאמר ד\"ה ראו קרא ה' בשם בצלאל שנדפס בסה\"מ תרל\"ה ח\"א ע' קכט ואילך [כנרשם בגוכתי\"ק בריש העמוד כאן: לד\"ה ראו בס' רל\"ה דקי\"ז]. בשינוי ההתחלה ובהוספות ושינויים.\nבסה\"מ תרל\"ה שם מציין (על מאמר זה והמשכו שבפ' פקודי — נדפס גם לקמן והפתיחא היא וידעת היום) לד\"ה ראו קרא וביאורו שנדפס בסה\"מ תקס\"ד ע' סה ואילך (וראה הנסמן במ\"מ לשם בסה\"מ תקס\"ד). לב' מאמרים אלו ראה גם מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ו ואילך. סה\"מ תרנ\"א ע' קכד ואילך.\nלמאמר זה ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שעא. ובהוספות וכו' נדפס בסה\"מ תרס\"ה ע' קעו ואילך.\nלקמן במאמר ד\"ה וידעת היום (שהוא כנראה המשך למאמר זה) בתחילתו מציין למאמר זה.\nבבוך תרמ\"א 2086 — כת\"י מעתיק — הכותרת: פ' תשא. הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן בחלק הנחותיו,\nחלק מהמאמר הפתיחא וההוספות נרשם בגוכתי\"ק והשאר נרשם בכת\"י מעתיק עם איזה תיקונים בגוכתי\"ק."],["1341","2","<b>ראה קראתי בשם . . למטה יהודה</b>: תשא לא, ב."],["1342","3","<b>ואמלא אותו</b>: שם לא, ג (צויין לקמן פ\"ג בפנים)."],["1343","4","<b>לחשוב מחשבות</b>: תשא שם, ד."],["1344","5","<b>ואני הנה . . למטה דן</b>: תשא לא, ו."],["1345","6","<b>ופי' במד\"ר</b>: ראה שמו\"ר מ, ב.\n\n<b>א</b> ) ראה גם לקמן קרוב לסיום המאמר. סה\"מ תרל\"ה ח\"א ע' קמה. אוה\"ת ויקהל ס\"ע ב'קפג."]]],[2001910177,"אמור להם והם עושים ולא א\"ל למי יאמר, אמר משה למי אומר, א\"ל אני מראה לך, ומה עשה הקב\"ה הביא לו ספרו של אדה\"ר והראה לו כל הדורות שהם עתידים לעמוד מבראשית עד תחה\"מ כו' דור דור ונביאיו א\"ל כאו\"א התקנתיו מאותה שעה, וכן בצלאל מאותו שעה התקנתיו הוי ראה קראתי בשם בצלאל כו', ואח\"כ כתי' ואני הנה נתתי אתו את אהליאב בן אחיסמך למטה דן והיינו שעיקר עשיית המשכן והכלים היו ע\"י בצלאל משבט יהודה, ואהליאב משבט דן, וצ\"ל מהו משני שבטים אלו דוקא. הנה ארז\"ל (ברכות ל\"ג ע\"א) גדול מקדש שניתן בין שני<sup data-n=\"1346\">*7</sup> אותיות, שנא' פעלת הוי' מקדש אד'<sup data-n=\"1347\">7</sup>, והנה בענין הדעת ארז\"ל שם ג\"כ גדולה דעה שניתן<sup data-n=\"1348\">8</sup> בין שתי אותיות שנא' כי אל דעות הוי'<sup data-n=\"1349\">9</sup>, רק שבמקדש נא' ש' הוי' תחלה ואח\"כ ש' אד', ובדיעות נא' שם אל תחלה ואח\"כ ש' הוי', והענין הוא דהנה ארז\"ל ברכות דנ\"ה ע\"א א\"ר יהודה א\"ר יודע הי' בצלאל לצרף אותיות שנבראו בהם שמים וארץ כתי' הכא (בפ' ויקהל ל\"ה ל\"א) וימלא אותו רוח אלקים בחכ' בתבונה<sup data-n=\"1350\">10</sup> ובדעת וכתיב התם (בבריאת שמים וארץ) ה' בחכ' יסד ארץ כונן שמים בתבונה, וכתי' בדעתו תהומות נבקעו (משלי ג' י\"ט כ'), ופי' בדעתו תהומות נבקעו הוא ענין הגשמים שמחברים שמים וארץ כי הגשם מן השמים על הארץ וארז\"ל אין לך טפה<sup data-n=\"1351\">11</sup> יורד מלמעלה שאין טפים עולים כנגדה, נמצא שהגשמים מחברים שמים וארץ וזהו ה' בחכ' יסד ארץ כונן שמים בתבונה והדעת מחבר שמים וארץ, וזהו בדעתו תהומות נבקעו שע\"י הדעת נעשה התחברות בחי' תהומות מעלה ומטה, ולכן הד' מינים שבלולב<sup data-n=\"1352\">*12</sup> שהם בחי' דעת<sup data-n=\"1353\">12</sup> באים לרצות על המים<sup data-n=\"1354\">13</sup>, ובבצלאל נא' ג\"כ ג' דברים אלו לכן ארז\"ל שהי' יודע לצרף אותיות שנבראו בהם שמים וארץ. ולכאו' צ\"ל למה הי' בצלאל צריך לידע לצרף אותיות שנבראו בהם שמים וארץ, ואיתא התירוץ בספרים<sup data-n=\"1355\">14</sup> שמפני שמעשה המשכן הי' מכוון כנגד בריאת העולם שכמו שבברה\"ע נא' בראשית ברא כו' את השמים<sup data-n=\"1356\">15</sup>, כמו\"כ יש בחי' שמים במעשה המשכן שהוא בחי' יריעות המשכן וכמ\"ש נוטה שמים כיריעה<sup data-n=\"1357\">16</sup>, בבריאת העולם נא' יהי אור,",[["1346","*7","<b>שני</b>: בסה\"מ תרל\"ה כאן בשתי. בסה\"מ תרס\"ה כאן כבפנים."],["1347","7","<b>פעלת הוי' מקדש אד'</b>: בשלח טו, יז."],["1348","8","<b>שניתן</b>: וכ\"ה בסה\"מ תרל\"ה ותרס\"ה כאן. בברכות שם: שנתנה — וכן הוא לקמן (ובהנ\"ל) על יד הערה 123."],["1349","9","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג."],["1350","10","<b>בתבונה</b>: כ\"ה בהכתוב ובסה\"מ תרל\"ה כאן. בגמ' שם ובסה\"מ תרס\"ה כאן: ובתבונה. ראה גם הגהת הגרי\"ב עה\"ג שם."],["1351","11","<b>אין לך טפה</b>: ראה תענית כה, ב [לפי גי' הרוקח סשע\"ז]. זהר רע\"מ פינחס רמז, ב. מאמרי אדה\"א הנחות תקע\"ז ע' רכב. וש\"נ. תו\"ח יתרו ח\"ב רעו, ב הערה 44."],["1352","*12","<b>הד' מינים שבלולב</b>: סוכה לא, א. מנחות כז, א."],["1353","12","<b>הד' מינים שבלולב . . דעת</b>: ראה לקו\"ת ברכה צו, א. סידור שער הלולב רסג, ג ואילך [נדפס גם במאמרי אדה\"ז תקס\"ח ח\"א ע' תמב]. מאמרי אדה\"ז תקס\"ב ח\"א ע' רפב. ח\"ב ע' תקנג. סה\"מ תר\"ם ח\"ב ע' תקעח ובהנסמן במ\"מ להנ\"ל."],["1354","13","<b>הד' מינים . . לרצות על המים</b>: ראה תענית ב, ב."],["1355","14","<b>ואיתא התירוץ בספרים</b>: ראה לקמן פ\"ג שמציין לאלשיך ולהה\"מ נ\"ע (או\"ת). וש\"נ."],["1356","15","<b>בראשית ברא . . השמים</b>: בראשית א, א."],["1357","16","<b>יריעות המשכן . . נוטה שמים כיריעה</b>: תרומה כו, ז. תהלים קד, ב. ראה גם לקו\"ת נשא כד, ג."]]],[2001910178,"במשכן הי' הארון והמנורה<sup data-n=\"1358\">17</sup>, בברה\"ע נא' יהי רקיע ויהי מבדיל<sup data-n=\"1359\">18</sup> במשכן כתי' והבדילה הפרוכת לכם בין הקדש ובין קדה\"ק<sup data-n=\"1360\">19</sup>*, ועד\"ז כל מה שיש בברה\"ע הי' במשכן ג\"כ לכן כדי שיוכל בצלאל לעשות המשכן הי' צריך לידע אותיות שנבראו בהם שמים וארץ.\n(ב) <b>ולהבין</b> זה, הנה ארז\"ל עוד בברכות קודם מאמר הנ\"ל<sup data-n=\"1361\">20</sup> בצלאל ע\"ש חכמתו נקרא בשעה שאמר הקב\"ה למשה לך עשה לי משכן ארון וכלים הלך משה והיפך ואמר ארון וכלים ומשכן א\"ל בצלאל אדם בונה בית ואח\"כ מכניס לתוכן כלים, כלים שאני עושה להיכן אכניסן שמא כך אמר לך הקב\"ה עשה משכן ארון וכלים א\"ל בצל אל היית וידעת, וצ\"ל מפני מה שינה משה והיפך. הנה כתי' ועשו לי מקדש<sup data-n=\"1362\">21</sup> ושכנתי בתוכם, וארז\"ל בתוכו לא נא' אלא בתוכם בתוך כאו\"א מישראל שגם בזמן בהמ\"ק הי' עיקר השראת השכינה בתוך כאו\"א, ועכשיו שאין לנו בהמ\"ק מ\"מ בתוך כאו\"א יש גם עכשיו בחי' המשכן, ובזה יתורץ מארז\"ל כ\"מ שנא' לי<sup data-n=\"1363\">22</sup> אינו זז כו' ולא בעוה\"ז הלא עכשיו אין לנו בהמ\"ק, אלא שבכאו\"א יש בחי'\n\n*)\n<i>בע' בפ\"ע נעתקו הגהות ולא נסמן מקומן בפנים וכנראה שייך לכאן:</i>\nלד\"ה ראו<sup data-n=\"8213\">ב</sup> — פ\"ש נא' ראה קראתי<sup data-n=\"8214\">ג</sup> — ולא הועתק כ\"א הנמחק<sup data-n=\"8215\">ד</sup>\nבשלישי יקוו המים<sup data-n=\"8216\">ה</sup>, ובמשכן ועשית כיור נחשת<sup data-n=\"8217\">ו</sup>, ברביעי יהי מאורות<sup data-n=\"8218\">ז</sup>, ובמשכן ועשית מנורת זהב טהור<sup data-n=\"8219\">ח</sup>, בחמישי ועוף יעופף<sup data-n=\"8220\">ט</sup>, ובמשכן והיו הכרובים<sup data-n=\"8221\">י</sup>, בששי נברא אדם<sup data-n=\"8222\">יא</sup>, ובמשכן ואתה הקרב כו' אהרן אחיך (שמות ך\"ח<sup data-n=\"8223\">יב</sup>), בשביעי כתי' ויכולו השמים<sup data-n=\"8224\">יג</sup>, ובמשכן ותכל כל עבודת המשכן<sup data-n=\"8225\">יד</sup>, בברי\"ע כתי' ויברך<sup data-n=\"8226\">טו</sup>, ובמשכן ויברך אותם (שמות ל\"ט)<sup data-n=\"8227\">טז</sup>, במד\"ר פ' נשא תוך פ' י\"ב<sup data-n=\"8228\">יז</sup> ע\"פ את המשכן<sup data-n=\"8229\">יח</sup>, וע' בפי' בעלי התוספת בס\"פ פקודי<sup data-n=\"8230\">יט</sup> שכנגד הארץ ופרי הארץ הי'<sup data-n=\"8231\">כ</sup> השולחן ושתי מערכות של לחה\"פ, שש המערכות כנגד ששה עתים זרע וקציר וקור וחום וקיץ וחורף עכ\"ל.",[["1358","17","<b>בבריאת . . יהי אור . . והמנורה</b>: בראשית א, ג. כ\"ז הוא הוספת כ\"ק אדמו\"ר מהר\"ש. בבמד\"ר המצויין בפנים בשולי הגליון כאן כ\"ז ליתא."],["1359","18","<b>יהי רקיע ויהי מבדיל</b>: בראשית א, ו [בדילוג]."],["1360","19","<b>והבדילה הפרוכת . . קדה\"ק</b>: תרומה כו, לג."],["1361","20","<b>בברכות קודם מאמר הנ\"ל</b>: בנוגע לבצלאל שהובא בפרק שלפנ\"ז — בשינויים."],["1362","21","<b>ועשו לי מקדש</b>: תרומה כה, ח. ראה אלשיך שם. לקו\"ש בא כרך כו ע' 83 הערה 49. שם תרומה ע' 173 הערה 45. טור ברקת הל' יו\"ט סתק\"כ (סג, א). טור יהלום יו\"ד סשס\"ג, ס\"ז (ב, ג). מאמרי אדמו\"ר הצ\"צ תרי\"ד ע' ו בשם הה\"מ."],["1363","22","<b>כ\"מ שנא' לי</b>: ראה ויק\"ר פ\"ב, ב. מדרש שמואל פי\"ט. ספרי בהעלותך יא, טז. לקו\"ת במדבר ט, ג.\n\n<b>ב</b> )<i>לד\"ה ראו:</i> הוראה להמעתיק, שהגהות אלו יעתיקם (עם שאר ההגהות וכו'), כשמעתיק המאמר ראו קרא תרל\"ה (ראה לעיל הערה 1).\n\n<b>ג</b> )<i>פ\"ש נא' ראה קראתי:</i> פעם שני' נאמר (המאמר ראו הנ\"ל) בהתחלה ראה קראתי, היינו דרוש הזה.\n\n<b>ד</b> )<i>ולא הועתק כ\"א הנמחק:</i> היינו שהמעתיק לא העתיק הגהות אלו, פרט להגה אחת שכן העתיקה שאותה מחק (העביר עלי' קו) כ\"ק אדמו\"ר מהר\"ש כאן.\nבבוך 2086 כת\"י הר\"ש סופר באו הגהות אלו בסוף המאמר על עמוד בפ\"ע מבלי הכותרת.\n\n<b>ה</b> )<i>יקוו המים:</i> בראשית א, ט.\n\n<b>ו</b> )<i>ועשית כיור נחשת:</i> תשא ל, יח.\n\n<b>ז</b> )<i>יהי מאורות:</i> בראשית א, יד.\n\n<b>ח</b> )<i>ועשית מנורת זהב טהור:</i> תרומה כה, לא. ראה גם אוה\"ת במדבר בהוספות ע' א'תפו ואילך (פ\"י).\n\n<b>ט</b> )<i>ועוף יעופף:</i> בראשית א, כ.\n\n<b>י</b> )<i>והיו הכרובים:</i> תרומה כה, כ.\n\n<b>יא</b> )<i>בששי נברא אדם:</i> בראשית א, כו-כז.\n\n<b>יב</b> )<i>ואתה הקרב . . שמות ך\"ח:</i> פסוק א.\n\n<b>יג</b> )<i>ויכולו השמים:</i> בראשית ב, א.\n\n<b>יד</b> )<i>ותכל כל עבודת המשכן:</i> פקודי לט, לב [ושם וכן במדרש המצויין בסמוך בפנים: משכן].\n\n<b>טו</b> )<i>ויברך: במדרש המצויין בסמוך בפנים:</i> ויברך אלקים — בראשית ב, ג.\n\n<b>טז</b> )<i>ויברך אותם (שמות ל\"ט):</i> פסוק מג.\n\n<b>יז</b> )<i>במד\"ר פ' נשא תוך פ' י\"ב:</i> סימן יג. ראה גם תנחומא פקודי ב. מדרש תהלים וילקוט המכירי לתהלים פכ\"ו. רבעה\"ת הנסמן בסמוך בפנים.\n\n<b>יח</b> )<i>ע\"פ את המשכן:</i> נשא ז, א.\n\n<b>יט</b> )<i>בס\"פ פקודי:</i> לח, כה.\n\n<b>כ</b> )<i>הי':</i> ברבעה\"ת שם ליתא."]]],[2001910179,"המקדש בעבודה כו', ולכאו' צ\"ל איך הוא השראת השכינה בתוך כאו\"א, הנה כתי' ואהבת את הוי' אלקיך<sup data-n=\"1364\">23</sup> בכל לבבך פי' ב' של בכל לבבך הוא ב' השימוש שבתוך כל הלב<sup data-n=\"1365\">24</sup> היינו בחלל הימני וחלל השמאלי יהי' הוי' אלקיך, וזהו ואהבת מל' אבה<sup data-n=\"1366\">25</sup> ל' רצון שיהי' הרצון שבחי' הוי' אלקיך יהי' בכל לבבך דהיינו בתוך כל הלב, דהנה יש פי' בואהבת בכל לבבך ל' הבטחה<sup data-n=\"1367\">26</sup> שהאהבה תהי' בכל לבבך, אבל כאן הפי' שהבית היא ב' השימוש דהיינו להיות בבחי' רצון שהוי' אלקיך יהי' בתוך כל הלב כו'.\n<b>והענין</b> הוא דהנה כתי' וידעת היום<sup data-n=\"1368\">27</sup> והשבות אל לבבך כי הוי' הוא האלקי' שענין הידיעה שהוי' הוא האלקי' הוא מצות לייחדו, שזהו מה שאנו אומרים בנוסח הקדושה ממקומו הוא כו' לעמו המייחדים שמו ערב ובקר בכי\"ת<sup data-n=\"1369\">28</sup> כו' שמע ישראל כי שמע ישראל ופסוק וידעת הוא ענין אחד שהם מצות לייחדו<sup data-n=\"1370\">29</sup>, וכמו שלבוא לידי ואהבת בכל לבבך שהיא מדה שבלב א\"א כ\"א ע\"י<sup data-n=\"1372\">31</sup> התבוננות<sup data-n=\"1371\">30</sup> בפסוק",[["1364","23","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["1365","24","<b>בכל לבבך . . שבתוך כל הלב</b>: ראה גם לקו\"ת שמע\"צ פח, ג. סה\"מ תר\"ם ח\"א ע' קפד. וש\"נ."],["1366","25","<b>ואהבת מל' אבה</b>: ראה ס' שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב [צב, רע\"א — ובמהדורת אותיות מרובעות (תשס\"ג) צד, א]. מאמרי אדה\"א הנחות תקע\"ז ע' רסד. וש\"נ. תו\"ח בשלח ח\"א קצט, ב. וש\"נ."],["1367","26","<b>בואהבת . . ל' הבטחה</b>: ראה תו\"א תשא פו, ג. סה\"מ תרכ\"ז ע' עד-עה. תרכ\"ט ע' שכב. תרל\"ב ח\"א ע' צה וע' קלט. לקו\"ש ר\"ח סיון כרך לג ע' 216 בהערה."],["1368","27","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם סה\"מ תרס\"ה כאן ס\"ע קעז ואילך. לקמן פ\"ג הערה 51."],["1369","28","<b>ממקומו הוא . . בכי\"ת</b>: נוסח קדושת כתר."],["1370","29","<b>שמע ישראל . . מצות לייחדו</b>: ואתחנן ו, ד. ראה רמב\"ם הל' יסוה\"ת פ\"א, ה\"ז. סהמ\"צ להרמב\"ם מ\"ע ב. ולהצ\"צ נט, ב ואילך. אוה\"ת בראשית כרך ז ע' 2328 ואילך."],["1372","31","<b>שהיא מדה . . ע\"י התבוננות</b>: ראה סהמ\"צ להרמב\"ם מ\"ע ג. ולהצ\"צ ע' קצט. לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י פ\"ב. וש\"נ."],["1371","30","<b>שלבוא לידי ואהבת . . ע\"י התבוננות</b>: ראה גם תו\"א תשא שם ואילך. לקו\"ת ואתחנן יא, ב ואילך ובהנסמן במ\"מ לשם. סהמ\"צ שבהערה הבאה."]]],[2001910180,"שמע כו' כמ\"ש במ\"א, כן א\"א לבוא לבחי' והשבות אל לבבך כו' כ\"א ע\"י בחי' וידעת<sup data-n=\"1373\">32</sup> בבחי' דעת והכרה כי הוי' הוא האלקי'. והענין הוא דהנה כתי' מה יתרון לאדם בכל עמלו שיעמול תחת השמש<sup data-n=\"1374\">33</sup>, פי' תחת השמש כי שמש ומגן הוי' אלקים<sup data-n=\"1375\">34</sup> שכמו שאור השמש א\"א לקבל כ\"א ע\"י המגן ונרתק רק לע\"ל ארז\"ל הקב\"ה מוציא חמה מנרתיקה<sup data-n=\"1376\">35</sup> מפני כי לע\"ל יזדכך העולם ויוכל לקבל אור השמש בלא המגן אבל עכשיו אין יכולים לקבל אור השמש בלא הנרתק כ\"א ע\"י הנרתק דוקא, וזהו מ\"ש לשמש שם אהל בהם<sup data-n=\"1377\">36</sup>, ועד\"ז יובן למעלה בענין שם הוי' ושם אלקים שהוי' ואלקים הוא כמשל שמש ומגן שפי' ש' הוי' ל' התהוות<sup data-n=\"1378\">37</sup> ששרש ההתהוות הוא משם הוי' וכמ\"ש יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"1379\">38</sup>, ולכאו' הלא כתי' בראשית ברא אלקים<sup data-n=\"1380\">39</sup> ובכל ע\"מ לא נז' כ\"א שם אלקים של\"ב פעמים אלקים נא' בע\"מ<sup data-n=\"1381\">40</sup> ולא נזכר כלל שם הוי' כ\"א אח\"כ באדם ובבע\"ח נא' וייצר ה' אלקים<sup data-n=\"1382\">41</sup>, אבל בכל ע\"מ לא נז' שם הוי' וגם במאמר נעשה אדם<sup data-n=\"1383\">42</sup> לא נז' שם הוי' כ\"א שם אלקים, והיינו הגם כי שרש ההתהוות הוא משם הוי', אבל כדי שיתהוה העולם ליש ודבר נפרד זהו ע\"י שם אלקים דוקא כי ש' אלקים הוא מדת הצמצום<sup data-n=\"1384\">43</sup> המעלים ומצמצם כדי שיוכל להיות נבראים בע\"ג, אבל אם הי' ההתהוות מש' הוי' לבד הי' העולם בטל במציאות ע\"ד עולמות עליונים כו'.\n(ג) <b>והענין</b> הוא, דהנה שם אלקים הוא בחי' אותיות<sup data-n=\"1385\">44</sup> וכמו שאנו רואים שהאותיות מסתירים על השכל<sup data-n=\"1386\">45</sup> כמו תושב\"כ שאין מושג<sup data-n=\"1387\">46</sup> פנימיות ועמקות רזין דאורייתא המלובש בהאותיות מפני שהאותיות מסתירים על הפנימיות המלובש בהאותיות, ואפי' גם במשנה בחי' תושבע\"פ הנה אין מבינים ביאור עומק המכוון",[["1373","32","<b>והשבות אל לבבך . . וידעת</b>: ראה לקו\"ת ואתחנן ד, ד."],["1374","33","<b>מה יתרון לאדם . . השמש</b>: קהלת א, ג."],["1375","34","<b>כי שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. תו\"א ויצא כא, ד. תו\"ח ח\"ש קכח, סע\"ב ואילך. ויצא קסז, ג ואילך. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["1376","35","<b>לע\"ל . . מוציא חמה מנרתיקה</b>: ראה נדרים ח, ב. ראה גם שער היחוה\"א רפ\"ד. תו\"ח בראשית לה, א ובהערה 12. שמות ח\"א לט, ב. וש\"נ. מאמרי אדה\"א הנחות תקע\"ז ע' שי."],["1377","36","<b>לשמש שם אהל בהם</b>: תהלים יט, ה. ראה גם אוה\"ת (יהל אור) שם."],["1378","37","<b>ש' הוי' ל' התהוות</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. סה\"מ תר\"ם ח\"א ע' קצח. וש\"נ."],["1379","38","<b>יהללו . . צוה ונבראו</b>: תהלים קמח, ה. ראה גם לקמן פ\"ג. לעיל מאמר ד\"ה ועבדתם את ה\"א פ\"ב (פיסקא והנה כדי). וש\"נ. סה\"מ תרס\"ה כאן ס\"ע קעח ואילך."],["1380","39","<b>בראשית ברא אלקים</b>: ראה גם לעיל שם רפ\"ב. וש\"נ."],["1381","40","<b>של\"ב פעמים אלקים נא' בע\"מ</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["1382","41","<b>וייצר ה' אלקים</b>: בראשית ב, ז. יט."],["1383","42","<b>נעשה אדם</b>: בראשית א, כו."],["1384","43","<b>ש' אלקים . . הצמצום</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["1385","44","<b>אלקים הוא בחי' אותיות</b>: ראה תו\"א יתרו סט, ד."],["1386","45","<b>שהאותיות מסתירים על השכל</b>: ראה לקו\"ת צו טז, ד. אחרי כח, ד. במדבר ט, ב."],["1387","46","<b>תושב\"כ שאין מושג</b>: ראה זהר בהעלותך קנב, א."]]],[2001910181,"וטעם הדבר בהמשנה כ\"א ע\"י ריבוי יגיעה והיינו ג\"כ מפני שהאותיות מסתירים, כמו\"כ יובן למעלה שש' אלקים הוא בחי' האותיות שזהו מ\"ש גדול הוי' ומהולל מאד בעיר אלקינו<sup data-n=\"1388\">47</sup>, עיר אלקינו הוא בחי' צירופי אותיות הדבור שתי אבנים בונות שתי בתים שלשה אבנים כו' כמ\"ש בס\"י<sup data-n=\"1389\">48</sup>, ומפני שהאותיות מסתירים לכן יכול להיות יש ודבר נפרד, אבל אם הי' ההתהוות רק מש' הוי'<sup data-n=\"1390\">*49</sup> לא היו מתהוים הנבראים בבחי' יש ודבר נפרד כי ש' הוי' הוא בחי' הי' הוה ויהי'<sup data-n=\"1391\">49</sup>, ולכן הגם כי עיקר הבריאה הוא מש' הוי' שש' הוי' הוא מקור כל ההתהוות אעפ\"כ נא' כי הוא צוה ונבראו ממילא כו', אבל בש' אלקי' נא' בראשית ברא אלקים שברא הוא לנוכח בחי' כח הפועל בנפעל<sup data-n=\"1392\">50</sup> כי להיות הבריאה ליש ודבר זהו ע\"י ש' אלקים דוקא כנ\"ל, ומצות לייחדו היינו לייחד ב' השמות ה' ואלקי', וזהו וידעת כו' כי הוי' הוא האלקים כולא חד<sup data-n=\"1393\">51</sup> כי מה שנראה העולם ליש ודבר נפרד זהו לעינינו מצד בחי' ש' אלקים המסתיר כנ\"ל, אבל באמת מצד בחי' ש' הוי' כולא קמי' כלא חשיב<sup data-n=\"1394\">52</sup> והי' והוה ויהי' כא', וזהו מ\"ש אני ראשון ואני אחרון<sup data-n=\"1395\">53</sup> ומבלעדי אין אלקים (אני ראשון לפני ההשתלשלו' ואני אחרון לאחר כל ההשתל' ומבלעדי באמצעיתא<sup data-n=\"1396\">54</sup> אין אלקי' שאינו מסתיר רק לעינינו כו'), וזהו מה יתרון לאדם בכל עמלו שיעמול תחת השמש פי' תחת השמש הוא בחי' שם אלקים, דהנה אף אם יודע בש' אלקים דהיינו ענין הבריאה בראשית ברא אלקים מה יתרון בעמלו שזהו כמו פרעה שאמר לא ידעתי את הוי'<sup data-n=\"1397\">55</sup>, אבל מש' אלקי' ידע שהרי יוסף אמר לו אלקים יענה את שלום פרעה<sup data-n=\"1398\">56</sup>, ומשה הודיע לו גם בחי' ש' הוי' בחי' הי' הוה ויהי' וע\"ז אמר לא ידעתי כו', ועיקר מצות היחוד שנצטוינו ליחדו הוא יחוד ב' השמות כי הוי' הוא האלקים כולא חד בלא פרודא, וז\"ע יציאת מצרים<sup data-n=\"1399\">57</sup> לצאת מהמצרים וגבולים דש' אלקים ולידע שהוי' הוא האלקים כו', וזה הי' כללות ענין המשכן<sup data-n=\"1400\">58</sup> היינו המשכת גילוי ש' הוי' בשם אלקים, הגם כי בברה\"ע הי' ג\"כ ע\"י",[["1388","47","<b>גדול הוי' . . בעיר אלקינו</b>: תהלים מח, ב. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה פיסקא והענין הוא."],["1389","48","<b>שתי אבנים . . כמ\"ש בס\"י</b>: ראה שם פ\"ד, מי\"ב."],["1390","*49","<b>שהאותיות מסתירים . . מש' הוי'</b>: ראה סה\"מ תרס\"ה כאן ס\"ע קעט ואילך."],["1391","49","<b>הוי' . . הי' הוה ויהי'</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["1392","50","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."],["1393","51","<b>הוי' הוא האלקים כולא חד</b>: ראה זהר בהקדמה יב, א. וארא כו, ב. תרומה קסא, א ואילך. רע\"מ ואתחנן רסד, א. מאמרי אדה\"א דברים ח\"א ע' קעה ובהנסמן בריש המאמר שם. תו\"ח וארא ח\"א ס, א. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תה ואילך. וש\"נ. סה\"מ תרס\"ה כאן ס\"ע קפ ואילך."],["1394","52","<b>כולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1395","53","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו. ראה תו\"א מקץ לח, רע\"ד."],["1396","54","<b>ומבלעדי באמצעיתא</b>: ראה ת\"ז ת\"ע קכ, סע\"א. שע\"ת קמו, א ובהנסמן במ\"מ לשם. תו\"ח תצוה ח\"ב שלא, ג."],["1397","55","<b>לא ידעתי את הוי'</b>: שמות ה, ב. ראה לקו\"ת אמור לה, ג. ראה גם לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי פ\"ז ד\"ה דהנה פרעה."],["1398","56","<b>אלקים . . שלום פרעה</b>: מקץ מא, טז."],["1399","57","<b>וז\"ע יציאת מצרים</b>: ראה לקו\"ת שם. סהמ\"צ להצ\"צ כג, ב ואילך."],["1400","58","<b>וזה . . ענין המשכן</b>: ראה לקו\"ת נשא כא, ב ואילך. אוה\"ת בשלח ע' תקסד. ויקהל ריש ע' ב'ריא. במדבר ע' כה. עקב ע' תקיט."]]],[2001910182,"ש' הוי' בש' אלקים, אך הנה ש' אלקים מסתיר על שם הוי' שלכן נתהוה הבריאה שיהי' נראה לעינינו ליש ודבר נפרד, אבל ענין המשכן היינו שיהי' גילוי ש' הוי' בשם אלקי' וש' אלקי' לא יסתיר<sup data-n=\"1401\">59</sup> גם לעינינו, וזהו שלש פעמים בשנה יראה כו' פני האדון הוי' (כי תשא ל\"ד ך\"ג), וארז\"ל כדרך שבא לראות<sup data-n=\"1402\">60</sup> כך בא ליראות, מה לראות בשתי עיניו כו', וכתי' ושאבתם מים בששון<sup data-n=\"1403\">61</sup>, וארז\"ל שמשם שואבים רוה\"ק<sup data-n=\"1404\">62</sup>. ויובן זה ע\"פ מה שפי' רש\"י בחומש ע\"פ ואמלא אותו רוח כו' (תשא ל\"א ג') דעת<sup data-n=\"1405\">63</sup>, רוח הקדש, וממילא מובן שכאשר בצלאל לצורך עשיית המשכן הי' צריך שיהי' לו רוח הקדש, כ\"ש שכאשר נגמר מלאכתו כו' וכבוד ה' מלא את המשכן<sup data-n=\"1406\">64</sup>, וכן בבהמ\"ק שפי' יראה שנז\"ל הוא כדרך שבא לראות כו' מה לראות בשתי עיניו כו' שנת' לקמן<sup data-n=\"1407\">65</sup> שזהו ב' השגחות דיחו\"ע ויחו\"ת, שהם ד\"ע וד\"ת, הרי האיר בחי' ד\"ע בד\"ת שזהו עוד מבחי' היותר גבוה מד\"ע כמשנ\"ת שם, מובן שע\"י מצות ראי', וכן ע\"י שאיבת מים חכ' בששון בינה כמ\"ש בלק\"ת בד\"ה ושאבתם מים בששון השני פ\"ב<sup data-n=\"1408\">66</sup>, שאבו רוח הקדש כו', וזהו יודע הי' בצלאל לצרף אותיות שנבראו בהם שמים וארץ. הנה האלשיך פי' שבצלאל המשיך<sup data-n=\"1409\">67</sup> בחי' ומדריגת בריאת העולמות בהמשכן, לכן הי' צריך לידע האותיות שנבראו בהם שמים וארץ, אבל הה\"מ נ\"ע פי' בהיפך<sup data-n=\"1410\">68</sup> דבאמת מצינו שהמשכן גבוה יותר מבחי' ברה\"ע כמשארז\"ל (כתובות דף ה' ע\"א) גדולים מעשה צדיקים ממעשה<sup data-n=\"1411\">69</sup> שמים וארץ דאלו במעשה שמו\"א כתי' אף ידי יסדה ארץ וימיני טפחה שמים<sup data-n=\"1412\">70</sup> ובמעשה צדיקים<sup data-n=\"1413\">71</sup> כתי' מקדש אד' כוננו ידיך<sup data-n=\"1414\">72</sup> פי' ב' ידות, והגם כי במעשה שמו\"א כתי' ג\"כ ידי וימיני אך הנה ידי יד שמאל יסדה ארץ בפ\"ע וימיני טפחה שמים בפ\"ע, וכמארז\"ל נטה ימינו וברא שמים<sup data-n=\"1416\">74</sup> נטה שמאלו וברא ארץ, אבל במקדש כתי' כוננו ידיך ב' ידות ביחד בחד מעשה<sup data-n=\"1415\">73</sup> כו', והיינו כי המשכן הוא בחי' המשכת ש' הוי' שיהי' גילוי ש' הוי' בש' אלקים, משא\"כ בחי'",[["1401","59","<b>וש' אלקי' לא יסתיר</b>: ראה סה\"מ תרס\"ה כאן ס\"ע קפד ואילך."],["1402","60","<b>כדרך שבא לראות</b>: חגיגה ב, א. ראה תוד\"ה יראה. סה\"מ תרס\"ה כאן ע' קפה."],["1403","61","<b>ושאבתם מים בששון</b>: ישעי' יב, ג."],["1404","62","<b>שמשם שואבים רוה\"ק</b>: ירושלמי סוכה פ\"ה, ה\"א. ב\"ר פ\"ע, ח."],["1405","63","<b>דעת</b>: כ\"ה גם בסה\"מ תרל\"ה ותרס\"ה כאן. בהכתוב: ובדעת."],["1406","64","<b>וכבוד ה' מלא את המשכן</b>: פקודי מ, לד-לה."],["1407","65","<b>שנת' לקמן</b>: פ\"ד פיסקא וזהו."],["1408","66","<b>בלק\"ת . . פ\"ב</b>: סוכות פ, סע\"ב."],["1409","67","<b>האלשיך פי' שבצלאל המשיך</b>: ויקהל לה, י (ד\"ה ואחר אומרו). לו, ח."],["1410","68","<b>הה\"מ נ\"ע פי' בהיפך</b>: ראה אור תורה ר\"פ תצוה [הובא באוה\"ת תשא כרך ח' ע' ג'קג]. בראשית ד\"ה איתא במדרש [ד, ב במהדורת קה\"ת]. לקו\"א סקכ\"ו."],["1411","69","<b>ממעשה</b>: כ\"ה גם בסה\"מ תרל\"ה ותרס\"ה כאן. בכתובות שם: יותר ממעשה."],["1412","70","<b>אף ידי . . שמים</b>: ישעי' מח, יג."],["1413","71","<b>ובמעשה צדיקים</b>: כ\"ה גם בסה\"מ תרל\"ה ותרס\"ה כאן. בכתובות שם: ואילו במעשה ידיהם של צדיקים. ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 57."],["1414","72","<b>מקדש אד' כוננו ידיך</b>: בשלח טו, יז. [בכתובות שם מובאים גם התיבות: מכון לשבתך פעלת ה']."],["1416","74","<b>נטה ימינו וברא שמים</b>: ראה פדר\"א פי\"ח. הנסמן בתו\"א וארא נו, ב בפנים. לעיל שם ובהערה 81."],["1415","73","<b>והגם כי . . בחד מעשה</b>: ראה תוד\"ה דאילו כתובות שם. לקו\"ת נשא כא, ג."]]],[2001910183,"בריאת העולם שהי' ע\"י ש' הוי' וש' אלקים, אבל ש' אלקים מסתיר על אור הוי' עד שנתהוה העולם שנראה ליש ודבר נפרד, וזהו שהי' בצלאל צריך לידע לצרף אותיות שנבראו בהם שמים וארץ כי ע\"י המשכן נמשך ש' הוי' בגילוי בבחי' שם אלקי' שהוא בחי' בריאת העולם לכן הי' צריך לידע לצרף האותיות שנבראו בהם שמים וארץ דהיינו האותיות דש' אלקים<sup data-n=\"1417\">75</sup>, וזהו שנא' בבצלאל ולחשוב מחשבות כו' שהמשכת ש' הוי' הוא ע\"י לחשוב מחשבות.\n(ד) <b>(ואפ\"ל</b> דהנה נת' לעיל<sup data-n=\"1418\">76</sup> ששם אלקים הוא בחי' אותיות הדבור בחי' עיר אלקינו כו', וש' הוי' הוא ג\"כ בחי' אותיות שהרי כתי' אני הוי' הוא שמי<sup data-n=\"1419\">77</sup> רק שהוא ע\"ד אותיות המחשבה<sup data-n=\"1420\">78</sup>, שבלבושי האדם הם אותיות היותר נעלים<sup data-n=\"1421\">79</sup>, לכן כדי שיוכל להמשיך מבחי' ש' הוי' זהו ע\"י לחשוב מחשבות, ועוי\"ל שבנפש שמים הוא בחי' שכל ומחשבה שהם מקיפים לגבי מדות ודבור, שהמח' מקפת הדבור והמחשבה אם<sup data-n=\"1423\">81</sup> היות שהיא לבוש להנפש עכ\"ז היא לבוש הפנימי<sup data-n=\"1422\">80</sup> ומתאחדת עם השכל כהדין קמצא<sup data-n=\"1424\">82</sup> דלבושא מיני' ובי' שהרי הדבור אם ירצה האדם לא ידבר אבל בלא לבוש המח' א\"א שבע\"כ יהרהר כו' כמ\"ש מזה בביאור שובה ישראל הא'<sup data-n=\"1425\">83</sup> בפי' הוי' הוא האלקי' בביאור פי' הראשון, ולכן ע\"י שהי' בצלאל יודע לחשוב מחשבות שז\"ע התדבקות בש' הוי' בחי' סוכ\"ע<sup data-n=\"1426\">84</sup> הי' יכול לעשות המשכן שענינו הוא בחי' המשכת ש' הוי' סוכ\"ע בש' אלקי' וש' אד'<sup data-n=\"1428\">86</sup> בחי'<sup data-n=\"1429\">87</sup> ממכ\"ע<sup data-n=\"1427\">85</sup> ושלא יסתיר בחי' ההסתר דש' אלקים וש' אד' כו'). וזהו בצלאל למטה יהודה ואהליאב למטה דן שמשני שבטים אלו<sup data-n=\"1430\">88</sup> דוקא הי' עשיות המשכן והיינו מפני כי דן הוא בחי' ש' אד'<sup data-n=\"1431\">89</sup>",[["1417","75","<b>צריך לידע . . האותיות דש' אלקים</b>: ראה סה\"מ תרס\"ה כאן ע' קפו."],["1418","76","<b>נת' לעיל</b>: רפ\"ג."],["1419","77","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."],["1420","78","<b>הוי' . . ע\"ד אותיות המחשבה</b>: ראה גם אוה\"ת וארא ע' קצו ואילך."],["1421","79","<b>המחשבה . . אותיות היותר נעלים</b>: ראה תניא פ\"כ ופכ\"א. שהיחוה\"א פ\"ח. אגה\"ק סי\"ט בסופה."],["1423","81","<b>אם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["1422","80","<b>והמחשבה . . לבוש הפנימי</b>: ראה לקו\"ת בהר מא, א. ש\"ש סה, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטז. אתהלך לאזניא ע' ריז."],["1424","82","<b>כהדין קמצא</b>: ראה ב\"ר פכ\"א, ה. תניא פכ\"א ובלקוטי הגהות־ ליקוט פירושים שם. שער היחוה\"א פ\"ז. מאמרי אדה\"א ויקרא ח\"ב ע' תשכא בהערה.\nבשיעורים בספר התניא שם ע' 242 : טשערעפאכע. אבל ראה מ\"מ הגהות והע\"ק לסש\"ב שם: מין חגב. וראה גם לקו\"ש חוקת כרך כג ע' 144 הערה 26 ובשולי היריעה שם."],["1425","83","<b>בביאור שובה ישראל הא'</b>: לקו\"ת ש\"ש סה, ד."],["1426","84","<b>בש' הוי' בחי' סוכ\"ע</b>: ראה לקו\"ת בלק עג, ד. עד, ב. תו\"ח וארא ח\"א עג, ב. וש\"נ."],["1428","86","<b>בשם אלקי' וש' אד'</b>: ראה בסמוך בפנים ובהערה 94."],["1429","87","<b>בשם אלקי' . . בחי' ממכ\"ע</b>: ראה הערה 84."],["1427","85","<b>סוכ\"ע . . ממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["1430","88","<b>שמשני שבטים אלו</b>: ראה לקו\"ת שבהערה 73."],["1431","89","<b>דן . . ש' אד'</b>: ראה הגהות מהרח\"ו לזהר בלק קצז, א."]]],[2001910184,"כי אד' הוא א'<sup data-n=\"1433\">91</sup> דין<sup data-n=\"1432\">90</sup> ויהודה הוא בחי' ש' הוי'<sup data-n=\"1434\">92</sup> כי כל הד' אותיות דש' הוי' נמצאים ביהודה* והיינו שע\"י בצלאל ואהליאב<sup data-n=\"1435\">93</sup> נמשך בחי' ש' הוי' בש' אד' וש' אד' וש' אלקים הכל בחי' אחת<sup data-n=\"1436\">94</sup>. וזהו דכתיב בפ' ויקהל ראו קרא הוי'<sup data-n=\"1437\">95</sup> בשם בצלאל, פי' שבצלאל קרא והמשיך בחי' ש' הוי' בשם דהיינו ש' אד'. והנה זה הי' ע\"י בהמ\"ק ומשכן כו', ועכשיו אנו ממשיכים זה ע\"י הדעת הוא בחי' וידעת היום והשבות אל לבבך כי ה' הוא האלקים כולא חד בלא פרודא כלל, שמה שנראה העולם ליש ודבר נפרד זהו לעינינו אבל באמת כולא קמי' כלא חשיב ממש לגבי ש' הוי' בחי' הי' הוה ויהי' כא' שהוא בחי' ביטול הזמן בעבר הוה ועתיד, וכן הוא ביטול המקום כי שניהם מחודשים מאין ליש<sup data-n=\"1438\">96</sup> כו', ועי\"ז ממשיכים גילוי ש' הוי' בשם אלקים כו'.\n\n*)\n<i>המשך להגהות (ראה לעיל ספ\"א והערה ב) ולא נרשם מקומו בפנים ואולי שייך כאן:</i>\nואולי י\"ל שאות ד' שבתיבת יהודה זהו מש' אד' להורות על בחי' שילוב ש' אד' בהוי'<sup data-n=\"8232\">כא</sup>, וכמ\"ש בלק\"ת בביאור שובה ישראל הא' שזהו כלל בפע\"ח שאות הראשון גובר<sup data-n=\"8233\">כב</sup>, וביהודה ג' אותיות קודם הד', וזהו ע\"י בצלאל המשכת ש' הוי' בש' אד', וש' אד' לא יסתיר כו', ומ\"מ הי' צ\"ל אתו אהליאב משבט דן כי כאן המכוון שיהי' יראה את פני האדון הוי'<sup data-n=\"8234\">כג</sup> כמארז\"ל לראות בשתי עיניו<sup data-n=\"8235\">כד</sup> בחי' יחוד ב' השגחות, ולכן הי' צריכים גם אהליאב משבט דן שזהו ד\"ת, והוא אתו היינו את בצלאל היינו שילוב ש' אד' בהוי', ולא ש' הוי' בש' אד' שאז ש' אד' גובר שמזה נמשך ההסתר כ\"א שילוב ש' אד' בהוי' שיומשך הגילוי במשכן ומקדש כו' וע' לקמן<sup data-n=\"8236\">כה</sup> המובא מלק\"ת מביאור כי תשמע בקול, ובלק\"ת בד\"ה ביאור שובה הנ\"ל.\nאך א\"א לומר כן שהרי יהודה וש' אד' שניהם<sup data-n=\"8237\">כו</sup> במל'<sup data-n=\"8238\">כז</sup>, רק י\"ל שיהודה הוא ע\"ד בחי' ש' אלקי' כמו שנת' בפי' הראשון דהוי' הוא האלקי' שהצמצום הוא בכדי שיוכל להיות ההתהוות, בד\"ה שובה ישראל הראשון<sup data-n=\"8239\">כח</sup>, ולכאורה זהו כמו בבריאת העולם שזהו ג\"כ ע\"י ש' הוי' וש' אלקים, אך המעיין בת\"א ד\"ה וידבר אלקי' וארא<sup data-n=\"8240\">כט</sup> זהו בחי' יחוד הוי' ואלקים, וש' אד' הוא כמו סתם ש' אלקים.\nוע' בסידור בד\"ה אד' שפתי תפתח<sup data-n=\"8241\">ל</sup> ש' אד' א' דין כמדומני שא' ממתיק הדין דאד' ולפ\"ז הי' מתאחד עם משנת\"ל שיהודה זהו כמו שילוב ש' אד' בש' הוי'.",[["1433","91","<b>אד' הוא א' דין</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ה. סידור תפלת ר\"ה רלו, ג. תו\"ח בשלח ח\"א רמד, א. וש\"נ."],["1432","90","<b>דן הוא בחי' . . דין</b>: ראה פסחים ד, א."],["1434","92","<b>ויהודה . . ש' הוי'</b>: ראה סוטה י, ב (ובמהרש\"א שם)."],["1435","93","<b>שע\"י בצלאל ואהליאב</b>: ראה סה\"מ תרס\"ה כאן ע' קפו."],["1436","94","<b>וש' אד' וש' אלקים . . אחת</b>: ראה לקו\"ת שבהערה 83: שם אד' הוא שם אלקים ששניהם בחי' א'. סה\"מ תרכ\"ז ע' מב. וש\"נ. ע' קנו וע' קפב. המשך תער\"ב ח\"א ע' תריט. לקמן מאמר ד\"ה מגילה נקראת ספ\"ג. ד\"ה להבין וכו' בעניו הציץ רפ\"ד. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 50."],["1437","95","<b>בפ' ויקהל ראו קרא הוי'</b>: לה, ל."],["1438","96","<b>שניהם מחודשים מאין ליש</b>: ראה שער היחוד והאמונה פ\"ז ובמ\"מ, הגהות והע\"ק שם. סידור שער החנוכה רעו, א. לקו\"ת ברכה צח, א. בהר מא, ב.\n\n<b>כא</b> )<i>שילוב ש' אד' בהוי':</i> ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. לקו\"ת ש\"ש סה, ד ובהנסמן במ\"מ לשם סד, ב. תו\"ח וארא ח\"א נ, א הערה 32. לקמן מאמר ד\"ה להבין וכו' בענין הציץ רפ\"ג.\n\n<b>כב</b> )<i>כלל בפע\"ח שאות הראשון גובר:</i> כ\"ה בלקו\"ת (סה, ד) שם. ובמ\"מ לשם מציין למ\"ח מסכת או\"א פ\"ג, מ\"ה. ראה גם שער היחוד והאמונה פ\"ז ע' פב. תו\"א מקץ מג, א. סה\"מ תרל\"ב ח\"א ע' סה. לקמן שם.\n\n<b>כג</b> )<i>יראה את פני האדון הוי':</i> תשא לד, כג [בדילוג].\n\n<b>כד</b> )<i>לראות בשתי עיניו:</i> חגיגה ב, א.\n\n<b>כה</b> )<i>וע' לקמן:</i> בפנים על יד הערה 119.\n\n<b>כו</b> )<i>יהודה . . שניהם במל':</i> ראה זהר ויחי מז. א. הנסמן במאמרי אדה\"א בראשית ע' רצט.\n\n<b>כז</b> )<i>וש' אד' . . במל':</i> ראה זהר ויקרא יא, א. מאמרי אדה\"א בראשית ע' קצז. וש\"נ. תו\"ח נח סד, ג הערה 44.\n\n<b>כח</b> )<i>בד\"ה שובה ישראל הראשון:</i> לקו\"ת ש\"ש סד, ג.\n\n<b>כט</b> )<i>בת\"א ד\"ה וידבר אלקי' וארא:</i> וארא נו, סע\"א ואילך.\n\n<b>ל</b> )<i>בסידור בד\"ה אד' שפתי תפתח:</i> תפלת ר\"ה רלז, ב. ראה גם לקו\"ת נצבים נא, סע\"ג."]]],[2001910185,"וזהו גדול מקדש שניתן בין ב' אותיות<sup data-n=\"1439\">97</sup> להיות כי ע\"י בחי' המקדש ממשיכים מבחי' ש' הוי' בשם אד', פי' שגם בבחי' ש' אד' הוא בחי' ד\"ת יהי' ג\"כ גילוי ש' הוי' איך שקמי' כלא חשיב, כי הנה כתי' כי אל דעות<sup data-n=\"1440\">98</sup> הוי'<sup data-n=\"1441\">99</sup> שיש ב' דעות הא' הוא בחי' ד\"ע איך שקמי' כלא חשיב ולא יש שום מציאות כלל זולתו ית' ולמעלה הוא היש האמיתי ולמטה הוא אין, אבל בחי' ד\"ת הוא שהבריאה הוא יש מאין פי' שנתהוה למטה בחי' יש ודבר מאין פי' שאינו נראה ונגלה כו'<sup data-n=\"1442\">100</sup>, ובשם זה של אל כולל ב' הדיעות יחו\"ע ויחו\"ת היינו ד\"ע וד\"ת, להיותו בחי' תיקון הראשון מי\"ג ת\"ד<sup data-n=\"1443\">101</sup> ולכן כולל ב' הדיעות<sup data-n=\"1444\">102</sup> כמ\"ש היוצר יחד לבם<sup data-n=\"1445\">103</sup> המבין אל כל מעשיהם, ולכן מבחי' שם אל זה יכול להיות שגם בבחי' ד\"ת יחו\"ת ביטול היש לאין יומשך בחי' גילוי ש' הוי' שהוא הי' הוה ויהי' כאחד בחי' יחו\"ע איך שקמי' כלא חשיב כי המגביהי לשבת המשפילי לראות<sup data-n=\"1446\">104</sup> בשמים ובארץ בשוה. וע\"ד דוגמא מה שמצינו בזהר באד\"ר דקל\"ב א' בענין תלת עלמין דנפקי<sup data-n=\"1448\">106</sup> מתקונא קדמאה כו' שהתלת",[["1439","97","<b>גדול מקדש שניתן בין ב' אותיות</b>: ברכות לג, א — נסמן לעיל פ\"א בפנים."],["1440","98","<b>כי אל דעות</b>: ראה להבא בסמוך תו\"א יתרו סח, ד ד\"ה וזהו."],["1441","99","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11."],["1442","100","<b>שאינו נראה ונגלה כו'</b>: ראה סה\"מ תרס\"ה כאן ע' קפז."],["1443","101","<b>אל . . תיקון הראשון מי\"ג ת\"ד</b>: ראה זהר אד\"ר נשא קלא, ב. לקו\"ש אלול כרך ד ע' 1348 ואילך."],["1444","102","<b>ולכן כולל ב' הדיעות</b>: ראה סה\"מ תרס\"ה כאן."],["1445","103","<b>היוצר יחד לבם</b>: תהלים לג, טו."],["1446","104","<b>המגביהי לשבת המשפילי לראות</b>: תהלים קיג, ה. ו."],["1448","106","<b>דנפקי</b>: וכ\"ה סה\"מ תרל\"ה ותרס\"ה כאן. בתו\"א: דנפיק. ובהערות ותיקונים לשם [נראה לי בדרך אפשר] דנפקין. וכ\"ה בלקו\"ת שה\"ש כג, א. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 84 [ושם: נפקין]. אבל בלקו\"ת אמור לט, א כבתו\"א."]]],[2001910186,"עלמין הם ג' עולמות בי\"ע<sup data-n=\"1449\">*107</sup> והם נמשכים מהתיקון הראשון די\"ג ת\"ד<sup data-n=\"1447\">105</sup> שהוא בחי' מי אל כמוך<sup data-n=\"1450\">107</sup>, ולכאו' יפלא<sup data-n=\"1452\">109</sup> איך יהי' דילוג המדרגה כ\"כ<sup data-n=\"1453\">110</sup> מבחי' י\"ג ת\"ד דא\"א מקור כל<sup data-n=\"1454\">111</sup> האצי' שיומשך מזה ג' עולמות בי\"ע, אך הענין הוא דהיא הנותנת שכדי<sup data-n=\"1455\">112</sup> שיבא האור עד למטה כ\"כ בעולמות בי\"ע צריך שיבא ממקום הנעלה ביותר<sup data-n=\"1456\">113</sup> כי לעוצם הרוממות יוכל להשפיל א\"ע למטה יותר כו', ולכן כדי<sup data-n=\"1457\">114</sup> שיהי' התהוות ג'<sup data-n=\"1458\">115</sup> עולמות בי\"ע הוא<sup data-n=\"1459\">116</sup> דוקא ע\"י ההמשכה מתיקון הראשון די\"ג ת\"ד<sup data-n=\"1451\">108</sup> כו'. ועד\"ז יובן כאן<sup data-n=\"1460\">117</sup> שלהיות ההמשכה במשכן ובמקדש בחי' ש' הוי' בחי' ד\"ע בגילוי בש' אד' בחי' ד\"ת, להיות הגילוי ע\"י המשכן ומקדש שיגיע לכ\"א בחי' הארת ש' הוי' להיות יראה כל זכורך<sup data-n=\"1461\">118</sup> כדרך שבא לראות כך בא ליראות, מה לראות בשתי עיניו של מקום כו' שפי' בלק\"ת פ' ראה<sup data-n=\"1462\">119</sup> בביאור הדברים בד\"ה כי תשמע בקול ובהג\"ה שם שזהו ב' השגחות דיחו\"ע ויחו\"ת, ונת' שם בהג\"ה שכדי להיות יחוד ב' השגחות שיהי' ביחו\"ת כמו ביחו\"ע זהו תכלית ועיקר מכוון הבריאה, וזהו עדיף מבחי' השגחה דיחו\"ע עצמה והיינו שזהו ע\"י המקדש מה לראות בשתי עיניו כו', ועוד פי' שם שכדי להיות ביחו\"ת הגילוי כמו ביחו\"ע זהו ע\"י המשכה מלמעלה מב' הבחי' דיחו\"ע ויחו\"ת, וי\"ל שזהו שם אל הכולל ב' הבחי' יחד, וע\"ד קורא אני עליהם<sup data-n=\"1463\">120</sup> יעמדו יחדיו, וע' במק\"מ בפי' הזח\"א דף ב' סע\"א ששם אל שבבצלאל הוא המסייע לבצלאל, ולכן בצלאל שיש ש' אל בשמו<sup data-n=\"1464\">121</sup> קרא והמשיך ש' הוי' יחו\"ע בשם היינו ש' אלקים ושם אד' היכל גימ' אד'<sup data-n=\"1465\">122</sup> כו', והכח ע\"ז הי' מפני שיש שם אל בשמו, ועכשיו ממשיכים זה ע\"י הדעת, וזהו כוונת אמרם ז\"ל גדולה דיעה שניתנה<sup data-n=\"1466\">123</sup> בין שתי אותיות אל דעות הוי', שע\"י הדעת כי הוי' הוא האלקי' כולא חד עי\"ז ממשיכים ש' הוי' כמו במקדש שקראו את השם ככתבו<sup data-n=\"1467\">124</sup> מפני שהאיר שם ש' הוי', וכן הוא עכשיו ע\"י הדעת, ולכן במקדש שם הא' ש' הוי' והשני ש' אד' לרמז על",[["1449","*107","<b>שהתלת עלמין . . בי\"ע</b>: ראה לקמן בהנחה כאן ובהערה 85 בשם הרמ\"ז."],["1447","105","<b>באד\"ר . . די\"ג ת\"ד</b>: לשון התו\"א יתרו סח, ד בשינוים."],["1450","107","<b>מהתיקון הראשון . . מי אל כמוך</b>: מיכה ז, יח. בתו\"א: כמוך כו'."],["1452","109","<b>ולכאו' יפלא</b>: שם: וזה פליאה לכאורה."],["1453","110","<b>כ\"כ</b>: שם ליתא."],["1454","111","<b>כל</b>: שם ליתא."],["1455","112","<b>דהיא הנותנת שכדי</b>: שם: משום דאדרבה כי כדי."],["1456","113","<b>שכדי שיבא . . למטה . . הנעלה ביותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["1457","114","<b>כדי</b>: בתו\"א ליתא."],["1458","115","<b>ג'</b>: שם ליתא."],["1459","116","<b>הוא</b>: שם שהוא."],["1451","108","<b>די\"ג ת\"ד</b>: בתו\"א: מי\"ג ת\"ד דא\"א דאצי'."],["1460","117","<b>ועד\"ז יובן כאן</b>: ראה סה\"מ תרס\"ה כאן."],["1461","118","<b>יראה כל זכורך</b>: תשא לד, כג."],["1462","119","<b>בלק\"ת פ' ראה</b>: כד, א."],["1463","120","<b>קורא אני אליהם</b>: ישעי' מח, יג."],["1464","121","<b>בצלאל שיש ש' אל בשמו</b>: ראה (בנוסף להמק\"מ) לקמן בפנים שמציין לזהר תרומה קנב, א. זהר בהקדמה ב, סע\"א. לעיל רפ\"ב מברכות נה, א."],["1465","122","<b>היכל גימ' אד'</b>: ת\"ז תי\"ח (לב, א. לג, ב). ז\"ח יתרו לד, א. וראה גם לעיל מאמר ד\"ה והי' אור הלבנה פ\"ג. וש\"נ."],["1466","123","<b>גדולה דיעה שניתנה</b>: ברכות לג, א."],["1467","124","<b>במקדש שקראו את השם ככתבו</b>: תמיד פ\"ז, מ\"ב."]]],[2001910187,"ההמשכה מש' הוי' לשם אד' וש' אד' לא יסתיר כ\"א שגם לעינינו יושג בחי' ד\"ע, ובדיעה שם הא' הוא שם אל והשני ש' הוי' לרמז שכדי שיומשך ד\"ע בד\"ת ש' הוי' בש' אד' בגילוי זהו ע\"י שם אל שכולל ב' הדיעות וי\"ל שז\"ע בצלאל בצל אל כמ\"ש בזח\"ב פ' תרומה דקנ\"ב סע\"א בצל אל ההוא דאקרי אל עליון, ועמ\"ש בענין אל עליון גומל חסדים טובים בביאור ע\"פ אלה מסעי השני שבלק\"ת פ\"ג<sup data-n=\"1468\">125</sup> דהיינו שהיסוד מושך השפע מהבינה ומבחי' כתר, ולכן בצלאל בחי' יסוד<sup data-n=\"1469\">126</sup> קרא ה' בשם ש' אד'. ובזה יובן מאמר המד\"ר הנ\"ל שהראה הקב\"ה למשה בספרו של אדה\"ר, שפי' ספרו של אדה\"ר<sup data-n=\"1470\">127</sup> הוא ע\"ד שנת' במ\"א* בפי' קורא הדורות מראש<sup data-n=\"1471\">128</sup> היינו מבחי' א\"ק אור כללי<sup data-n=\"1472\">129</sup> בחי' מחשבה הקדומה<sup data-n=\"1473\">130</sup> כו', ואפ\"ל שז\"ע מה שא\"ל משה בצל אל היית שי\"ל שזהו בחי' מח' הקדומה, שהו\"ע בחי' צל בחי' מקיף כו' היית וידעת, ועכשיו זהו ע\"י מצות ליחדו שזהו ע\"י הדעת והכרה שהוי' הוא האלקים בשמים ממעל סוכ\"ע וארץ מתחת בחי' ממכ\"ע, עי\"ז והשבות אל לבבך כמו ואהבת בכל לבבך ע\"י שמע ישראל כו'.\n\n*)\n<i>בצד הימיני של העמוד נרשם:</i>\nכ\"פ בס' שמות ח\"ג דקל\"ב ע\"א בד\"ה ראה קראתי<sup data-n=\"8242\">לא</sup>.",[["1468","125","<b>בביאור ע\"פ אלה מסעי השני שבלק\"ת פ\"ג</b>: צ, ג."],["1469","126","<b>בצלאל בחי' יסוד</b>: ראה זהר המובא בפנים (ובאוה\"ת שמות ע' לד. ויקהל כרך ז ע' ב'תתא). ויקהל ריד, סע\"ב (ובאור החמה שם). שלח קסב, ב (ובמק\"מ שם). מאו\"א מערכת בצלאל אות ס. אוה\"ת ויקהל ע' ב'רטו. תשא כרך ח ע' ג'קג ואילך."],["1470","127","<b>ספרו של אדה\"ר</b>: ראה גם אוה\"ת בראשית כרך ג' ע' 1180."],["1471","128","<b>קורא הדורות מראש</b>: ישעי' מא, ד. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתיא. ע' תתפח. קונטרסים ע' תלב."],["1472","129","<b>א\"ק אור כללי</b>: ראה אוה\"ת ענינים ע' פד (בלק ע' תתקסח): ”כן אמר רבינו הגדול נ\"ע בשם הרב המגיד דמעזריטש נ\"ע שהי' מרגלא בפומי' דבחי' א\"ק הוא אור כללי\" (סהמ\"צ להצ\"צ ע' 116. ע' סח. ע' 186) ”וכן מצאתי ג\"כ בפירוש לתלמיד ר' ישראל סרוג תלמיד האריז\"ל\"."],["1473","130","<b>א\"ק . . מחשבה הקדומה</b>: ראה תו\"א משפטים עח, ב. מאמרי אדה\"ז מארז\"ל ס\"ע קלז. מאמרי אדה\"א דברים ח\"ג ס\"ע תתפז ואילך ובהנסמן שם ובע' תתפח.\n\n<b>לא</b> )בס' שמות . . ראה קראתי: כנראה אוה\"ת תשא ע' א'תתקנ."]]],[2001910188,"<h3>כי תשא את ראש בנ\"י</h3>\n<b>פ' ויקהל, פ' שקלים</b>\n<b>כי</b> תשא<sup data-n=\"1474\">1</sup> את ראש בנ\"י כו' ונתנו איש כפר נפשו לה'<sup data-n=\"1475\">2</sup> כו' זה יתנו כל העובר על הפקודים מחצית השקל בשקל הקדש עשרים כו' מחצית השקל תרומה לה'<sup data-n=\"1476\">3</sup>, וצ\"ל מה\"ע אומרו עשרים גרה השקל וחיוב הנתינה הוא המחצה איזהו תועלת יצא לנו מה שמספר לנו ששקל שלם הוא עשרים גרה, מאחר שחיוב הנתינה הוא רק המחצה הצ\"ל כמה הוא המחצה לבד. והענין הוא דהנה כתי' וייצר ה' אלקים את האדם<sup data-n=\"1477\">4</sup>, וארז\"ל וייצר בתרין יצרין<sup data-n=\"1478\">5</sup> ביצ\"ט וביצה\"ר וז\"ע ב' יודי\"ן שבתיבת וייצר, והנה נודע כי עיקר ירידת הנשמה בגוף הוא בשביל בירור הנה\"ב שהוא היצה\"ר כי הנשמה מצד עצמה אינה צריכה תיקון<sup data-n=\"1479\">6</sup> כלל כ\"א כל ירידתה הוא בשביל בירור נה\"ב, וזהו אומרו עשרים גרה השקל, פי' הגם כי שקל שלם הוא עשרים גרה דהיינו השני יודי\"ן דוייצר שהם היצ\"ט ויצה\"ר והיינו שהיצה\"ר ישתוה ליצ\"ט, כי הצדיקים ע\"י עבודתם מהפכים היצה\"ר ג\"כ לטוב, וע\"ד שארז\"ל טוב מאד זה יצה\"ר<sup data-n=\"1480\">7</sup>, מ\"מ איני מבקש מכם כ\"א המחצה לבד דהיינו בירור נה\"ב ע\"ד אתכפיא לבד שא\"א לחשוב את היצה\"ר שנתברר להיות ע\"ד טוב מאד שהרי הרע עדיין לא נתברר אלא שמסגף א\"ע מבלי לעשות נגד התורה והמצוה כו' מ\"מ הריני מחשב זה לפדיון נפשו שיהי' כופר נפשו לה', ולכן פי' ברע\"מ פ' תרומה דקנ\"ח ב' שמחצית השקל הוא בינוני, והיינו כי הבינוני אינו כמעלת הצדיקים גמורים שהפכו היצה\"ר להיות ע\"ד טוב מאד מ\"מ מאחר שפעלו ע\"י עבודתם להיות בבחי' אתכפיא עכ\"פ ה\"ז נחשב כופר נפשו לה', וסוף כל סוף יבא לבחי' אתהפכא.",[["1474","1","<b>כי תשא</b>: מאמר זה הוא הדרוש זה יתנו שנדפס בסה\"מ תרל\"ד ע' קכז ואילך. וש\"נ. בהוספת פסוק בתחילתו. ועוד. בסה\"מ תרל\"ד שם ע' קלא-קלב בסיום המאמר נדפסה פיסקא נוספת וכן קיצור מהמאמר.\nהמאמר בשינויים וכו' נדפס בסה\"מ תרנ\"א ע' קיט ואילך [ושם ע' קכא מציין להגהות שנדפסו כאן ”עמ\"ש בהגהות לד\"ה כי תשא בס' רמ\"א דע\"א\". ובע' קכא מציין להמאמר]. תרפ\"ה ע' קסו וס\"ע קעו ואילך.\nההגהות באו בע' עא ואילך בכותרת: ”זה ל\"נ ולה\"ע\" [לא נאמר ולא הועתק] והם ארבע הגהות, והם: והנה עיקר. שה פזורה. גם י\"ל. זה משה. ע' עב בכותרת: ”לד\"ה זה יתנו\" [היינו הוראה להמעתיק, כשיעתיק המאמר זה יתנו יעתיק גם את זה]. ”ז\"נ והועתק\". וציין כ\"ק אדמו\"ר מהר\"ש עד איפה להעתיק. והחלק שלא הועתק נדפס בשולי היריעה להלן במקומו.\nהכותרת שבריש המאמר נעתקה מבוך תרמ\"א 2086 — כת\"י מעתיק —. אבל ההגהות הנ\"ל לא נעתקו שם.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו."],["1475","2","<b>כי תשא את ראש . . נפשו לה'</b>: תשא ל, יב."],["1476","3","<b>זה יתנו . . תרומה לה'</b>: תשא שם, יג."],["1477","4","<b>וייצר . . את האדם</b>: בראשית ב, ז. ראה בהבא בסמוך אוה\"ת תשא ע' א'תתקז ס\"ג."],["1478","5","<b>וייצר בתרין יצרין</b>: ראה זהר תזריע מו, ב. ברכות סא, א . תרגום יוב\"ע שם. אוה\"ת בראשית כרך ג ע' 1044 ואילך."],["1479","6","<b>הנשמה . . אינה צריכה תיקון</b>: ראה תניא פל\"ז (מח, ב). לקמן מאמר ד\"ה וידעת היום על יד הערה 32 ואילך. מאמרי אדה\"א בראשית ע' עד. וש\"נ. קונטרסים ע' שעח. וש\"נ. שע\"ת קמא, ב."],["1480","7","<b>טוב מאד זה יצה\"ר</b>: ראה ב\"ר פ\"ט, ז [ושם דורש מתיבת והנה]. סה\"מ תרל\"ח ע' עט. וראה גם לעיל מאמר ד\"ה ובירך את לחמך ובהערה 95."]]],[2001910189,"<b>כי</b> הנה כל משפטי התורה הוא בענין בירור נה\"ב, וזהו שאה\"כ על כל דבר פשע על שור ועל חמור<sup data-n=\"1481\">8</sup> כו', פי' על שור קאי על נה\"ב ששרשו מפני שור<sup data-n=\"1482\">9</sup> שבמרכבה שהוא בבחי' התלהבות, וכשנפל למטה יכול להיות מזה שור נגח הוא<sup data-n=\"1483\">10</sup>, שופך דם האדם באדם<sup data-n=\"1484\">11</sup>, וכן כל הכועס<sup data-n=\"1485\">12</sup> כו' שהוא בחי' התלהבות ולהיטת הלב על שכנגדו המעכבו למלאות תאוות יצרו הרע המסיתו ומדיחו מדרך הטוב.\n<b>על</b> חמור הוא כמארז\"ל חמרא אפי' בתקופת תמוז קרירא לי'<sup data-n=\"1486\">13</sup>, פי' בתקופת תמוז שהשמש זורח בתוקף<sup data-n=\"1487\">14</sup> מ\"מ קרירא לי', והיינו הגם שמתבונן בענין מ\"ש שמש ומגן ה' אלקים<sup data-n=\"1488\">15</sup> כו', אשר מבחי' התבוננות זו צ\"ל בבחי' רצוא ותשוקה לאלקות להיות ואהבת את הוי' שיהי' בבחי' אלקיך<sup data-n=\"1489\">16</sup> כו', מ\"מ הוא בבחי' הקרירות ואינו מתפעל כלל, א\"נ חמור ע\"ד (יחזקאל ך\"ג ד'<sup data-n=\"1490\">17</sup>) בשר חמורים, וזרמת כו', שזהו מחמת תאוות זרות כו'.\n<b>על</b> שה הוא בחי' שה פזורה<sup data-n=\"1491\">18</sup>, וזהו טענת המן ישנו עם אחד מפוזר<sup data-n=\"1492\">19</sup>, פי' הגם שהיותם הוא מבחי' אחד, וכתי' גוי אחד בארץ<sup data-n=\"1493\">20</sup> שע\"י העבודה בתומ\"צ",[["1481","8","<b>על כל דבר . . ועל חמור</b>: וכ\"ה בסה\"מ תרל\"ד ותרנ\"א כאן. משפטים כב, ח [ושם: על. וכ\"ה בסמוך בפנים].\nראה גם בהבא להלן (בנוסף להערה 1) אוה\"ת משפטים ע' א'עו ואילך. האזינו ע' א'תרסו. סה\"מ תרל\"ד ע' קצב ואילך. תרפ\"ט ע' 157 ואילך. סה\"ש תש\"ד ע' 104-105. לקו\"ש משפטים ח\"א ע' 155 ואילך."],["1482","9","<b>נה\"ב ששרשו מפני שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תר\"ם ח\"ב ע' תקפ. וש\"נ. לקמן מאמר ד\"ה וידעת היום על יד הערה 13 ואילך."],["1483","10","<b>שור נגח הוא</b>: משפטים כא, לו. ראה לקו\"ת ויקרא ב, ד."],["1484","11","<b>שופך דם האדם באדם</b>: נח ט, ו."],["1485","12","<b>כל הכועס</b>: ראה שו\"ע אדה\"ז חאו\"ח סקנ\"ו, ס\"ג. מאמרי אדה\"א דברים ח\"ב ע' שצג. וש\"נ.\nבסה\"מ תרפ\"ט [שבהערה 8]: וכמא' כל הכועס כאלו שופך דמים — ראה גם ספר חסידים סתרנ\"ה הובא בראשית חכמה שער הענוה פ\"ה [רכט, א ד\"ה עוד הסבות]. הר\"ח הועתק בשל\"ה שער האותיות אות ר קז, ב. מדרש תלפיות אות כ ענף כעס."],["1486","13","<b>חמרא אפי' בתקופת תמוז קרירא לי'</b>: שבת נג, א. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שלה. מארז\"ל ע' נט. אוה\"ת שמע\"צ ע' א'תתטז. סה\"מ תר\"ם ח\"א ע' שצח. וש\"נ."],["1487","14","<b>שהשמש זורח בתוקף</b>: ראה גם לקו\"ש יב-יג תמוז כרך יח ע' 310 ואילך."],["1488","15","<b>שמש ומגן ה' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. תו\"א ויצא כא, ד. תו\"ח ח\"ש קכח, סע\"ב ואילך. ויצא קסז, ג ואילך. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך. לעיל מאמר ד\"ה ראה קראתי בשם פ\"ב ואילך."],["1489","16","<b>ואהבת את הוי' . . אלקיך</b>: ואתחנן ו, ה. ראה תו\"א תצוה פב, רע\"ג. לקו\"ת שה\"ש מב, ב."],["1490","17","<b>ד'</b>: בסה\"מ תרל\"ד כאן: ך."],["1491","18","<b>שה פזורה</b>: ירמי' נ, יז. ראה גם לקמן בשולי הגליון ד\"ה שה פזורה."],["1492","19","<b>ישנו עם אחד מפוזר</b>: אסתר ג, ח."],["1493","20","<b>גוי אחד בארץ</b>: שמו\"ב ז, כג. דברי הימים-א יז, כא."]]],[2001910190,"ממשיכים בחי' אחד גם בארץ<sup data-n=\"1494\">21</sup> בבחי' טורי דפרודא<sup data-n=\"1495\">22</sup> ג\"כ כמ\"ש ואספת דגנך<sup data-n=\"1496\">23</sup> בפ' שני' דק\"ש שז\"ע מה שאוספים כל דברים הגשמיי' ג\"כ לאלקות, והוא ע\"י עשה תורתך קבע<sup data-n=\"1497\">24</sup> ומלאכתך עראי, מ\"מ טענת המן הי' שהם מפוזר ומפורד כו', והיינו בין רבות מחשבות הטורדות ומעכבות, וה\"ז מעכב מ\"ש ואגודתו על ארץ יסדה<sup data-n=\"1498\">25</sup> בחי' אגודה א'*, כהנים לוים וישראלים כ\"א מפוזר ומפורד במחשבות זרות כו'.\n\n*)\n<i>נרשם בשולי היריעה:</i>\nוהנה עיקר פי' ואגודתו להיותו בבחי' התכללות בבחי' ביטול כמו ביעקב דכתי' ע' נפש<sup data-n=\"8243\">א</sup> שהגם שהיו ע' עכ\"ז נא' נפש לשון יחיד<sup data-n=\"8244\">ב</sup>, לפי שהיו יוצאי ירך יעקב יו\"ד עקב<sup data-n=\"8245\">ג</sup> שנמשך היו\"ד בבחי' עקביים, ויש להם ביטול, לכן יכולים להתאחד ולהתכלל, וע' מזה בד\"ה ולקחתם אגודת אזוב<sup data-n=\"8246\">ד</sup>, גם כהנים לוים וישראלים בלק\"ת ד\"ה כי ההרים ימושו פ\"ג<sup data-n=\"8247\">ה</sup> נק' ואגודתו, גם כענין ברכת הזימון בשלשה אומר נברך<sup data-n=\"8248\">ו</sup>, ובעשרה אומרים קדושה<sup data-n=\"8249\">ז</sup>, ובאדם אחד י\"ל ענין האגודה הוא בחי' התכללות חג\"ת, אהוי\"ר ורחמים, ג' קווין תורה ועבודה וגמ\"ח<sup data-n=\"8250\">ח</sup>, ועשרה הוא בחי' עשר כוחות<sup data-n=\"8251\">ט</sup> הנפש<sup data-n=\"8252\">י</sup> שכ\"ז בעבודה יוכל גם האחד לבא לזה, (אך מ\"מ אינו רשאי לומר קדושה או לזמן ברכת הזימון בינו לבין עצמו<sup data-n=\"8253\">יא</sup>, כ\"א כשהוא בשלשהו או בעשרה דוקא), מ\"מ לפמשנ\"ת כאן י\"ל ואגודתו זהו כשמקשר מחדומ\"ע לאלקות, וזהו עצמו ענין תורה ועבודה וגמ\"ח<sup data-n=\"8254\">יב</sup> עבודה הוא בחי' עבודת הקרבנות<sup data-n=\"8255\">יג</sup> שעכשיו תפלה במקום קרבנות<sup data-n=\"8256\">יד</sup> שכשם שבהקרבן הי' פוסל מחשבת חוץ<sup data-n=\"8257\">טו</sup> כן התפלה<sup data-n=\"8258\">טז</sup> צ\"ל בבחי' דביקות לאלקות בחי' רעו\"ד<sup data-n=\"8259\">יז</sup>, ודבור הוא בחי' דבור התורה<sup data-n=\"8260\">יח</sup>, ומעשה הוא בחי' מעשה המצות, והנה טענת המן הי' הגם כי באמת הם מבחי' אחד שממשיכים בחי' אחד גם בארץ, ע\"י הביטול כד אמליכתי'<sup data-n=\"8261\">יט</sup> למעלה ולמטה ולד' רוחות כו' נמשך בחי' אחד גם בארץ, אך לאחר התפילה הם בבחי' שינה, וזהו ישנו שהם בבחי' שינה<sup data-n=\"8262\">כ</sup> וגם מפוזר ומפורד במחשבות זרות, אך כ\"ז הוא מנה\"ב וצריך להסיח דעת מהם כמ\"ש בסש\"ב פך\"ח.\nשה פזורה, שה ביטול בטבע<sup data-n=\"8263\">כא</sup>, אהבה מוסתרת, עכ\"ז היא פזורה, אמנם יש מפזר ונוסף עוד<sup data-n=\"8264\">כב</sup>.\nגם י\"ל<sup data-n=\"8265\">כג</sup> הוא ר\"ת הוא ושמו אחד<sup data-n=\"8266\">כד</sup> כמ\"ש במ\"א בפי'<sup data-n=\"8267\">כה</sup> עד שלא נברה\"ע הי' הוא ושמו בלבד<sup data-n=\"8268\">כו</sup>.\nזה משה<sup data-n=\"8269\">כז</sup> י\"ל מפני שמשה אמר בפ' יתרו כי יהי' להם דבר<sup data-n=\"8270\">כח</sup> בא אלי.",[["1494","21","<b>אחד גם בארץ</b>: ראה תו\"א וישב כז, סע\"ד. לקו\"ת שלח נא, ד. סה\"מ תרכ\"ז ס\"ע רפד ואילך. וש\"נ. תרכ\"ט ע' רכח. וש\"נ. פלח הרמון אמור ע' שעה. וש\"נ. לקמן מאמר ד\"ה [נקדישך] וביאור הענין בסופו. ד\"ה כי תבואו וכו' ושבתה הארץ רפ\"ה. ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום ספ\"א. ד\"ה כל אשר חפץ ה' עשה בסופו. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 29. הנחה ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 82. (בחלק ההנחות) הנחה ד\"ה בעשרה מאמרות נברא העולם בסופה."],["1495","22","<b>טורי דפרודא</b>: זהר בראשית כט, ב. ויצא קנח, א. פקודי רלד, סע\"א. ראה גם לקמן מאמר ד\"ה להבין וכו' זאת תהי' תורת המצורע הערה 94."],["1496","23","<b>ואספת דגנך</b>: עקב יא, יד. ראה גם לעיל מאמר ד\"ה במשנה וכו' ר' נהוראי אומר ספ\"ב. וש\"נ."],["1497","24","<b>עשה תורתך קבע</b>: רמב\"ם הל' ת\"ת פ\"ג, ה\"ז. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י רפ\"ד. וש\"נ."],["1498","25","<b>ואגודתו על ארץ יסדה</b>: עמוס ט, ו.\n\n<b>א</b> ) <b>ביעקב דכתי' ע' נפש</b>: ויגש מו, כז.\n\n<b>ב</b> ) <b>נפש ל' יחיד</b>: ראה ויק\"ר פ\"ד, ו. רש\"י ויגש מו, כו. סה\"מ תרל\"ג ח\"ב ע' תקלד בשם הה\"מ. תרכ\"ז ע' ריח. שע\"ת עג, ד ובהערה 87.\n\n<b>ג</b> ) <b>יעקב יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ.\n\n<b>ד</b> ) <b>בד\"ה ולקחתם אגודת אזוב</b>: סה\"מ תרכ\"ז ע' ריח ואילך.\n\n<b>ה</b> ) <b>בלק\"ת . . פ\"ג</b>: תצא מ, ד.\n\n<b>ו</b> ) <b>בשלשה אומר נברך</b>: ברכות פ\"ז, מ\"ג (מט, ב). ראה סידור שער בהמ\"ז קב, א ואילך. אוה\"ת עקב ע' תקלח ואילך. סה\"מ תרכ\"ו ע' ריח. לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך על יד הערה 108 ואילך.\n\n<b>ז</b> ) <b>ובעשרה אומרים קדושה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סנ\"ה, ס\"ב. ראה גם אוה\"ת (יהל אור) תהלים ע' תרלו.\n\n<b>ח</b> ) <b>חג\"ת . . תורה ועבודה וגמ\"ח</b>: ראה גם תו\"א תשא קיב, ב. לקו\"ת בשלח א, ג. תו\"ח פקודי ח\"ב שפב, ד ובהנסמן שם.\n\n<b>ט</b> ) <b>ועשרה . . עשר כוחות הנפש</b>: ראה גם לקו\"ש ח\"ב י\"ט כסלו ע' 477 ואילך. סה\"ש תשמ\"ח ח\"א ע' 81 הערה 34.\n\n<b>י</b> ) <b>עשר כוחות הנפש</b>: ראה תו\"א תולדות יט, א. תניא פ\"ג.\n\n<b>יא</b> ) <b>אינו רשאי . . לבין עצמו</b>: ראה גם סה\"מ תרכ\"ו ריש ע' ריט.\n\n<b>יב</b> ) <b>מחדומ\"ע . . תורה ועבודה וגמ\"ח</b>: ראה גם סה\"מ תר\"ל ס\"ע שטו ואילך. תרל\"ב ח\"א ע' קנב. פלח הרמון אחרי ע' קפד.\n\n<b>יג</b> ) <b>עבודה . . עבודת הקרבנות</b>: ראה אבות פ\"א, מ\"ב ובמפרשים שם. סה\"מ תרל\"ח ע' לד הערה 79.\n\n<b>יד</b> ) <b>תפלה במקום קרבנות</b>: ברכות כו, א-ב. ראה לקו\"ת פינחס עז, ג. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג.\n\n<b>טו</b> ) <b>שבהקרבן . . מחשבת חוץ</b>: ראה רמב\"ם הל' פסולי המוקדשין רפי\"ג. סה\"מ תר\"ם ח\"א ע' רצד. וש\"נ.\n\n<b>טז</b> ) <b>כן התפלה</b>: ראה גם סה\"מ תר\"ל־ תרל\"ב ופלח הרמון שם.\n\n<b>יז</b> ) <b>רעו\"ד</b>: זהר וירא ק, א.\n\n<b>יח</b> ) <b>ודבור. . דבור התורה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. תו\"ח וארא ח\"א פ, ג. וש\"נ.\n\n<b>יט</b> ) <b>כד אמליכתי'</b>: ראה ברכות יג, ב. אמרי בינה פתח השער בתחילתו. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י פ\"א ואילך.\n\n<b>כ</b> ) <b>ישנו . . שינה</b>: ראה מגילה יג, ב. וראה גם סה\"מ תר\"ם ח\"א ע' שסא.\n\n<b>כא</b> ) <b>שה ביטול בטבע</b>: ראה לקו\"ת אמור לז, סע\"א. לח, רע\"ד.\n\n<b>כב</b> ) <b>יש מפזר ונוסף עוד</b>: משלי יא, כד. ראה גם תו\"א וישב כו, ג ואילך.\n\n<b>כג</b> ) <b>גם י\"ל</b>: ראה לקמן בפנים פיסקא על כל אבידה.\n\n<b>כד</b> ) <b>הוא ר\"ת . . אחד</b>: נסמן לקמן הערה 42.\n\n<b>כה</b> ) <b>כמ\"ש במ\"א בפי'</b>: ראה אוה\"ת יתרו ע' תתלד. הנסמן בתניא ליקוט פירושים בהקדמת שער היחוד והאמונה עה, סע\"ד (ע' כח ד\"ה הוא).\n\n<b>כו</b> ) <b>עד שלא . . ושמו בלבד</b>: ראה פדר\"א פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6.\n\n<b>כז</b> ) <b>זה משה</b>: ראה לקמן בפנים פיסקא וזהו עד.\n\n<b>כח</b> ) <b>כי יהי' להם דבר</b>: נסמן לקמן הערה 50."]]],[2001910191,"ועל שלמה הוא כי תמורת שצ\"ל וריח שלמותיך כריח הלבנון<sup data-n=\"1499\">26</sup> (שה\"ש ד' י\"א) ריחא דלבושייכו<sup data-n=\"1500\">27</sup>, ריח בגדיו<sup data-n=\"1501\">28</sup>, הנה הוא יש בבחי' ההיפוך ג\"כ כמ\"ש (ישעי' ך\"ד י\"ו) ובגד בוגדי' בגדו כו' לבושים צואים.\n<b>על</b> כל אבידה פי' שע\"י כל הנ\"ל ח\"ו יכול לאבד את ניצוץ האלקי אשר בקרבו כו' שמזה נמשך להיות אשר יאמר עליו כי הוא זה ע\"ד שמים אור לחשך וחשך לאור<sup data-n=\"1502\">29</sup> (ישעי' ה' ך') ופי' הוא היינו בחי' חשך כמ\"ש הוא הי' גבור ציד<sup data-n=\"1503\">30</sup>, משא\"כ זה בחי' אור וגילוי, גם היצה\"ר נק' הוא וע\"ז אמרו המרגלים כי חזק הוא ממנו<sup data-n=\"1505\">32</sup> כ\"כ בעה\"כ דסה\"ד<sup data-n=\"1504\">31</sup>, וע' סוטה דל\"ה א' מנחות נ\"ג ב' ערוכין ט\"ו א' שארז\"ל אפי' בעה\"ב כו' אדון העולם<sup data-n=\"1506\">33</sup>, והיינו כי שרש התיקון מש'<sup data-n=\"1508\">35</sup> מ\"ה<sup data-n=\"1507\">34</sup>, והיצה\"ר משם<sup data-n=\"1510\">37</sup> ס\"ג<sup data-n=\"1509\">36</sup> ולכן נק' זקן<sup data-n=\"1511\">38</sup> כו', וזהו שאמרו ששרשו מבחי' הוא שמקבל מבחי' ארך אפים וע\"כ אמרו חזק הוא מבחי' זה<sup data-n=\"1512\">39</sup>, ועז\"נ שמים כו' וחשך לאור. אך באמת כי הוי' הוא האלקי'<sup data-n=\"1513\">40</sup>, אני הוי' הוא שמי<sup data-n=\"1514\">41</sup> בחי' הוא, הוא ר\"ת הוא ושמו אחד<sup data-n=\"1515\">42</sup>, ולכן כתי' ועבד הלוי הוא<sup data-n=\"1516\">43</sup>, והנה מחמת עון אשר יאמר עליו כי הוא זה מחמת זה נמשך להיות ואנכי הסתר אסתיר<sup data-n=\"1517\">44</sup> פני ביום ההוא, אמנם ע\"י התשובה יהי' נמשך להיות ואמר ביום ההוא<sup data-n=\"1518\">45</sup> הנה אלקינו זה.\n<b>וזהו</b> עד האלקי' יבא דבר שניהם פי' דבר שניהם היינו תשובה ווידוי<sup data-n=\"1519\">46</sup>, ופי' עד האלקי' עד שהוי' יהי' בבחי' אלקים כמ\"ש בלק\"ת שובה ישראל",[["1499","26","<b>הלבנון</b>: וכ\"ה בסה\"מ תרל\"ד (ע' קכח) ותרנ\"א (ע' קכא) כאן. תר\"ם ח\"ב ע' תרכו. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 34. בשה\"ש שם: לבנון — וכ\"ה בסה\"מ תרפ\"ה כאן ריש ע' קעח."],["1500","27","<b>ריחא דלבושייכו</b>: זהר ינוקא בלק קפו, א. ראה מאמרי אה\"ז הקצרים ע' שצט ואילך. מאמרי אדה\"א דרושי חתונה ח\"א ע' קה ואילך. וש\"נ."],["1501","28","<b>ריח בגדיו</b>: תולדות כז, כז."],["1502","29","<b>שמים . . לאור</b>: וכ\"ה באוה\"ת משפטים ע' א'עו. סה\"מ תרל\"ד (ע' קכט) ותרנ\"א כאן. בישעי' שם: שמים חשך לאור ואור לחשך."],["1503","30","<b>הוא הי' גבור ציד</b>: נח י, ט."],["1505","32","<b>כי חזק הוא ממנו</b>: שלח יג, לא."],["1504","31","<b>היצה\"ר נק' הוא . . בעה\"כ דסה\"ד</b>: מערכת הוא."],["1506","33","<b>אדון העולם</b>: רש\"י סוטה שם (המצויין בפנים) ד\"ה בעל הבית."],["1508","35","<b>מש' מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["1507","34","<b>התיקון מש' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"א ואילך."],["1510","37","<b>משם ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["1509","36","<b>והיצה\"ר משם ס\"ג</b>: ראה מק\"מ לזהר וישב קעט, ריש ע\"ב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 48 ואילך."],["1511","38","<b>והיצה\"ר . . נק' זקן</b>: ראה קה\"ר פ\"ד, יג. רש\"י קהלת שם. זהר מדרש הנעלם וירא קי, סע\"ב. וישב קעט, סע\"א ואילך. רא\"ש לנדרים לב, ב. לעיל הערה 36."],["1512","39","<b>וזהו שאמרו . . מבחי' זה</b>: ראה אוה\"ת משפטים כאן ס\"ע א'עו ואילך."],["1513","40","<b>כי הוי' הוא האלקי'</b>: ואתחנן ד, לה. לט. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 52."],["1514","41","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."],["1515","42","<b>הוא ר\"ת . . אחד</b>: של\"ה בית ה' ד, א."],["1516","43","<b>ועבד הלוי הוא</b>: קרח יח, כג. ראה זהר קרח קעח, ב. תו\"ח שמות ח\"א לד, א הערה 345."],["1517","44","<b>ואנכי הסתר אסתיר</b>: וילך לא, יח."],["1518","45","<b>ואמר ביום ההוא</b>: ישעי' כה , ט."],["1519","46","<b>דבר שניהם היינו תשובה ווידוי</b>: ראה אוה\"ת משפטים כאן ע' א'עז בתיקונים חדשים שבסוף ת\"ז ת\"י בשם ח\"צ [ושם קנג, ג: וידוי . . עם תורה . . וזהו יבא דבר שניהם הוידוי ותורה]. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 57.\nהספר ח\"צ [חמדת צבי לר' צבי ב\"ר ירחמיאל חאטש אמשטרדם תס\"ו] הובא בכ\"מ בדא\"ח ומהם: לקו\"ת פ' ראה כז, ד אוה\"ת משפטים ע' א'עז כנ\"ל. ע' א'שה. שלח ע' תקכח. חוקת ע' תשצג. ע' תתיא. איכה כרך ב ע' א'צו. אג\"ק ח\"ח אגרת ב'תסט.\nנזכר לעיל שהספר ח\"צ הובא בלקו\"ת פ' ראה. בבוך 1101 תיג, ב גוכתי\"ק הצ\"צ מאמר הנ\"ל הוזכר שם עודה\"פ [והוא בלקו\"ת שם לאח\"ז בשו\"ה ומיכאל — שהם] ”וכן פי' בחמדת צבי הנ\"ל\". ושם נמחקו ב' הפעמים. אלא כנראה שאח\"כ הוסיפו הצ\"צ רק בפעם הא' כנדפס בלקו\"ת שם. ראה גם בשולי היריעה שם במהדורת אותיות מרובעות."]]],[2001910192,"הראשון<sup data-n=\"1520\">47</sup>. אשר ירשיעון אלקים ארז\"ל במד\"ר נשא פ\"ט<sup data-n=\"1521\">48</sup> קרוב לסופה זה משה, שנא' ראה נתתיך אלקים לפרעה<sup data-n=\"1522\">49</sup>, ומשה אמר כי יהי' להם דבר<sup data-n=\"1523\">50</sup> בא אלי, וכתי' ואלה המשפטים אשר תשים<sup data-n=\"1524\">51</sup>, משה דוקא כמ\"ש בת\"א פ' משפטים<sup data-n=\"1525\">52</sup>.\n<b>ישלם</b><sup data-n=\"1526\">53</sup> שנים תשובה עילאה ותשו' תתאה<sup data-n=\"1527\">54</sup>, תורה ותפלה, גם ממעמקים קראתיך ה'<sup data-n=\"1528\">55</sup> ב' עומקים<sup data-n=\"1529\">56</sup>, גם הי' רגיל לקרות דף א' יקרא שני דפים שזהו תשובה כמ\"ש בתד\"א<sup data-n=\"1530\">57</sup>, וכמו\"כ נמשך לו מלמעלה ג\"כ בחי' שנים שהוא שני שמות הוי' שנא' ביגמה\"ר ה' ה'<sup data-n=\"1531\">58</sup>, גם שלום שלום לרחוק ולקרוב<sup data-n=\"1532\">59</sup> לרחוק שנעשה קרוב<sup data-n=\"1533\">60</sup> ע\"י התשובה במקום שבע\"ת עומדין<sup data-n=\"1534\">61</sup> כו' היינו יחוד י\"ה וגם ו\"ה כו', הרי נת' שכל משפטי התורה בענין בירור נה\"ב.\n<b>וזהו</b> אומרו העשיר לא ירבה<sup data-n=\"1535\">62</sup> והדל לא ימעיט, והיינו כי אין עשיר אלא בדעת<sup data-n=\"1536\">63</sup> ואין עני אלא בדעת, ועכ\"ז שניהם שוים במספר עשר, רק שבזאת הוא",[["1520","47","<b>בלק\"ת שובה ישראל הראשון</b>: ש\"ש סד, ג ואילך."],["1521","48","<b>במד\"ר נשא פ\"ט</b>: סמ\"ז בסופו."],["1522","49","<b>ראה נתתיך אלקים לפרעה</b>: וארא ז, א. במדרש הובא זה שם לפנ\"ז על התיבות ”עד האלקים\". הועתק גם באוה\"ת וארא ע' קלב [ובכרך ז ע' ב'תקצה]."],["1523","50","<b>כי יהי' להם דבר</b>: יתרו יח, טז. ראה גם לעיל בשולי הגליון פיסקא זה משה."],["1524","51","<b>ואלה המשפטים אשר תשים</b>: משפטים כא, א."],["1525","52","<b>בת\"א פ' משפטים</b>: עד, ג. עה, ב ואילך. ראה גם סה\"מ תרנ\"א כאן ס\"ע קכא ואילך."],["1526","53","<b>ישלם</b>: פיסקא זו מיוסד על אוה\"ת משפטים ס\"ע א'קנ ד\"ה זה."],["1527","54","<b>תשובה עילאה ותשו' תתאה</b>: זהר רע\"מ נשא קכג, א."],["1528","55","<b>ממעמקים קראתיך ה'</b>: תהלים קל, א."],["1529","56","<b>ב' עומקים</b>: ראה זהר בשלח סג, ב. אחרי ע, א. לקו\"ת נצבים מה, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תקצ. וש\"נ. קונטרסים ס\"ע שט ואילך. וש\"נ."],["1530","57","<b>הי' רגיל . . כמ\"ש בתד\"א</b>: וכ\"ה בסה\"מ תרל\"ד (ע' קכט וע' קצד) ותרנ\"א (ע' קכב) כאן. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 68.\nבקיצורים והערות לתניא ס\"ע לט מציין: ע' ויקרא רבה פכ\"ה ע\"ש. ראה לקו\"ש אגה\"ת כרך טל ע' 111 ואילך ובהערה 1 והערה 15 שם. סה\"מ תר\"ם ח\"ב ס\"ע תתקלז ואילך ובהערה 138."],["1531","58","<b>שני שמות . . ה' ה'</b>: תשא לד, ו."],["1532","59","<b>שלום שלום לרחוק ולקרוב</b>: ישעי' נז, יט."],["1533","60","<b>לרחוק שנעשה קרוב</b>: ראה ברכות לד, ב. אוה\"ת ישעי' כרך א ע' רעג."],["1534","61","<b>במקום שבע\"ת עומדין</b>: ראה ברכות שם. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["1535","62","<b>העשיר לא ירבה</b>: תשא ל, טו."],["1536","63","<b>אין עשיר אלא בדעת</b>: ראה כתובות סח, א."]]],[2001910193,"ההפרש בין עשיר לעני, שהעשיר ע\"י הדעת שלו מברר נה\"ב להיות בבחי' אתהפכא מחשוכא לנהורא<sup data-n=\"1537\">64</sup> ואז נעשה היצה\"ר טוב מאד<sup data-n=\"1538\">65</sup>, אבל העני בדעת הגם כי א\"א לבוא לבחי' אתהפכא מ\"מ לא יפחות מעשר ע\"י אתכפי' עכ\"פ ואז נחשב ג\"ז כופר נפשו לה' כו', וסוף כל סוף יבא לבחי' אתהפכא כו'.\n<b>והנה</b> כל מה שנת\"ל בענין מחצית השקל הוא בענין בירור נה\"ב, ומעתה יובן ענין מחצית השקל גם בנה\"א עצמה, והגם כי אינה צריכה תיקון מ\"מ ע\"י מחצית השקל מתעלה גם הנה\"א, וזהו כי תשא את ראש כו' זה יתנו כו' שע\"י נתינת מחצית השקל נעשה נשיאות ראש העלאת נה\"א. והענין הוא דהנה איתא בירושלמי פ\"ק דשקלים ה\"ו<sup data-n=\"1540\">67</sup> זה יתנו שנים עשר שבטים יתנו כו', דהנה איתא בס\"י ג' אמות אמש<sup data-n=\"1542\">69</sup><sup data-n=\"1541\">68</sup> ז' כפולות בג\"ד כפר\"ת<sup data-n=\"1543\">70</sup> י\"ב פשוטות<sup data-n=\"1544\">71</sup>, ושנים עשר שבטים נמשכים מי\"ב פשוטות, והם יתנו מחצית השקל שהוא עשרה גרה נגד ג' אמות וז' כפולות שמהם מקבלים י\"ב פשוטות, וא\"כ זהו ע\"ד והחיות נושאות את הכסא<sup data-n=\"1545\">72</sup> עם בחי' אדם שעל הכסא שהו\"ע ע\"ס כו', כך י\"ב שבטים שהם כמו י\"ב חיות<sup data-n=\"1546\">73</sup> המרכבה יתנו מחצית השקל בחי' עשרה גרה כמספר ע\"ס בחי' אדם כו'<sup data-n=\"1539\">66</sup>, וכמו שהחיות הם נושאות ומנושאות<sup data-n=\"1547\">74</sup> כן עי\"ז מתעלים הנשמות שהם מי\"ב שבטים לשורש שרשן הראשון כו'. והענין הוא דהנה משה נתקשה בג\"ד מנורה שקלים החדש (זח\"ב תרומה קנ\"ח א\"ב), ופי' הרמ\"ז<sup data-n=\"1548\">75</sup> בפ' פקודי דרך\"ה ע\"ב מה שנתקשה משה בשקלים<sup data-n=\"1549\">76</sup> לפי שישראל שרשם מיסוד אבא שלמעלה מהמספר והחשבון איך יעלו למנין ומספר כו' והקב\"ה הראה לו מטבע של אש<sup data-n=\"1550\">77</sup> שבה טבועין ומצויירין כל האורות עליונים כו' וא\"ל זה יתנו כו' חלק הנגלה שהוא נק' זה עכ\"ל. וביאור דבריו היינו כי בהנשמה יש ב' בחי' הא' שרש ומקור הנשמה כמו שהיא למעלה בחי' מזלי'<sup data-n=\"1551\">78</sup> כו' ונוזלים מן לבנון<sup data-n=\"1552\">79</sup>, וזהו שארז\"ל מאין באת<sup data-n=\"1553\">80</sup>, אין רומז על ג\"ר<sup data-n=\"1555\">82</sup> א' כתר יו\"ד חכ' נו\"ן נש\"ב, כמ\"ש מזה",[["1537","64","<b>אתהפכא מחשוכא לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרל\"ח ע' קנב. וש\"נ."],["1538","65","<b>טוב מאד</b>: ראה גם סה\"מ תרנ\"א כאן ס\"ע קכב ואילך."],["1540","67","<b>בירושלמי . . ה\"ו</b>: וכ\"ה באוה\"ת שם־ סה\"מ תרל\"ד (ע' קל) ותרנ\"א ע' (קכג) כאן. שם ה\"ג."],["1542","69","<b>אמש</b>: בסה\"מ תרל\"ד כאן: אמ\"ש אויר מים אש."],["1541","68","<b>ג' אמות אמש</b>: ס\"י פ\"ב, מ\"א."],["1543","70","<b>ז' כפולות בג\"ד כפר\"ת</b>: ס\"י פ\"ד, מ\"א."],["1544","71","<b>י\"ב פשוטות</b>: ס\"י פ\"ב, מ\"א. פ\"ה, מ\"א. ראה גם סה\"מ תרנ\"א כאן."],["1545","72","<b>והחיות נושאות את הכסא</b>: נסמן לעיל מאמר ד\"ה ועבדתם את ה\"א הערה 97."],["1546","73","<b>י\"ב שבטים . . י\"ב חיות</b>: ראה זהר ויחי רמא, א. לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 179."],["1539","66","<b>איתא בירושלמי . . אדם כו'</b>: השוה אוה\"ת תשא ע' א'תתקו ד\"ה זה יתנו."],["1547","74","<b>שהחיות הם נושאות ומנושאות</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה 102."],["1548","75","<b>ופי' הרמ\"ז</b>: להבא להלן ראה אוה\"ת תשא ע' א'תתקז פ\"ד."],["1549","76","<b>בשקלים</b>: באוה\"ת שם ליתא."],["1550","77","<b>אש</b>: שם: אש כו'."],["1551","78","<b>שרש . . הנשמה . . מזלי'</b>: ראה שעה\"ק להרח\"ו ח\"ג, ש\"ה. לקו\"ת במדבר טז, א ואילך. תצא לו, ריש ע\"ב. האזינו עא, ד. שה\"ש טז, ד. סה\"מ תר\"ם ח\"א ע' קנה ואילך. וש\"נ."],["1552","79","<b>ונוזלים מן לבנון</b>: שה\"ש ד, טו."],["1553","80","<b>מאין באת</b>: אבות פ\"ג, מ\"א."],["1555","82","<b>אין רומז על ג\"ר</b>: ראה ת\"ז רתמ\"ב. ת\"ע קכו, סע\"א."]]],[2001910194,"בלק\"ת<sup data-n=\"1554\">81</sup> בד\"ה במדבר סיני, הב' הוא בחי' הנשמה המלובשת בגוף, וחלק המלובש בגוף נק' זה שהו\"ע גילוי ע\"ד ואמר ביום ההוא הנה אלקינו זה, וזהו ג\"כ ענין מי ברא אלה<sup data-n=\"1556\">83</sup> כי אלה הוא כמו זה, משא\"כ מי הוא בחי' העלם ועז\"נ מי מנה עפר יעקב<sup data-n=\"1557\">84</sup> כו' שאין שם בחי' מנין כי בשרשם כולא חדא כנז' בת\"א פ' בשלח בד\"ה אז ישיר<sup data-n=\"1558\">85</sup> וגבי פורים סד\"ה וקבל היהודים<sup data-n=\"1559\">86</sup> וקבל ל' יחיד כו', וביאור הענין דהנה ענין ההתחלקות המדרגות זהו רק מהחכ' ולמטה<sup data-n=\"1561\">88</sup> כמ\"ש נודע בשערים<sup data-n=\"1563\">90</sup><sup data-n=\"1562\">89</sup> לכל חד לפום מה דמשער בלביה<sup data-n=\"1564\">91</sup> דהיינו כל אחד לפי השגתו, והיינו במדות שנמשכים ונולדים מהשכל א\"כ כשאין דעותיהם שוות גם המדות אינם שוות, וכמו תלמידי שמאי והלל שנתרבו הדעות<sup data-n=\"1565\">92</sup> וההתחלקות, זה פוסל וזה מכשיר מחמת שינוי הדיעות אף ששמאי והלל לא נחלקו רק בג' דברים<sup data-n=\"1566\">93</sup>, אבל תלמידיהם נחלקו הרבה זה תופס השכל ששמע מרבו כך וזה כך, ועד\"ז בהעבודה מצד השכל המושג נמשך התחלקות המדרגות אבל בחי' רעו\"ד<sup data-n=\"1567\">94</sup> שהוא הרצון שלמעלה מהשגת השכל לגמרי<sup data-n=\"1560\">87</sup>, הנה בבחי' זו כולם משתוים בו יחד כאילו אינו אלא רצון אחד מכולם יחד כאיש אחד, כי בלמעלה מהחכמה אין שייך שום התחלקות כלל, ולכן נא' וקבל לשון יחיד*. וזהו עצמו<sup data-n=\"1568\">95</sup> ב' בחי' השקל שכ\"א עשרים<sup data-n=\"1569\">96</sup> גרה כי בכל בחי' יש ע\"ס כו', רק\n\n<i>בגוכתי\"ק נרשם: ”ע\"כ להעתיק\". ראה לעיל הערה 1.</i>\nוהיינו שע\"י בחי' ביטול זה ורעותא דליבא הוא שזכו לגילוי אור א\"ס ב\"ה דכתי' בו כי לא יראני האדם וחי<sup data-n=\"8271\">כט</sup> שאינו נתפס בשום שכל אלא רק ברעותא דליבא<sup data-n=\"8272\">ל</sup>, וזהו וקיבל היהודים שבחי' הודאה הוא לבחי' שלמעלה מהשכל שאינו נתפס בשכל רק ע\"י הודאה, וכמאמר לך טוב להודות<sup data-n=\"8273\">לא</sup>, וזה הי' בפורים ע\"י הודאה ובענין מחצית השקל זהו עצמו<sup data-n=\"8274\">לב</sup> ב' בחי' שקל שכ\"א עשרה גרה כי בכל בחי' יש ע\"ס (רק שבבחי' שלמעלה מהחכמה אין שם התחלקות שהוא למעלה מהמספר ומנין וחשבון). וע\"י",[["1554","81","<b>מאין באת . . בלק\"ת</b>: במדבר ב, סע\"א."],["1556","83","<b>מי ברא אלה</b>: ישעי' מ, כו."],["1557","84","<b>מי מנה עפר יעקב</b>: בלק כג, י."],["1558","85","<b>בת\"א פ' בשלח בד\"ה אז ישיר</b>: סב, ב ואילך."],["1559","86","<b>בת\"א . . סד\"ה וקבל היהודים</b>: מג\"א צז, סע\"ד ואילך."],["1561","88","<b>ולמטה</b>: שם: למטה."],["1563","90","<b>בשערים</b>: בתו\"א שם: בשערים בעלה."],["1562","89","<b>נודע בשערים</b>: משלי לא, כג."],["1564","91","<b>לפום מה דמשער בלביה</b>: זהר וירא קג, ריש ע\"ב."],["1565","92","<b>תלמידי שמאי והלל שנתרבו הדעות</b>: ראה סוטה מז, סע\"ב."],["1566","93","<b>ששמאי והלל . . בג' דברים</b>: ראה שבת יד, ב. טו, א."],["1567","94","<b>רעו\"ד</b>: זהר וירא ק, א."],["1560","87","<b>וביאור הענין . . השכל לגמרי</b>: לשון התו\"א שם צח, א."],["1568","95","<b>וזהו עצמו</b>: ראה גם בשולי הגליון כאן על יד הערה לב."],["1569","96","<b>עשרים</b>: באוה\"ת (שבהערה 75) ובסה\"מ תרל\"ד (ע' קלא) כאן: עשרה.\n\n<b>כט</b> ) <b>כי לא יראני האדם וחי</b>: תשא לג, כ.\n\n<b>ל</b> ) <b>נתפס . . ברעותא דליבא</b>: ראה זהר אד\"ז האזינו רפט, ב. תו\"ח וישב קצט, ג ובהערה 56. שע\"ת קכה, א. סה\"מ תרל\"ח ע' מו. וש\"נ.\n\n<b>לא</b> ) <b>לך טוב להודות</b>: יהללוך ה\"א — בסיום ההלל.\n\n<b>לב</b> ) <b>זהו עצמו</b>: ראה גם בפנים כאן על יד הערה 95."]]],[2001910195,"שבבחי' שלמעלה מן הטו\"ד בחי' רעו\"ד בחי' מקיפים שבנשמה שם אינו שייך התחלקות כנודע שבמקיף אינו כמו באו\"פ, ושם הוא למעלה מן המספר ומנין וחשבון<sup data-n=\"1570\">97</sup>, וע\"י\nמחצית השקל מעוררים ג\"כ שרשם שלמעלה מהמנין והחשבון כו', ומ\"מ רק זה יתנו הוא חלק הגלוי ועי\"ז מתעלים לשרש שרשם ששם למעלה מן המנין כו', וזהו כי תשא את ראש עליית נה\"א כו'.",[["1570","97","<b>למעלה מן המספר ומנין וחשבון</b>: ראה סה\"מ תרנ\"א כאן ע' קכד."]]],[2001910196,"<h3>וידעת היום</h3>\n<b>פ' פקודי</b>\n<b>וידעת</b> היום<sup data-n=\"1571\">1</sup> והשבות אל לבבך כי הוי' הוא האלקי' בשמים ממעל<sup data-n=\"1572\">2</sup> כו' שנת' בד\"ה ראה קראתי בשם<sup data-n=\"1573\">3</sup> שענין המשכן והמקדש הי' שיאיר גילוי ש' הוי' בשם אלקים וש' אד', וש' אד' לא יסתיר<sup data-n=\"1574\">4</sup> וזהו ג\"כ ענין וידעת כו' כי הוי' הוא האלקי' כמשנ\"ת שם בענין מצות לייחדו, וע\"ש בענין מצות ראי' ברגלים<sup data-n=\"1575\">5</sup>, ושגם בזמן בהמ\"ק עיקר ההשראה הי' בתוכם<sup data-n=\"1576\">6</sup> כי בתוכו לא נא' כ\"א בתוכם בתוך כאו\"א<sup data-n=\"1577\">7</sup> כו' ולכן גם עכשיו בעבודה יש ג\"כ בחי' זו, וזהו שארז\"ל כ\"מ שנא' לי<sup data-n=\"1578\">8</sup> אינו זז לא בעוה\"ז כו', שנמצא צ\"ל שכל הבחי' שהיו במשכן ישנם גם עכשיו בעבודה, וז\"ע שהוי' הוא האלקי' נאמר בפסוק וידעת אחר והשבות אל לבבך, כי וידעת, והשבות אל לבבך כולל כלליות ופרטיות הענינים שהיו במשכן ומקדש כו'. ולהבין זה צ\"ל מ\"ש והשבות אל לבבך, שלכאו' הי' צ\"ל והשבות אל לבך מהו לבבך בשני ביתי\"ן, הנה נודע שיש",[["1571","1","<b>וידעת היום</b>: מאמר זה הוא הדרוש מש\"פ פקודי תרל\"ה ד\"ה אך עדיין צ\"ל מ\"ש והשבת אל לבבך שנדפס בסה\"מ תרל\"ה ח\"א ע' קלז ואילך (שבא שם בהמשך לד\"ה ראו קרא ה' בשם בצלאל) בהוספת התחלה.\nמאמר זה הוא כנראה המשך למאמר ד\"ה ראה קראתי בשם שנדפס לעיל (וכאן בהתחלתו צויין אליו) וראה הנסמן לעיל בריש המאמר שם.\nלפיסקא והנה עוד הי' במשכן ראה סה\"מ תרס\"ה ע' רא ואילך. וראה גם סה\"מ תרפ\"ה ע' רפו ואילך. תש\"ח ע' 138 ואילך.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו.\nבבוך זה 1130 — גוכתי\"ק וחלק בכת\"י הר\"ש סופר — נרשם מאמר דידן בהמפתח שבריש הספר (שמתחיל בע' עז) אמנם דפים אלו אינם נמצאים בהבוך. והועתק כאן מבוך תרמ\"א 2086 — כת\"י מעתיק — ע' לז."],["1572","2","<b>וידעת . . והשבות . . בשמים ממעל</b>: ואתחנן ד, לט."],["1573","3","<b>בד\"ה ראה קראתי בשם</b>: נדפס לעיל (לפני מאמר ד\"ה כי תשא)."],["1574","4","<b>ושם אד' לא יסתיר</b>: לעיל שם פ\"ד."],["1575","5","<b>וע\"ש בענין מצות ראי' ברגלים</b>: פ\"ד שם."],["1576","6","<b>בזמן בהמ\"ק . . הי' בתוכם</b>: לעיל שם רפ\"ב."],["1577","7","<b>בתוכם בתוך כאו\"א</b>: ראה לעיל שם הערה 21."],["1578","8","<b>כ\"מ שנא' לי</b>: ראה ויק\"ר פ\"ב, ב. מדרש שמואל פי\"ט. ספרי בהעלותך יא, טז. לקו\"ת במדבר ט, ג."]]],[2001910197,"בחי' פנימיות הלב וחיצוניות הלב<sup data-n=\"1579\">9</sup> והם כנגד ב' המזבחות מזבח החיצון ומזבח הפנימי<sup data-n=\"1580\">10</sup>, חיצוניות הלב הוא כנגד מזבח החיצון ופנימיות הלב הוא כנגד מזבח הפנימי, והנה על מזבח החיצון היו מקריבין פרים<sup data-n=\"1581\">11</sup> ואילים וכבשים, אבל על מזבח הפנימי לא היו מקריבין קרבנות כ\"א קטרת<sup data-n=\"1582\">12</sup> היו מקטירין, וכמו\"כ יובן בנפש האדם שעל חיצוניות הלב מקריבין את נה\"ב ששרשו ג\"כ מפני שור<sup data-n=\"1583\">13</sup> כמו בהמה הגשמיות רק ששורש בהמה הגשמיות הוא מבחי' פני שור<sup data-n=\"1584\">14</sup> שבפני שור ונה\"ב שרשה מבחי' פני אדם שבפני שור<sup data-n=\"1585\">15</sup>, אבל עכ\"פ שרשה ג\"כ מבחי' פני שור והקרבתה הוא<sup data-n=\"1586\">*16</sup> על חיצוניות הלב. וענין חיצוניות הלב הוא כי הנה מצינו שנחלק סדר התפלה על ג' בחי'<sup data-n=\"1587\">16</sup> דהיינו פסוד\"ז עד ק\"ש, וק\"ש ואמת ויציב, ותפלה, והנה פסוד\"ז וברכת ק\"ש הוא התבוננות הללו את ה' מן השמים<sup data-n=\"1588\">17</sup> הללוהו במרומים כו' הללו את ה' מן הארץ<sup data-n=\"1589\">18</sup> כו', ובברכת ק\"ש איך שהאופנים וחיות הקדש ברעש גדול ומצד זה תתפעל הנה\"ב כאשר תתבונן היטב ששרשה בטל כו' להיות גם היא רצונה ליכלל וליבטל אליו ית', שז\"ע בירור נה\"ב שתהי' ע\"ד בהמה למעלה שענין הבהמה למעלה<sup data-n=\"1590\">19</sup> הוא בחי' תוקף המדות לאלקות וככה תהי' גם הנה\"ב שהמדות דנה\"ב יהיו בבחי' תוקף לאלקות, ובחי' זו נק' חיצוניות הלב לפי שהתבוננות זו היא מבחי' בריאת העולמות ובריאת העולם הוא רק מהארה בעלמא, ולכן יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"1591\">20</sup> שאפי' בחי' ש' הוי' שהוא ג\"כ רק שם והארה בעלמא, אך הנה הארה זו הוא בחי' גבוה לכן הוא רק צוה ונבראו ממילא שאינו בבחי' התלבשות כו' לפי שהתהוות העולמות בחי' כח הפועל בנפעל<sup data-n=\"1592\">21</sup> הוא רק מהארה בעלמא בחי' מלכותך מל' כל עולמים<sup data-n=\"1593\">22</sup>, ולכן נק' בחי' חיצוניות הלב שהוא בחי' התבוננות מבחי' חיצוניות. אך הנה הקרבת נה\"ב הוא דוקא על בחי' חיצוניות הלב כי מצד התבוננות עצמותו ית' לא תתפעל הנה\"ב כלל",[["1579","9","<b>פנימיות הלב וחיצוניות הלב</b>: ראה גם תו\"א בראשית ז, ב. תצוה פד, ד. לקו\"ת בלק סז, ד."],["1580","10","<b>פנימיות הלב . . מזבח החיצון ומזבח הפנימי</b>: ראה לקו\"ת סוכות עח, ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז אתהלך לאזניא ע' קלב."],["1581","11","<b>מזבח החיצון . . פרים</b>: ראה יתרו כ, כא. רמב\"ם הל' ביהב\"ח פ\"א, ה\"ו."],["1582","12","<b>מזבח הפנימי . . כ\"א קטרת</b>: ראה תצוה ל, א. ז. ח. סהמ\"צ להרמב\"ם מ\"ע כח. רמב\"ם הל' כלי המקדש פ\"א, הי\"א. הל' תמידין ומוספין רפ\"ג."],["1583","13","<b>נה\"ב ששרשו ג\"כ מפני </b> [בסה\"מ תרל\"ה כאן: פני]<b> שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תר\"ם ח\"ב ע' תקפ. וש\"נ."],["1584","14","<b>ששורש בהמה . . פני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["1585","15","<b>ונה\"ב . . פני אדם שבפני שור</b>: ראה גם שערי אורה ח, א הערה 15. סה\"מ תרל\"א ח\"א ע' רלג. וש\"נ. תרל\"ח ע' לט. וש\"נ. תר\"ם ח\"ב ע' תריח."],["1586","*16","<b>הוא</b>: בסה\"מ תרל\"ה כאן: היא."],["1587","16","<b>התפלה על ג' בחי'</b>: ראה מאמרי אדה\"ז תקס\"ד ע' ע [צויין אליו לעיל במאמר ד\"ה ראה קראתי בשם] באו\"א. ראה גם תו\"א בראשית א, ד ואילך. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 13."],["1588","17","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["1589","18","<b>הללו את ה' מן הארץ</b>: תהלים שם, ז."],["1590","19","<b>שענין הבהמה למעלה</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ה. ע' י. תו\"ח בראשית יב, א."],["1591","20","<b>יהללו . . צוה ונבראו</b>: תהלים שם, ה. ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 79."],["1592","21","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."],["1593","22","<b>מלכותך מל' כל עולמים</b>: תהלים קמה, יג. ראה לקו\"ת אמור לה, ב."]]],[2001910198,"כ\"א כאשר תתבונן ששרשה בטל כו' כי אין הגבורות נמתקין אלא בשרשן<sup data-n=\"1594\">23</sup>, וזהו דוגמת מזבח החיצון שהיו מקריבין עליו פרים ואילים וכבשים ואש יורד מלמעלה<sup data-n=\"1595\">24</sup> דהיינו בחי' ארי' דאכיל קרבנין<sup data-n=\"1596\">25</sup> כמו\"כ בעבודה בנפש האדם הוא בחי' הקרבת הנה\"ב שרוח הבהמה יורדת למטה<sup data-n=\"1597\">26</sup> שתהי' בבחי' ביטול ובחי' אחרי ה' אלקיכם ילכו כארי' ישאג כו' (הושע סי' י\"א יו\"ד). אבל בחי' פנימיות הלב הוא נגד מזבח הפנימי שעליו מקטירין קטרת שענין הקטרת הוא בחי' התקשרות<sup data-n=\"1598\">27</sup> שתיבת קשר תרגומו קטר<sup data-n=\"1599\">28</sup> שהו\"ע בחי' התקשרות הנה\"א, והקשורים ליעקב<sup data-n=\"1600\">29</sup>, ונק' פנימיות הלב לפי שנמשך מצד התבוננות עצמותו כו', וזהו כדוגמת הקטרת שהוא דבר שהנשמה נהנית ממנה<sup data-n=\"1601\">30</sup> ולא הגוף. אך א\"א לבוא לבחי' פנימיות הלב התקשרות הנה\"א כ\"א שתהי' תחלה בירור הנה\"ב, כי הנה\"א מלובש בנה\"ב, ולכן כאשר הנה\"ב מתברר אז עי\"ז הוא עליית נה\"א ע\"ד דוגמא כמו בענין והחיות נושאות את הכסא<sup data-n=\"1602\">31</sup> שהחיות נושאות את הכסא עם בחי' אדם שעל הכסא, כך ע\"י בירור נה\"ב להיות כמו בחי' בהמה שלמעלה כנ\"ל אזי אח\"כ הוא בחי' עליית נה\"א להיות בבחי' התקשרות. והנה בנה\"א לא שייך לומר ל' בירור<sup data-n=\"1603\">32</sup>, כי בנה\"ב מצד שהוא מעורב טו\"ר<sup data-n=\"1604\">33</sup> לכן שייך לשון בירור לברר הטוב מהרע, אבל הנה\"א היא חלק אלק' ממעל<sup data-n=\"1605\">34</sup> ולא נמצא בה רע כלל לכן אינו שייך ל' בירור כ\"א עלייה. וההפרש שביניהם הוא כמו ההפרש שבין שבת<sup data-n=\"1606\">35</sup> לששת ימי החול, שבששת ימי החול הוא בחי' הבירורי' כו' כנודע, משא\"כ שבת בורר אסור<sup data-n=\"1607\">36</sup> רק הוא בחי' עליית העולמות<sup data-n=\"1608\">37</sup> כו', ועד\"ז הוא ענין בירור דנה\"ב ועליות דנה\"א. וכשם",[["1594","23","<b>אין הגבורות נמתקין אלא בשרשן</b>: ראה פע\"ח שער השופר שכ\"ו, פ\"א. תניא עם מ\"מ הגהות והע\"ק לפל\"א. מאמרי אדה\"א דברים ח\"ב ע' תרטו. וש\"נ. תו\"ח וירא קח, ב ובהערה 14."],["1595","24","<b>ואש יורד מלמעלה</b>: ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["1596","25","<b>ארי' דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. סה\"מ תר\"ם ח\"א ע' מ ואילך."],["1597","26","<b>שרוח הבהמה יורדת למטה</b>: קהלת ג, כא."],["1598","27","<b>הקטרת . . התקשרות</b>: ראה בחיי שמיני י, א: ולשון קטרת התקשרות. זהר שמיני לז, ב. לקו\"ת נשא כב, ד. סה\"מ תרל\"ח ע' מו. וש\"נ. בהערה הבאה."],["1599","28","<b>שתיבת קשר תרגומו קטר</b>: ראה וישב לח, כח. סה\"מ תר\"ם ח\"ב ע' תרכד ואילך ובהנסמן שם."],["1600","29","<b>והקשורים ליעקב</b>: ויצא ל, מב. ראה לקו\"ת נשא שם."],["1601","30","<b>דבר שהנשמה נהנית ממנה</b>: ראה ברכות מג, ב. סה\"מ תר\"ם ח\"א ע' מז. וש\"נ."],["1602","31","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["1603","32","<b>בנה\"א . . ל' בירור</b>: ראה תניא פל\"ז (מח, ב). וראה גם לעיל מאמר ד\"ה כי תשא ובהנסמן שם."],["1604","33","<b>בנה\"ב . . מעורב טו\"ר</b>: ראה תניא פ\"א. לקו\"ת ויקרא ב, ד. במדבר ב, ג."],["1605","34","<b>חלק אלק' ממעל</b>: איוב לא, ב. ראה גם תניא רפ\"ב. סידור ר' יעקב קאפיל בהקדמת הכותב ע' ג. מאמרי אדה\"א ויקרא ח\"ב ע' שעג. וש\"נ. תו\"ח וארא ח\"א נא, ד. וש\"נ. סה\"ש תש\"נ ע' 381."],["1606","35","<b>ההפרש שבין שבת</b>: ראה תו\"א ח\"ש טו, ג ואילך. יתרו ע, ב. לקו\"ת בלק עב, א. מאמר ד\"ה למה נסמכה וביאורו במאמרי אדה\"ז תקס\"ג ח\"א ע' רלז ואילך (הנחת אדה\"א). תקס\"ד ע' עח ואילך (הנחת הר\"מ). תו\"ח ויקהל ח\"ב תיח, ג ואילך. מאמר ד\"ה זכור שבהערה 40. לקמן בהנחה כאן על יד הערה 31."],["1607","36","<b>שבת בורר אסור</b>: ראה שו\"ע אדה\"ז הל' שבת סשי\"ט. סה\"מ תר\"ם ח\"א ע' רמג. וש\"נ."],["1608","37","<b>שבת . . עליית העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. תו\"ח בא ח\"א קכז, א הערה 667."]]],[2001910199,"ששבת הוא בחי' השביתה שאחר הירידה דששת ימי החול אז אח\"כ כי בו שבת<sup data-n=\"1610\">39</sup> כו', ולכן המהלך במדבר כו' מונה ששה תחלה<sup data-n=\"1611\">40</sup> ואח\"כ משמר יום אחד כו', כך עליית נה\"א הוא ע\"י בירור הנה\"ב דוקא כו'<sup data-n=\"1609\">38</sup>, וזהו והשבות אל לבבך ב' לבבות חיצוניות הלב ופנימיות הלב דוגמת מזבח החיצון ומזבח הפנימי, ואנו מבקשים ויחד לבבינו<sup data-n=\"1612\">41</sup> כו' כמשי\"ת<sup data-n=\"1613\">42</sup>.\n<b>והנה</b> עוד הי' במשכן שני בחי' יריעות המשכן והכלים, והיריעות היו מד' בחי' תכלת וארגמן ותולעת שני ושש<sup data-n=\"1614\">43</sup>, והכלים היו ג\"כ ד' ארון ומנורה ושולחן ומזבח הפנימי, שעיקר ענין המשכן הוא להמשיך ש' הוי' לכן היו ד' כנגד ד'<sup data-n=\"1616\">45</sup> אותיות דש' הוי'<sup data-n=\"1615\">44</sup> כו'. ויובן תחלה ענין היריעות שהיו ד' בחי' תכלת וארגמן ותולעת שני ושש נגד ד' אותיות דש' הוי' והיו עשר יריעות כמ\"ש ואת המשכן תעשה עשר יריעות<sup data-n=\"1617\">46</sup> נגד עשר אותיות דש' הוי' עם המילוי<sup data-n=\"1618\">47</sup>, מהו בעבודה בנפש האדם. הנה תכלת הוא בחי' יראה<sup data-n=\"1619\">48</sup> כי ענין היראה הוא מחמת רוממות המלוכה שמחמת שהמלך הוא מרומם ומתנשא מחמת זה הוא בחי' היראה, וזהו מה שארז\"ל תכלת דומה לים<sup data-n=\"1620\">49</sup> וים דומה לרקיע, שהוא בחי' מלכותא דרקיע<sup data-n=\"1621\">50</sup> שהוא בחי' מלכותך מל' כ\"ע שמרומם ומתנשא וכמ\"ש המלך המרומם לבדו<sup data-n=\"1622\">51</sup> שהו\"ע רוממות המלוכה ומחמת זה נמשך היראה וכמ\"ש שום תשים עליך מ'<sup data-n=\"1623\">52</sup> וארז\"ל שתהא מוראו עליך<sup data-n=\"1624\">53</sup>, ובד\"כ הוא בחי' קעומ\"ש. ותולעת שני הנה תולעת שני הוא גוון סומק<sup data-n=\"1625\">54</sup> שהוא בחי' אהבה ברשפי אש בחי' רצוא אם רץ לבך<sup data-n=\"1626\">55</sup> וכמו בקרבנות היו מקריבין הדם שהוא בחי' רשפי אש, ולכן מי שהוא מרובה בדמים החמימות והרשפי אש אצלו ביותר. וארגמן הוא בחי'",[["1610","39","<b>כי בו שבת</b>: בראשית ב, ג."],["1611","40","<b>המהלך במדבר . . ששה תחלה</b>: ראה גם לעיל מאמר ד\"ה זכור את יום השבת פ\"ו. וש\"נ."],["1609","38","<b>וכשם ששבת . . דוקא כו'</b>: בסה\"מ תרל\"ה כאן ע' קלט ליתא."],["1612","41","<b>ויחד לבבינו</b>: ברכת (אהבת עולם אהבתנו) ק\"ש. ראה לקו\"ת בלק סז, ג. האזינו עד, א. תו\"ח תרומה ח\"ב כאן דש, ג ובהערה 10."],["1613","42","<b>ויחד לבבינו כו' כמשי\"ת</b>: להלן ריש פיסקא והנה נת' לעיל."],["1614","43","<b>והיריעות היו מד' בחי' . . ושש</b>: תרומה כו, א."],["1616","45","<b>והכלים היו . . ד' כנגד ד'</b>: ראה אוה\"ת ויקהל כאן ס\"ע ב'רי ואילך."],["1615","44","<b>והיריעות היו . . ד' . . דש' הוי'</b>: ראה מאמרי אדה\"ז תקס\"ד כאן ע' סח בשולי היריעה."],["1617","46","<b>ואת המשכן תעשה עשר יריעות</b>: תרומה כו, א. ויקהל לו, ח."],["1618","47","<b>עשר יריעות . . הוי' עם המילוי</b>: יו\"ד ה\"א וא\"ו ה\"א — ראה אוה\"ת ויקהל כאן ע' ב'רח."],["1619","48","<b>תכלת . . יראה</b>: ראה (בנוסף למאמרי אדה\"ז תקס\"ד כאן־ אוה\"ת ויקהל כאן ס\"ע ב'קפו ואילך. ע' ב'רח ואילך) לקו\"ת שלח מג, ג. קרח נג, ד. לקמן הערה 72."],["1620","49","<b>תכלת דומה לים</b>: באוה\"ת ויקהל כאן ע' ב'רח מציין: ועיין מזה במד\"ר נשא פי\"ד דת\"ז ב' [במדב\"ר פי\"ד, ג] ובמנחות דמ\"ג ב' ובזח\"א קכ\"א א' ובפי' הרמ\"ז שם (וראה גם אוה\"ת שם ס\"ע ב'קפו ואילך). ראה גם הנסמן במ\"מ במאמרי אדה\"ז תקס\"ד לע' סח."],["1621","50","<b>מלכותא דרקיע</b>: ברכות נח, א."],["1622","51","<b>המלך המרומם לבדו</b>: נוסח ברכת יוצר."],["1623","52","<b>שום תשים עליך מ'</b>: פ' שופטים יז, טו."],["1624","53","<b>שתהא מוראו עליך</b>: ראה סנהדרין כב, א (במשנה). סה\"מ תרל\"ו ח\"ב ע' תמא בהערה."],["1625","54","<b>תולעת שני . . סומק</b>: ראה אוה\"ת ויקהל ע' ב'קפז. תרומה ע' א'תקא [ובנוגע להרמ\"ז שבאוה\"ת כאן — ראה גם שם ע' א'תקב]."],["1626","55","<b>אם רץ לבך</b>: ס\"י פ\"א, מ\"ח."]]],[2001910200,"מדה\"ר<sup data-n=\"1627\">56</sup>, כי ארגמן הוא גוון הכלול מכמה גוונים<sup data-n=\"1628\">57</sup> וכך מדה\"ר כלול מחו\"ג<sup data-n=\"1629\">58</sup> שהיא מדתו של יעקב<sup data-n=\"1630\">59</sup> שהי' כלול מאברהם ויצחק כמ\"ש אלקי אבי אברהם<sup data-n=\"1631\">60</sup> ופחד יצחק הי' לי וכתי' יעקב אשר פדה את אברהם<sup data-n=\"1632\">61</sup>. ושש הוא בחי' חסד<sup data-n=\"1633\">62</sup> שהוא בחי' מקור כל הששה מדות, וכמ\"ש יומם יצוה ה' חסדו<sup data-n=\"1634\">63</sup> שהוא בחי' יומא דאזיל עם כולא יומין<sup data-n=\"1635\">64</sup> שזהו מקור כל הששה מדות, והנה שש הוא בחי' בד<sup data-n=\"1636\">65</sup> שהוא גוון לבן וגוון לבן הוא עצמי<sup data-n=\"1637\">66</sup>, והיינו מפני שבחסד מאיר מבחי' גבוה מאד שזהו מ\"ש וישכם לבן בבקר<sup data-n=\"1638\">67</sup>, בקר הוא בחי' בקר דאברהם<sup data-n=\"1639\">68</sup>, וישכם לבן בבקר הוא בחי' לובן העליון<sup data-n=\"1640\">69</sup> בחי' לבושי' כתלג חיור<sup data-n=\"1641\">70</sup> שמאיר בבחי' בקר דאברהם, וזהו גוון לבן שהוא בחי' גוון עצמי, ובנפש הוא בחי' אהבה מוסתרת שיש בכל אחד מישראל שהיא בחי' יחידה שבנפש שהוא בחי' רצון פשוט שלמעלה מן הטעם שהוא כנגד יו\"ד וקש\"י<sup data-n=\"1642\">71</sup>, וזהו הד' בחי' שבנפש שהם ד' בחי' שביריעות המשכן נגד ד' אותיות דש' הוי'. וכמו\"כ ד' בחי' כלים ג\"כ מכוון נגד בחי' אלו, שולחן הוא כנגד בחי' תכלת בחי' מל'<sup data-n=\"1643\">72</sup> כנ\"ל והשולחן הוא ג\"כ בחי' מל'<sup data-n=\"1644\">73</sup>, וכמ\"ש כי על שולחן המלך<sup data-n=\"1645\">74</sup> תמיד הוא אוכל (ש\"ב ט' י\"ג), והיינו שלמעלה ענין השולחן הוא שע\"י השולחן נמשך כל ההשפעות<sup data-n=\"1646\">75</sup> והיינו כמ\"ש ואתה מחי' את",[["1627","56","<b>וארגמן . . מדה\"ר</b>: במאמרי אדה\"ז תקס\"ד ואוה\"ת: הארגמן . . ת\"ת שהוא מדת הרחמים. ראה גם לקמן ובהערה 90."],["1628","57","<b>ארגמן . . מכמה גוונים</b>: ראה זהר תרומה קלט, א."],["1629","58","<b>מדה\"ר כלול מחו\"ג</b>: ראה ביאוה\"ז תרומה נ, ג. תו\"ח בראשית מ, א ובהערה 4. וארא ח\"א פה, ד. וש\"נ."],["1630","59","<b>מדה\"ר . . של יעקב</b>: ראה זהר לך פז, ב. מאמרי אדה\"א בראשית ע' קנו. וש\"נ."],["1631","60","<b>אלקי אבי אברהם</b>: ויצא לא, מב [בדילוג]. ראה ספר הבהיר סק\"צ. תו\"א תולדות יז, ג. סידור שער הלולב רסב, א. תו\"ח בא ח\"א קכז ג. וש\"נ."],["1632","61","<b>יעקב אשר פדה את אברהם</b>: ישעי' כט, כב."],["1633","62","<b>ושש . . חסד</b>: ראה הגהת הרח\"ו לזהר פקודי רכח, א. מאמרי אדה\"ז תקס\"ד כאן ע' עה. אוה\"ת כאן ע' ב'קפז וע' קצג."],["1634","63","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט."],["1635","64","<b>יומא דאזיל עם כולא יומין</b>: ראה זהר אמור קג, ב. פע\"ח ש' יוה\"כ שכ\"ז, פ\"ג (הובא ברמ\"ז לזהר יתרו סז, א — אוה\"ת כאן ע' ב'קצג). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'לה."],["1636","65","<b>שש . . בד</b>: ראה יומא עא, ב."],["1637","66","<b>וגוון לבן הוא עצמי</b>: ראה לקו\"ת אחרי כח, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תפד. וש\"נ. דברים ח\"ד ע' א'רלו-א'רלז. המשך תרס\"ו ע' שעג ואילך."],["1638","67","<b>וישכם לבן בבקר</b>: ויצא לב, א."],["1639","68","<b>בקר דאברהם</b>: ע\"פ וירא כב, ג (כ\"ה בתו\"א דבסמוך. וראה גם שם: יט, כז. כא, יד).\nראה זהר מקץ רג, א. רע\"מ משפטים קיט, ב. אחרי סד, ב. בלק רד, א. ת\"ז תכ\"ב סז, א. תו\"א ויצא כד, ב."],["1640","69","<b>לבן . . לובן העליון</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' רכב. וש\"נ. תו\"ח ויצא קסח, ד ובהערה 31."],["1641","70","<b>לבושי' כתלג חיור</b>: בסה\"מ תרל\"ה כאן ע' קמ: לבושא — דניאל ז, ט [ושם לבושה]."],["1642","71","<b>רצון פשוט . . כנגד יו\"ד וקש\"י</b>: ראה אגה\"ת פ\"ד. סה\"מ תרס\"ה כאן ע' רו."],["1643","72","<b>תכלת בחי' מל'</b>: ראה הגהת הרח\"ו לזהר פקודי רכח, א. מאו\"א מערכת תכלת אות כא. מאמרי אדה\"ז תקס\"ד כאן ע' סח. תו\"ח ויקהל ח\"ב תח, ב. וש\"נ."],["1644","73","<b>והשולחן . . מל'</b>: ראה טור ברקת סתרע\"א, ס\"ה (קכו, ד) בשם זהר תרומה [ראה שם קנג, ב — קנה, א ובמפרשים]. פרדס שעה\"כ שכ\"ג, פכ\"א מערכת שולחן."],["1645","74","<b>כי על שולחן המלך</b>: ראה זהר תרומה קנג, א. קנו, ב."],["1646","75","<b>שע\"י השולחן נמשך כל ההשפעות</b>: ראה זהר לך פח, ב. תרומה קנג, ב. קנד, ב."]]],[2001910201,"כולם<sup data-n=\"1647\">76</sup> ולכן שולחן בצפון<sup data-n=\"1648\">77</sup> כי מצפון זהב יאתה<sup data-n=\"1649\">78</sup>, והרוצה להעשיר יצפין<sup data-n=\"1650\">79</sup>, והשולחן והכלים שלו הי' ג\"כ של זהב<sup data-n=\"1651\">80</sup> כו'. והנה ההפרש שבין שולחן לתכלת, כי תכלת דומה לים וים דומה לרקיע והרקיע הוא כדורי<sup data-n=\"1652\">81</sup> בחי' מקיף והשולחן היא השפעה פנימיות, והיינו כי במל' יש ב' בחי' הא' הוא בחי' רוממות המלוכה המלך המרומם לבדו כו' כנ\"ל, והב' הוא בחי' ואתה מחי'<sup data-n=\"1653\">82</sup> את כולם שמחי' בבחי' או\"פ. ומנורה היא כנגד תולעת שני, שתולעת שני היא בחי' אהבה ברשפי אש כנ\"ל וכך הוא ענין המנורה שהוא בחי' אש, רק שמנורה היא בחי' היותר גבוה שיש בה שמן ופתילה<sup data-n=\"1655\">84</sup> שהיא בחי' תורה<sup data-n=\"1654\">83</sup> כו'. וארון הוא כנגד בחי' שש לפי שבארון היו הלוחות, והנה הלוחות היו אותיות החקיקה<sup data-n=\"1656\">85</sup> שהם אותיות החקוקים מיני' ובי' שהוא כמו שש שהוא גוון עצמי בלתי עשוי מדבר אחר, ובחי' אותיות החקיקה הם יותר גבוהים מאותיות הכתב<sup data-n=\"1657\">86</sup> כי אותיות הכתב שכותבים בדיו על הקלף שהם חיבור ב' דברים נפרדים, וכך התורה ניתנה באש שחורה ע\"ג אש לבנה<sup data-n=\"1658\">87</sup>, משא\"כ הלוחות היו אותיות החקיקה מיני' ובי' ע\"ד גליף גליפו בטהירו עילאה<sup data-n=\"1659\">88</sup> וזהו שהארון הוא כנגד בחי' שש כי שש הוא בחי' יחידה שבנפש שמקבלת מבחי' יחיד<sup data-n=\"1660\">89</sup> וארון הוא מלמעלה למטה השפעה מבחי' יחיד כו'. ומזבח הפנימי הוא כנגד ארגמן בחי' ת\"ת<sup data-n=\"1661\">90</sup> שהוא בחי' התעוררות רחמים, ברחמיך הרבים רחם עלינו<sup data-n=\"1662\">91</sup>, והוא בחי' בריח התיכון המבריח<sup data-n=\"1663\">92</sup> מן הקצה אל הקצה, ולכן הי' המזבח עומד מכוון כנגד הארון<sup data-n=\"1664\">93</sup> לפי שמזבח הוא בחי' בריח התיכון כו'. נמצא כי יש ד' בחי' אלו ביריעות המשכן ובכלים רק ההפרש בין יריעות לכלים",[["1647","76","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1648","77","<b>שולחן בצפון</b>: תרומה כו, לה. פקודי מ, כב. יומא כא, ב. לג, ריש ע\"ב."],["1649","78","<b>מצפון זהב יאתה</b>: איוב לז, כב."],["1650","79","<b>והרוצה להעשיר יצפין</b>: ראה ב\"ב כה, ב."],["1651","80","<b>והשלחן והכלים . . של זהב</b>: תרומה כה, כד-כט."],["1652","81","<b>והרקיע הוא כדורי</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' יב. ענינים ע' רפ. מאמרי אדה\"א הנחות תקע\"ז ע' קעט. סהמ\"צ להצ\"צ קסב, ב. סה\"מ תרכ\"ח סע\"ב. תרכ\"ט ע' ז."],["1653","82","<b>במל' יש ב' . . בחי' רוממות . . ואתה מחי'</b>: ראה אוה\"ת פ' זכור ע' א'תשעא. ויקהל ע' ב'קנח ואילך."],["1655","84","<b>שיש בה שמן ופתילה</b>: ראה מאמרי אדה\"ז תקס\"ד כאן ע' סט. אוה\"ת ויקהל כאן ע' ב'רי.\nבמאמרי אדה\"ז שם מציין בהערה שכאן וכן באוה\"ת מיכה ע' תעו מציין לתניא פל\"ד ולכאורה צ\"ל פל\"ה. ויש להוסיף אוה\"ת הנ\"ל."],["1654","83","<b>שמנורה . . תורה</b>: ראה תורת העולה ח\"א פט\"ז. תו\"ח ויקהל ח\"ב תמ, א ובהערה 1928."],["1656","85","<b>הלוחות היו אותיות החקיקה</b>: תשא לב, טז."],["1657","86","<b>אותיות החקיקה . . מאותיות הכתב</b>: ראה לקו\"ת אחרי כח, ג. בחוקותי מה, א. ד ואילך. חוקת נו, א. נט, ג ואילך. שה\"ש ה, א."],["1658","87","<b>באש שחורה ע\"ג אש לבנה</b>: ראה רש\"י שה\"ש ה, טז ד\"ה שחורות. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["1659","88","<b>גליף גליפו בטהירו עילאה</b>: ראה זהר בראשית טו, א."],["1660","89","<b>יחידה . . שמקבלת מבחי' יחיד</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. לקו\"ת ואתחנן יא, ג. מאמרי אדה\"א קונטרסים ע' שצא. וש\"נ. סה\"מ תר\"ם ח\"ב ע' תרכח. וש\"נ."],["1661","90","<b>ארגמן . . בחי' ת\"ת</b>: ראה זהר תרומה קלט, א ובהגהות הרח\"ו שם."],["1662","91","<b>ברחמיך הרבים רחם עלינו</b>: נוסח ברכת יוצר."],["1663","92","<b>בריח התיכון המבריח</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג."],["1664","93","<b>המזבח עומד מכוון כנגד הארון</b>: ראה תוספתא יומא פ\"ב, הי\"א. ברייתא דמלאכת המשכן פ\"ד. רש\"י תצוה ל, ו."]]],[2001910202,"שביריעות היו משזר<sup data-n=\"1665\">94</sup> שהיו כלולים יחד ובבחי' כלים היו כ\"א בפ\"ע הארון הי' עומד בקה\"ק ופרוכת הי' מפסיק בין קדש לקה\"ק<sup data-n=\"1666\">95</sup>, ושולחן ומנורה ומזבח הפנימי היו עומדים בהיכל שולחן בצפון ומנורה בדרום ומזבח באמצע<sup data-n=\"1667\">96</sup> שהי' כ\"א בפ\"ע. והענין הוא דהנה כתי' לכל זמן ועת לכל חפץ תחת השמים<sup data-n=\"1668\">97</sup>, והיינו שקאי אפי' על תו\"מ שלכל יש זמן כמו מצות מילה שניתנה לאברהם ולא קודם לכן והתורה ניתנה למשה ולא קודם, והגם שהיו קודם אך תחת השמים לכל עת שבאותו עת יהי' הגילוי דוקא, ואפי' בחי' שמים החדשים וארץ החדשה אשר אני עושה<sup data-n=\"1669\">98</sup> הנה הם ישנם גם עכשיו, אך זמן ניתן להם אימתי יגיעו תחת השמים שעדיין לא הגיע העת, והיינו אף שבחי' אלו הם למעלה מבחי' הזמן מ\"מ כיון שנמשכו מתחת השמים יש לזה זמן ועת אימתי יתגלו, אך הנה כ\"ז הוא כשנמשך תחת השמים, אבל בבחי' שמים שהוא בחי' מקיף הוא למעלה מבחי' זמן כי בבחי' תחת השמים נמשך בבחי' פרט, משא\"כ בשמים הוא בדרך כלל ששם הוא בחי' התכללות וכמו ע\"ד שארז\"ל שהראה הקב\"ה לאדה\"ר<sup data-n=\"1670\">99</sup> דור דור ודורשיו דור דור ומנהיגיו, והראה לו שבצלאל יבנה המשכן וכמ\"ש קורא הדורות מראש<sup data-n=\"1671\">100</sup>, ועז\"נ ראה קראתי בשם<sup data-n=\"1672\">101</sup> שהראה למשה בספרו של אדה\"ר<sup data-n=\"1673\">102</sup>, שהוא בחי' כלל שכולל כל הפרטים. והנה בנפש בחי' כלל ופרט שמים ותחת השמים הוא בחי' מוח ולב שהמוחין נק' בחי' שמים והלב הוא בחי' תחת השמים, וזהו וידעת שהוא בחי' דעת בחי' מוח שהוא בחי' התכללות ואח\"כ והשבות אל לבבך הוא בחי' תחת השמים שבלב הוא בחי' התחלקות אהבה בפ\"ע ויראה בפ\"ע, משא\"כ בבחי' דעת אינם בבחי' התחלקות, ואף שיש שם ג\"כ בחי' אהוי\"ר מ\"מ האהוי\"ר הם שכלי' שאינם הפכים כלל<sup data-n=\"1674\">103</sup> רק הם בבחי' התכללות יחד, וכמו שאנו רואים למטה שמים ואש* הם הפכים ומים מכבין אש אעפ\"כ המים וכח האש כמו הצור (הנק' קרעמין<sup data-n=\"1676\">104</sup>) אינם הפכים זל\"ז כלל, והיינו לפי שבמקור הם בבחי' התכללות<sup data-n=\"1675\">*104</sup>, וע\"ד מ\"ש הרמב\"ן שיש בחי' כח היולי<sup data-n=\"1677\">105</sup>",[["1665","94","<b>שביריעות היו משזר</b>: תרומה כו, א. ויקהל לו, ח."],["1666","95","<b>הארון . . ופרוכת . . לקה\"ק</b>: תרומה כו, לג."],["1667","96","<b>ושולחן ומנורה ומזבח הפנימי . . באמצע</b>: תוספתא יומא שם. יומא לג, ב. שקלים פ\"ו, ה\"ג. רמב\"ם הל' בית הבחירה פ\"א, ה\"ז. פ\"ג הי\"ז."],["1668","97","<b>לכל זמן . . תחת השמים</b>: קהלת ג, א. ראה קה\"ר שם."],["1669","98","<b>שמים החדשים . . אני עושה</b>: ישעי' סו, כב. ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 101."],["1670","99","<b>שהראה הקב\"ה לאדה\"ר</b>: ראה תנחומא תשא יב. שמו\"ר פ\"מ, ג. סנהדרין לח, ב. ע\"ז ה, א. אדר\"נ פל\"א, ג. לקו\"ש תרומה כרך יא ע' 319 ואילך."],["1671","100","<b>קורא הדורות מראש</b>: ישעי' מא, ד."],["1672","101","<b>ראה קראתי בשם</b>: תשא לא, ב."],["1673","102","<b>שהראה למשה בספרו של אדה\"ר</b>: ראה שמו\"ר פ\"מ, ב."],["1674","103","<b>בבחי' דעת . . הפכים כלל</b>: ראה גם תו\"ח תרומה ח\"ב שח, סע\"ד ואילך."],["1676","104","<b>הצור (הנק' קרעמין)</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' קסח. אוה\"ת חוקת כרך ה ע' א'תרמט [ובמהדורת תשמ\"ח חוקת כרך א בהוספות ע' 61]. יוכ\"פ כרך ה ע' ב'קלו. סה\"מ תר\"ל ע' שיב וע' שיז. תרל\"א ח\"א ע' רכה. תרל\"ה כאן ע' קמב. תרל\"ט ח\"ב ע' תקכה. תרפ\"ד ע' כד. תרפ\"ט ע' 63. תש\"ט ע' 34 (הא')."],["1675","*104","<b>שמים ואש . . בבחי' התכללות</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ס\"ע תדש ואילך."],["1677","105","<b>מ\"ש הרמב\"ן . . כח היולי</b>: ראה בראשית א, א. סה\"מ תר\"ם ח\"א ס\"ע קפח. וש\"נ.\nהובא גם (בנוסף לסה\"מ תרל\"ה כאן. לקמן בהנחה כאן) באוה\"ת שמות ע' מה. בשלח ע' שצג. ראה גם סה\"מ תרס\"ב ע' שנז. תרפ\"ו ס\"ע כט. תרפ\"ח ע' קסט."]]],[2001910203,"שכולל כל הד' בחי' ארמ\"ע<sup data-n=\"1678\">106</sup> והגם שארמ\"ע הם הפכים אך זהו כמו שנחלקו תחת השמים, אבל בשרשן יש כח היולי שכוללם יחד ושם אינם הפכים כלל. וזהו שביריעות המשכן שהם בחי' מקיפים בחי' שמים נוטה שמים כיריעה<sup data-n=\"1679\">107</sup> היו כל הד' בחי' תכלת כו' כלולים יחד לפי שאינם הפכים כלל, משא\"כ בכלים הם כ\"א בפ\"ע. וזהו וידעת היום שמתחלה הם כלולים בבחי' דעת ואח\"כ והשבות אל לבבך הם בבחי' פרטי' שנחלקו כ\"א למדרגה בפ\"ע יראה בפ\"ע ואהבה בפ\"ע.\n<b>והנה</b> נת' לעיל<sup data-n=\"1680\">108</sup> שבלב יש ב' בחי' חיצוני' הלב ופנימי' הלב שהם כנגד מזבח החיצון ומזבח הפנימי ואנו מבקשים ויחד לבבינו ליחד ב' הלבבות, והיינו כמו שבבהמ\"ק היו נוטלים גחלים לוחשות מע\"ג מזבח החיצון על מזבח הפנימי<sup data-n=\"1681\">109</sup> ועליהם היו מקטירין קטרת, וכך הוא בעבודה שצריך לחבר את בחי' חיצוני' הלב עם פנימי' הלב, כי קטרת הוא בחי' שמו\"ע כי צלותא בחשאי<sup data-n=\"1682\">110</sup> קול דממה דקה<sup data-n=\"1683\">111</sup> שז\"ע קטרת שהם בחשאי, כי ע\"ג מזבח החיצון הי' בחי' אש שהאש הוא בחי' רעש לפי שהאש מכלה את הדבר הנשרף דהיינו את הבהמה ובנפש האדם הוא בחי' הנה\"ב, אבל בקטרת לא הי' אש כלל רק גחלים לוחשות שכבר נשרפו, ובנפש הוא בחי' עליית נה\"א שאינו ע\"ד בירור כ\"א עלי' כנ\"ל<sup data-n=\"1684\">112</sup> ולכן הוא בחשאי. והנה ק\"ש ואמת ויציב הוא בחי' המחבר שתי הלבבות חיצוני' הלב ופנימיות הלב שהם כנגד מה שבמקדש היו לוקחי' הגחלים מעל מזבח החיצון להקטיר הקטרת על מזבח הפנימי כו', וכך אמת ויציב הוא ט\"ו ווי\"ן<sup data-n=\"1685\">113</sup> שווי\"ן הוא בחי' התקשרות<sup data-n=\"1686\">114</sup>, וזהו בווין תתקטר<sup data-n=\"1687\">115</sup> דהיינו שע\"י הווין דאמוי\"צ עי\"ז מגיע לבחי' קטרת שהוא בחי' שמו\"ע שהוא בחי' התקשרות של הנה\"א. וזהו ענין מיכאל עומד ומקריב נשמות<sup data-n=\"1688\">116</sup> ע\"ג המזבח, שהוא ענין בחי' העלאה של הנה\"א לבחי' עצמותו ית' לאשתאבא בגופא דמלכא<sup data-n=\"1689\">117</sup>, כי שרש נש\"י הוא מבחי' כלים<sup data-n=\"1690\">118</sup> כנודע ממ\"ש במ\"א, וההקרבה",[["1678","106","<b>הד' בחי' ארמ\"ע</b>: ראה שה\"א סו, א ובהערה 17. סה\"מ תרכ\"ט ע' קעט. וש\"נ. תרל\"ח ע' תצא. לקמן מאמר ד\"ה כתר יתנו לך פ\"ב."],["1679","107","<b>נוטה שמים כיריעה</b>: ראה גם לעיל מאמר ד\"ה ראה קראתי בשם ספ\"א. וש\"נ."],["1680","108","<b>והנה נת' לעיל</b>: סוף פיסקא וידעת היום."],["1681","109","<b>גחלים לוחשות . . מזבח הפנימי</b>: ראה תמיד לג, א. רמב\"ם הל' תמידין ומוספין פ\"ג, ה\"ה. ראה גם מאמרי אדה\"ז תקס\"ד כאן ע' סז. אוה\"ת ויקהל כאן ע' ב' רז ואילך. תו\"ח תרומה ח\"ב כאן שה, ד ואילך. וש\"נ. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 113 ואילך."],["1682","110","<b>צלותא בחשאי</b>: זהר ח\"ש קלב, א. ויגש רי, א. תרומה קלח, ב. ועוד. ראה מאמרי אדה\"א בראשית ע' צט. וש\"נ."],["1683","111","<b>קול דממה דקה</b>: מלכים-א יט, יב."],["1684","112","<b>כ\"א עלי' כנ\"ל</b>: על יד הערה 32 ואילך."],["1685","113","<b>אמת ויציב הוא ט\"ו ווי\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ח. תו\"ח וישב רי, א הערה 14. לקמן מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 75."],["1686","114","<b>שווי\"ן הוא בחי' התקשרות</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י קרוב לספ\"ד."],["1687","115","<b>בווין תתקטר</b>: זמירות לליל שבת — אזמר בשבחין."],["1688","116","<b>מיכאל עומד ומקריב נשמות</b>: ראה חגיגה יב, ב כגי' הע\"י. תוד\"ה ומיכאל מנחות קי, א. מאמרי אדה\"א ויקרא ח\"א ע' א. וש\"נ. תו\"ח שמות ח\"א ה, א. וש\"נ. סה\"מ תר\"ם ח\"א ס\"ע מא ואילך."],["1689","117","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם סה\"מ תר\"ם ח\"א ע' צז. וש\"נ."],["1690","118","<b>שרש נש\"י הוא מבחי' כלים</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה רפ\"ב. וש\"נ."]]],[2001910204,"היא<sup data-n=\"1691\">119</sup> לאשתאבא בגופא דמלכא. ומעתה יובן<sup data-n=\"1692\">120</sup> מה שבצלאל א' לעשות המשכן תחלה ואח\"כ כלים, לפי שע\"פ אתעדל\"ע שהיא מלמעלמ\"ט נמשך תחלה בחי' שמים שהוא בחי' מקיפים ואח\"כ הכלים בחי' או\"פ, ובעבודה שמתחלה<sup data-n=\"1693\">121</sup> נמשך בבחי' דעת ואח\"כ בבחי' מדות, וזהו וידעת היום ואח\"כ והשבות אל לבבך, וזהו שא\"ל משה בצל אל היית וידעת<sup data-n=\"1694\">122</sup>, צל הוא בחי' מקיף פי' שכוונתך לעשות כמו שנמשך ע\"י אתעדל\"ע מלמעלמ\"ט כו'. אך משה היפך וא' שיעשה הכלים תחלה ואח\"כ המשכן, והיינו לפי שאע\"פ שע\"פ אתעדל\"ע א\"א להיות נמשך כ\"א מקיפים תחלה ואח\"כ בחי' פנימיות מ\"מ עיקר המכוון הוא כדי שיומשך בבחי' פנימיות וכמ\"ש הן לה' אלקיך<sup data-n=\"1695\">123</sup> השמים ושמי השמים כו' רק באבותיך חשק ה'<sup data-n=\"1696\">124</sup> שהם הם עיקר המכוון, וכך עיקר הכוונה הוא בחי' הכלים שהם בחי' פנימי' והם בחי' אתעדל\"ת מלמטלמ\"ע, וזהו שנא' בהם בפ' תרומה בציווי העשי' ועשו ארון<sup data-n=\"1697\">125</sup> ועשית מנורת<sup data-n=\"1698\">126</sup> ועשית שולחן<sup data-n=\"1699\">127</sup> שהוא בחי' אתעדל\"ת וע\"י בחי' אתעדל\"ת זו נמשך בחי' המקיפים ופנימי', והיינו שכדי שיומשך אפי' בבחי' שמים הנה כתי' השמים ושמי השמים<sup data-n=\"1700\">128</sup> לא יכלכלוך וכדי שיומשך בבחי' שמים זהו ע\"י צמצום שהוא בחי' צמצם שכינתו<sup data-n=\"1701\">129</sup> בין ב' בדי הארון דוקא והצמצום עושים ע\"י אתעדל\"ת דוקא, ולכן א' משה שיעשה הכלים תחלה ואח\"כ המשכן. ועד\"ז מצינו פלוגתא בגמ' שב\"ש אומרים שמים קדמו שנא' בראשית ברא אלקים<sup data-n=\"1703\">131</sup> את השמים וב\"ה<sup data-n=\"1702\">130</sup> אומרים ארץ קדמה שנא' ביום עשות ה' אלקים<sup data-n=\"1704\">132</sup> ארץ ושמים וכתי' לפנים הארץ יסדת<sup data-n=\"1705\">133</sup>, ושניהם אמת<sup data-n=\"1706\">134</sup> שבבריאה שמים קדמו, אך במח' ארץ נבראת תחלה שהוא עיקר המכוון כמ\"ש אנכי עשיתי ארץ<sup data-n=\"1707\">135</sup> ואדם עליה בראתי, וכך עיקר המכוון הי' כדי שיומשך מבחי' מקיף לבחי' פנימי, ולכך אף שא\"א שיומשך בבחי' פנימיות כ\"א שיומשך תחלה בחי' מקיפים אעפ\"כ עיקר הכוונה הי' בשביל המשכת פנימיות ולכך היפך משה הסדר כו'.",[["1691","119","<b>וההקרבה היא</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י פ\"ג."],["1692","120","<b>ומעתה יובן</b>: ראה גם לעיל מאמר ד\"ה ראה קראתי בשם רפ\"ב."],["1693","121","<b>ובעבודה שמתחלה</b>: בסה\"מ תרל\"ה ח\"א ע' קמד כאן בהערה העיר שלכאורה צ\"ל ובעבודה הוא שמתחלה."],["1694","122","<b>בצל אל היית וידעת</b>: ברכות נה, א."],["1695","123","<b>הן לה' אלקיך</b>: עקב י, יד."],["1696","124","<b>רק באבותיך חשק ה'</b>: עקב שם, טו."],["1697","125","<b>בפ' תרומה . . ועשו ארון</b>: כה, י."],["1698","126","<b>ועשית מנורת</b>: שם כה, לא."],["1699","127","<b>ועשית שולחן</b>: שם כה, כג. כ\"ה סדר הכתובים גם בסה\"מ תרל\"ה כאן וראה בהערה שם. אבל ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."],["1700","128","<b>השמים ושמי השמים</b>: מלכים-א ח, כז."],["1701","129","<b>צמצם שכינתו</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["1703","131","<b>בראשית ברא אלקים</b>: בראשית א, א."],["1702","130","<b>פלוגתא בגמ' שב\"ש . . וב\"ה</b>: ראה חגיגה יב, א. ב\"ר פ\"א, טו."],["1704","132","<b>ביום עשות ה' אלקים</b>: שם ב, ד."],["1705","133","<b>לפנים הארץ יסדת</b>: תהלים קב, כו. כתוב זה מובא בב\"ר שם."],["1706","134","<b>ושניהם אמת</b>: ראה תו\"א ויגש מג, ג. לקו\"ש בא כרך ו ס\"ע 75 ואילך ובהנסמן שם."],["1707","135","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."]]],[2001910205,"<h3>מגילה נקראת</h3>\n<b></b><b>ש\"פ ויקרא ופ' זכור ולא הועתק ומחצה השני בפורים וג\"כ לא הועתק</b>\n<b>מגילה</b> נקראת<sup data-n=\"1708\">1</sup> באחד עשר כו' בחמשה עשר לא פחות ולא יותר, כרכי' המוקפים חומה מימות יהושע בן נון קורין בחמשה עשר<sup data-n=\"1709\">2</sup>. וצ\"ל מפני מה לא פחות ולא יותר, וגם צ\"ל מה שבכרכי' המוקפים חומה מימות יהושע בן נון קורין בט\"ו הלא הנס הי' בבבל דהיינו בשושן שהוא בעילם המדינה<sup data-n=\"1710\">3</sup> וא\"כ מה שייך לשנות הכרכים שמוקפות חומה שבא\"י.\n<b>הנה</b> כתי' ויקרא אל משה<sup data-n=\"1711\">4</sup> שהוא ל' חיבה<sup data-n=\"1712\">5</sup> כמ\"ש בזהר ל' אוקיר<sup data-n=\"1713\">6</sup> אנוש מפז (ישעי' י\"ג פסוק י\"ב) וכתי' ולא קם נביא עוד בישראל כמשה<sup data-n=\"1714\">7</sup> וארז\"ל במד\"ר ס\"פ במדבר<sup data-n=\"1716\">9</sup> ס\"פ י\"ד<sup data-n=\"1715\">8</sup> דרס\"ד ע\"ד<sup data-n=\"1717\">10</sup> (הוא דנ\"ה ע\"ד<sup data-n=\"1718\">11</sup>) תני ולא קם נביא כו' בישראל לא קם אבל באוה\"ע קם ומנו בלעם [וכ\"ה בזח\"ג בלק קצ\"ג ע\"א<sup data-n=\"1719\">12</sup> ובלק\"ת מהאריז\"ל פ'",[["1708","1","<b>מגילה נקראת</b>: מאמר זה הוא מיוסד על ד\"ה זה הנחת כ\"ק אדמו\"ר מהר\"ש מדרוש אביו כ\"ק אדמו\"ר הצ\"צ משנת תרט\"ז ובתוספת הגהות נדפס בסה\"מ תרכ\"ז ע' קעג ואילך (ובמהדורת אותיות מרובעות ע' קעח ואילך וראה בהנסמן בריש המאמר שם. ולמהדורא זו צויין לקמן בהערות) וכאן הוא בתוספת הגהות.\nב) הנחה אחרת מדרוש הצ\"צ (בתוס' הגהות) נדפסה בפלח הרמון מגלת אסתר ע' שנ ואילך בכותרת: ”שבת פ' ויקרא רחבו\"ת\" ולקמן בהביאור (ד\"ה להבין שרשי וביאור הדברים בענין הציץ על יד הערה לט) מעתיק ומציין אלי'.\nג) ועוד הנחה מדרוש הנ\"ל נמצא בבוך 739 שב, א והיא הנחת של ר' דוב [בעריל] קאליסקער [ראה גם לעיל מאמר ד\"ה קדש ישראל לה' בהערה 1].\nהמאמר נרשם בכת\"י מעתיק, ששילב את ההגהות שנכתבו בגוכתי\"ק על נייר בפ\"ע בכותרת: ”הגהות לס' רכ\"ז\" ומציין הדף והשיטה שאליהם שייכים. ועוד הגהות [שאותם לא העתיק] שנרשמו על דפים קטנים בכותרת: ”לעיין בזה (ב\". ואולי הכוונה בתיבת ב' שזה שייך לפרק ב.\nבבוך זה 1130 נרשם המאמר והביאור אחר המאמר שנדפס לאח\"ז. וכן נרשם גם בבוך תרמ\"א 2086 — כת\"י מעתיק. אמנם כאן סודרו המאמרים כפי סדר זמן אמירתם.\nחלק מההגהות דלהלן בפנים באים בתוך חצאי עיגול וחלק בתוך חצאי מרובע — כי כן הוא בסה\"מ תרכ\"ז שמאמר זה הוא העתק ממנו כנ\"ל. כמו\"כ חלוקת הפיסקאות במאמר זה הם ע\"פ הנדפס בסה\"מ תרכ\"ז.\nביאור על המאמר ד\"ה להבין שרשי וביאור הדברים בענין הציץ נדפס לקמן.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה — רק חלק קטן — נדפסה לקמן בחלק הנחותיו ושם הפתיחא ויקרא אל משה."],["1709","2","<b>מגילה נקראת . . בחמשה עשר</b>: מגילה פ\"א, מ\"א."],["1710","3","<b>בשושן שהוא בעילם המדינה</b>: דניאל ח, ב."],["1711","4","<b>ויקרא אל משה</b>: ויקרא א, א."],["1712","5","<b>ויקרא . . ל' חיבה</b>: ראה גם רש\"י שם. ראה פלח הרמון מג\"א כאן ע' שנ כמבואר בת\"כ. וראה מזרחי שם."],["1713","6","<b>ויקרא . . בזהר ל' אוקיר</b>: ראה זהר ויקרא ג, א. אוה\"ת תצוה כאן ע' א'תשלח."],["1714","7","<b>ולא קם . . כמשה</b>: ברכה לד, י. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שלז ובהנסמן שם."],["1716","9","<b>ס\"פ במדבר</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן. וכנשצ\"ל: ס\"פ נשא — כבאוה\"ת פ' זכור ע' א'תשצד. אוה\"ת שבהערה שלפנ\"ז. ואולי תיבת ”ס\"פ\" במדבר פיענוחו ספר במדבר."],["1715","8","<b>במד\"ר ס\"פ במדבר ס\"פ י\"ד</b>: סימן כ — ראה שם. אוה\"ת נח כרך ג' ע' 1284. פ' זכור ע' א'תשעו."],["1717","10","<b>דרס\"ד ע\"ד</b>: כנצ\"ל: דרס\"ב ע\"ד — במהדורת אמשטרדם ת\"א."],["1718","11","<b>הוא דנ\"ה ע\"ד</b>: במהדורת שקלאב תקע\"ד."],["1719","12","<b>ע\"א</b>: לכאורה צ\"ל כבסה\"מ תרכ\"ז כאן: ע\"ב."]]],[2001910206,"בלק<sup data-n=\"1720\">13</sup> כי משה הי' נבואתו מיסוד אבא שהוא דעת עליון שבז\"א, וכן בבלעם נא' ויודע דעת עליון<sup data-n=\"1721\">14</sup>, ובמאו\"א ב' סט\"ו<sup data-n=\"1722\">15</sup> בלעם קליפ' מקבלת ליסו\"א דעת דז\"א ומקבל אורו כנגד מקום גילוי דעת בין עקבי לאה עכ\"ל, ובי\"נ העיר מזח\"ב יתרו דע\"ט<sup data-n=\"1723\">16</sup>, ומלק\"ת פ' בלק הנ\"ל, וי\"ל כי בלעם הי' השגתו מאצי' דקלי'<sup data-n=\"1724\">17</sup> שנתבאר ענין אצי' דקלי' בד\"ה אם בהרת קדמה<sup data-n=\"1725\">18</sup> ומעמיד קלי' דאצי' היא<sup data-n=\"1726\">19</sup> בבריאה<sup data-n=\"1727\">20</sup>], ובמד\"ר ע\"פ ויקרא<sup data-n=\"1728\">21</sup> אל משה מה בין נביאי ישראל לנביאי אוה\"ע רב חמא בר חנינא אין הקב\"ה נגלה על נביאי אוה\"ע אלא בחצי דבור<sup data-n=\"1729\">22</sup> שנאמר ויקר אלקים אל בלעם<sup data-n=\"1730\">23</sup>, אבל נביאי ישראל בדבור שלום<sup data-n=\"1731\">24</sup> שנא' ויקרא אל משה, ר' ישכר דכפר מנדו אין ויקר אלא לשון טומאה כמ\"ד אשר לא יהי' טהור מקרה לילה<sup data-n=\"1732\">25</sup>, וצ\"ל מהו שייך לומר<sup data-n=\"1733\">26</sup> בנבואה לשון טומאה כו'.\n<b>הנה</b><sup data-n=\"1734\">27</sup> בלעם ועמלק הוא בחי' אחת<sup data-n=\"1735\">28</sup> כמ\"ש בזהר<sup data-n=\"1736\">29</sup> והיינו כי אותיות עמל הוא בבלעם וגם בעמלק רק שעמלק הוא עמל קו\"ף<sup data-n=\"1737\">30</sup> ובלעם הוא עמל בי\"ת ולכן הם בחי' אחת, והנה כששלח ה' את שאול להחרים את עמלק אמר שאול לשמואל בבואו מן המלחמה הקימותי את דבר ה'<sup data-n=\"1738\">31</sup>, ושמואל השיב לו מאסת את דבר ה'<sup data-n=\"1739\">32</sup> והיינו מפני שחמלו על מיטב הצאן<sup data-n=\"1740\">33</sup> וצ\"ל מפני מה הי' גדול כ\"כ חטא שאול הלא ע\"פ הטעם הי' נכון מה שלא החרים את הצאן והבקר בכדי להקריב מהם קרבנות,",[["1720","13","<b>ובלק\"ת מהאריז\"ל פ' בלק</b>: ד\"ה ענין בלק ובלעם הב'."],["1721","14","<b>ויודע דעת עליון</b>: בלק כד, טז."],["1722","15","<b>סט\"ו</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן. וכ\"ה במאו\"א [במאורי אור] — ובמאו\"א שם הוא טעות הדפוס וצ\"ל: ע\"ו."],["1723","16","<b>ע\"ט</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן. וכ\"ה בי\"נ [ביאיר נתיב] — ובי\"נ שם הוא טעות הדפוס וצ\"ל: סט, סע\"א ואילך."],["1724","17","<b>שבלעם . . מאצי' דקלי'</b>: ראה גם אוה\"ת פ' זכור ע' א'תשעו וע' א'תשצד."],["1725","18","<b>אצי' דקלי' בד\"ה אם בהרת קדמה</b>: לקו\"ת תזריע כג, ג ואילך. ראה גם לקו\"ת שמיני כא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תעד ואילך ובהנסמן שם ע' תעה. הנסמן בסה\"מ תרכ\"ז כאן ע' קעח. תר\"ם ח\"ב ע' תתקיא הערה 104."],["1726","19","<b>ומעמיד . . היא</b>: בסה\"מ תרכ\"ז כאן: ומעמד . . הוא."],["1727","20","<b>ומעמד קלי' . . בבריאה</b>: ראה אוה\"ת ויצא כרך ה' ע' תתמה: ”כ\"מ בע\"ח שער הקליפות פ\"ב . . בשער ק\"נ פ\"ט\" ע\"ש. פ' שופטים ס\"ע תתל ואילך. לקו\"ת במדבר ג, סע\"ג. לקמן בהביאור הערה 148."],["1728","21","<b>ובמד\"ר ע\"פ ויקרא</b>: ראה ויק\"ר פ\"א, יג."],["1729","22","<b>בחצי דבור</b>: ראה סה\"מ תרכ\"ז כאן ע' קפו בשולי היריעה. פלח הרמון מג\"א כאן ע' שנט."],["1730","23","<b>ויקר אלקים אל בלעם</b>: בלק כג, ד."],["1731","24","<b>שלום</b>: בסה\"מ תרכ\"ז כאן ע' קעט: שלם."],["1732","25","<b>אשר לא . . לילה</b>: תצא כג, יא."],["1733","26","<b>מהו שייך לומר</b>: ראה גם פלח הרמון מג\"א כאן ע' שנ."],["1734","27","<b>הנה</b>: בסה\"מ תרכ\"ז כאן: והנה."],["1735","28","<b>בלעם ועמלק הוא בחי' אחת</b>: ראה פלח הרמון מג\"א כאן ע' שנח בשם אדהצ\"צ [ראה אוה\"ת פ' זכור ס\"ע א'תשצד]."],["1736","29","<b>בלעם ועמלק . . בזהר</b>: בסה\"מ תרכ\"ז כאן ניתוסף: [אפ\"ל כוונתו בזח\"ג בלק דקצ\"ד א']."],["1737","30","<b>שעמלק הוא עמל קו\"ף</b>: ראה לקמן פ\"ו."],["1738","31","<b>כששלח ה' את שאול . . הקימותי את דבר ה'</b>: שמו\"א טו, א ואילך. שם, יג."],["1739","32","<b>מאסת את דבר ה'</b>: שם טו, כג. ראה גם סה\"מ תרכ\"ז כאן (ס\"ע קפד בשולי היריעה) ד\"ה וענין."],["1740","33","<b>שחמלו על מיטב הצאן</b>: שם שם, יד. טו. כא."]]],[2001910207,"ומפני מה הי' גדול עוונו מנשוא עד שאמר לו שמואל מאסת את דבר ה', אך הענין הוא דהנה עמלק א\"א כלל שיתברר שנא' בו ואחריתו עדי אובד<sup data-n=\"1741\">34</sup>.\nב)<sup data-n=\"1742\">35</sup> <b>ויובן</b> כ\"ז בהקדים הפסוק ועשית ציץ זהב טהור<sup data-n=\"1743\">36</sup> כו' פי' ציץ יש בו ב' פירושי', הא' לשון הארה<sup data-n=\"1744\">37</sup> כמו נץ החמה<sup data-n=\"1745\">38</sup>, יציץ נזרו<sup data-n=\"1746\">39</sup>, יציץ ופרח ישראל<sup data-n=\"1747\">40</sup>, שהוא מלשון הארה כו', הב' מלשון הבטה וראי'<sup data-n=\"1748\">41</sup> מלשון מציץ מן החרכים<sup data-n=\"1749\">42</sup> וכמו שפרש\"י על מציץ ל' הבטה<sup data-n=\"1750\">43</sup> ע\"ד מ\"ש ראה ראיתי את עני עמי<sup data-n=\"1751\">44</sup> כו'.\n<b>ולהבין</b> ב' הפירושי' צ\"ל תחלה פי' הא' שהוא ל' הארה, הנה הציץ הי' אהרן נושא אותו על מצחו<sup data-n=\"1752\">45</sup>, והנה אהרן הי' אחד מז' רועי'<sup data-n=\"1753\">46</sup> שהיו מפרנסים נש\"י והיינו שאהרן המשיך בחי' אה\"ר לנש\"י<sup data-n=\"1754\">47</sup>, והגם שארז\"ל [ברכות פ\"ה דל\"ג<sup data-n=\"1755\">48</sup> מגילה פ\"ב דך\"ה<sup data-n=\"1756\">49</sup> נדה פ\"ב דט\"ז<sup data-n=\"1757\">50</sup>] הכל בידי שמים<sup data-n=\"1758\">51</sup> חוץ מיראת שמים<sup data-n=\"1759\">52</sup> א\"כ אהוי\"ר תלוי' הם בעבודת האדם מלמטלמ\"ע, אך הנה באמת יש שני אהוי\"ר, הא' הוא בחי' אהוי\"ר מלמטלמ\"ע הב' הוא בחי' אהוי\"ר הבאה לאדם מלמעלה למטה (בבחי' מתנה<sup data-n=\"1760\">53</sup>, וע\"ז*\n\n*)\n<i>נרשם מלמעלמ\"ט בצד הימיני של העמוד ולא נסמן מקומו בפנים:</i>\nמה יפית סי' י\"ח<sup data-n=\"8275\">א</sup>",[["1741","34","<b>ואחריתו עדי אובד</b>: בלק כד, כ. ראה גם לקמן פ\"ד. מאמרי אדה\"א שמות ח\"ב ע' תקכב. וש\"נ. נ\"ך ע' תקטז. קונטרסים ע' רמא. סה\"מ תרמ\"ז ע' פז-פט."],["1742","35","<b>ב)</b>: ניתוסף ע\"פ סה\"מ תרכ\"ז כאן."],["1743","36","<b>ועשית ציץ זהב טהור</b>: תצוה כח, לו."],["1744","37","<b>ציץ . . לשון הארה</b>: ראה גם תו\"א תצוה פג, א. תו\"ח תצוה ח\"ב שנו, א. שסג, ג."],["1745","38","<b>נץ החמה</b>: ברכות ח, ב. ט, ב. ועוד."],["1746","39","<b>יציץ נזרו</b>: תהלים קלב, יח."],["1747","40","<b>יציץ ופרח ישראל</b>: ישעי' כז. ו."],["1748","41","<b>הב' מלשון הבטה וראי'</b>: ראה אוה\"ת תצוה ע' א'תרפט שמציין לזהר ויקהל דרי\"ז, ב ע\"פ ויעש את הציץ, ציץ אסתכלותא. תו\"ח תצוה ח\"ב שנו, א. שסג, ג."],["1749","42","<b>מציץ מן החרכים</b>: שה\"ש ב, ט."],["1750","43","<b>ל' הבטה</b>: תיבות אלו הם תוכן פרש\"י."],["1751","44","<b>ראה ראיתי . . עמי</b>: שמות ג, ז."],["1752","45","<b>הציץ הי' . . על מצחו</b>: תצוה כח, לח. ראה גם פלח הרמון מג\"א כאן."],["1753","46","<b>אהרן . . מז' רועי'</b>: ראה תיקונים לז\"ח קד, א. סה\"מ תרל\"ט ח\"ב ע' תכב. לקו\"ש חנוכה כרך כ ע' 643. בהעלותך כרך לח ע' 193."],["1754","47","<b>שאהרן המשיך בחי' אה\"ר לנש\"י</b>: ראה תו\"א תצוה פב, א ואילך. לקו\"ת בהעלותך כט, ג ואילך. מאמרי אדה\"א במדבר ח\"ג ס\"ע תתפג ואילך (ובהנסמן בראשית המאמרים שם)."],["1755","48","<b>דל\"ג</b>: ע\"ב."],["1756","49","<b>דך\"ה</b>: ע\"א."],["1757","50","<b>דט\"ז</b>: ע\"ב."],["1758","51","<b>הכל בידי שמים</b>: ראה גם סה\"מ תר\"ם ח\"א ע' קיד וע' שלה. לקמן מאמר ד\"ה בגמ' וכו' קא מפלגי פ\"ג."],["1759","52","<b>הכל בידי . . מיראת שמים</b>: וכ\"ה באהבה — ראה פלח הרמון מג\"א כאן ריש ע' שנא. סה\"מ ליקוט ח\"ב ע' קמג [המשך תרס\"ו מהדורת תשנ\"ט ע' תרו]."],["1760","53","<b>מתנה</b>: בסה\"מ תרכ\"ז כאן ס\"ע קעט בהערה כותב בגוכי\"ק נסמן כאן להגה\"ה ”בנייר בפ\"ע\" ולע\"ע לא נמצא. ואולי הכוונה להבא להלן בפנים — ראה לעיל הערה 1.\n\n<b>א</b> )מה יפית סי' י\"ח: הכוונה שזה העתק אגה\"ק סי\"ח. הערה זו לא נעתקה בכת\"י מעתיק."]]],[2001910208,"כתי'<sup data-n=\"1762\">55</sup> שמחו צדיקים בה' ולא כל אדם זוכה לזה, וזו היא בחי' כהנא ברעותא דליבא<sup data-n=\"1764\">57</sup> שבזה\"ק<sup data-n=\"1763\">56</sup>, ועז\"נ עבודת מתנה<sup data-n=\"1765\">58</sup> כו'<sup data-n=\"1766\">59</sup> כהונתכם<sup data-n=\"1767\">60</sup> והזר הקרב כו'<sup data-n=\"1774\">67</sup> כי אין דרך להשיגה ע\"י יגיעת בשר כמו היראה ששואלין עליה יגעת ביראה<sup data-n=\"1768\">61</sup>, ואוי לבשר שלא נתייגע ביראה כמ\"ש בר\"ח<sup data-n=\"1769\">62</sup> כתיב<sup data-n=\"1770\">63</sup> ביראה אם תבקשינה ככסף וכמטמונים תחפשנה (משלי ב' ד'<sup data-n=\"1771\">64</sup>) מלמד שצריכה יגיעה רבה ועצומה כמחפש אוצרות<sup data-n=\"1772\">65</sup>, אבל אהבה רבה זו בתענוגים<sup data-n=\"1773\">66</sup> (דהיינו שמתענג על ה' עונג נפלא בשמחה רבה ועצומה שמחת הנפש וכלותה, בטעמה כי טוב<sup data-n=\"1775\">68</sup> ה' ונעים נעימות עריבות עד להפליא מעין עוה\"ב<sup data-n=\"1777\">70</sup> שנהנין<sup data-n=\"1776\">69</sup> כו') הנה היא<sup data-n=\"1778\">71</sup> נופלת לאדם מלמעלה<sup data-n=\"1779\">72</sup> בלי שיכין ויכוון לה, אך ורק לאחר<sup data-n=\"1780\">73</sup> שנתייגע ביראת הרוממות להגיע<sup data-n=\"1781\">74</sup> לתכלית מה שיוכל להשיג ממנה לפי בחי' נשמתו אזי<sup data-n=\"1782\">75</sup> ממילא באה אהבה<sup data-n=\"1783\">76</sup> בתענוגי' מלמעלה לשכון ולהתייחד עם היראה כי דרכו של איש לחזור<sup data-n=\"1784\">77</sup> כו' כמ\"ש<sup data-n=\"1785\">78</sup> בלק\"א<sup data-n=\"1761\">54</sup> וע' בת\"א ד\"ה חכלילי עיניים מיין<sup data-n=\"1786\">79</sup> ואמנם מ\"ש רבינו ז\"ל זהו ע\"פ מ\"ש בת\"ז תיקון ב'<sup data-n=\"1787\">80</sup> וע' בס'\n\n<i>נרשם מלמעלמ\"ט בצד הימיני של העמוד ולא נסמן מקומו בפנים:</i>\nבת\"א ד\"ה חכלילי כ' שאה\"ר אין לה הפסק<sup data-n=\"8276\">ב</sup>, ובד\"ה ועשית ציץ<sup data-n=\"8277\">ג</sup> שאה\"ר יש לה הפסק אחר התפלה, אך אהבה רבה זו שהיא אהבה בתענוגים שאפ\"ל שהכהן יכול להמשיך זה מחמת שזהו כהנא ברעו\"ד כמ\"ש רבינו ז\"ל, אך ע\"י הציץ שעשה משה י\"ל שודאי נמשך כי משה גם מדחה בחי' הלעו\"ז דעמלק, וע\"י שהי' נושא תמיד הציץ בודאי לא הי' הפסק.",[["1762","55","<b>שמחו צדיקים בה'</b>: תהלים צז, יב. ראה גם לקו\"ת תבוא מב, ג. תו\"ח ויחי רלח, ג."],["1764","57","<b>דליבא שבזה\"ק</b>: באגה\"ק: דלבא שבזוה\"ק. באוה\"ת שם: דליבא שבזוה\"ק."],["1763","56","<b>כהנא ברעותא דליבא שבזה\"ק</b>: באוה\"ת תצא ע' תתקמא מציין: ע' בזהר פ' שמיני דל\"ט ע\"א. ראה גם במ\"מ הגהות והע\"ק כאן ע' מב."],["1765","58","<b>עבודת מתנה</b>: קרח יח, ז."],["1766","59","<b>כו'</b>: באגה\"ק: וגו'. ראה שינויי נוסחאות — בתניא עם ליקוט פירושים שם ע' שסה."],["1767","60","<b>כהונתכם</b>: באגה\"ק: ליתא."],["1774","67","<b>(דהיינו . . כו')</b>: לשון אגה\"ק שם לפנ\"ז."],["1768","61","<b>היראה ששואלין עליה יגעת ביראה</b>: ראה גם במ\"מ הגהות והע\"ק לאגה\"ק כאן ע' מב."],["1769","62","<b>ואוי לבשר . . בר\"ח</b>: שער היראה פי\"ב (לד, ג ד\"ה עוד בעניני) מצאתי בכת\"י מרגניתא של ר\"מ ע\"ה [ראה ר\"ח מהדורת ירושלים תדש\"ם ע' רכו בהערות]."],["1770","63","<b>כתיב</b>: באגה\"ק: וכתיב. ראה שינויי נוסחאות שם ע' שסו."],["1771","64","<b>וכמטמונים . . ד')</b>: באגה\"ק: וגו'. מתחילה נכתב תיבת כו', אלא שאח\"כ מחקו והוסיף בין השיטין וכמטמונים . . ד')."],["1772","65","<b>כמחפש אוצרות</b>: שם: כמחפש אחר אוצרות. ראה שינויי נוסחאות שם."],["1773","66","<b>זו בתענוגים</b>: באגה\"ק: זו [אהבה בתענוגים]. ראה גם שינויי נוסחאות שם."],["1775","68","<b>בטעמה כי טוב ה'</b>: ע\"פ תהלים לד, ט."],["1777","70","<b>עוה\"ב שנהנין</b>: ראה ברכות יז, א."],["1776","69","<b>עוה\"ב שנהנין</b>: באגה\"ק: עוה\"ב ממש שנהנין. ראה שינויי נוסחאות שם ע' שסה."],["1778","71","<b>הנה היא</b>: באגה\"ק: ליתא. תיבות אלו ניתוספו בין השיטין."],["1779","72","<b>לאדם מלמעלה</b>: שם: לאדם מאליה מלמעלה. ראה שינויי נוסחאות שם ע' שסו."],["1780","73","<b>לאחר</b>: באגה\"ק: אחר."],["1781","74","<b>להגיע</b>: שם: והגיע. ראה שינויי נוסחאות שם."],["1782","75","<b>אזי</b>: בכת\"י המעתיק כאן העתיק אז."],["1783","76","<b>אהבה</b>: שם: האהבה. ראה שינויי נוסחאות שם."],["1784","77","<b>דרכו של איש לחזור</b>: קדושין ב, ב."],["1785","78","<b>כמ\"ש בלק\"א</b>: פמ\"ג."],["1761","54","<b>וע\"ז כתי' . . כמ\"ש בלק\"א</b>: לשון אגה\"ק רסי\"ח."],["1786","79","<b>ועיין בת\"א . . מיין</b>: ויחי מז, ג. מז, ד ואילך. ראה אוה\"ת שה\"ש שבהערה 81."],["1787","80","<b>בת\"ז תיקון ב'</b>: וכ\"ה באוה\"ת שבהערה הבאה. והוא במהדורת מנטובה שי\"ח. אמשטרדם תקכ\"ח [ושם: תקונא תניינא ותליתאה]. ולפנינו תיקון ג (יח, ב).\n\n<b>ב</b> )<i>בת\"א . . אין לה הפסק:</i> ויחי מז, ב (ד\"ה והנה ההפרש].\n\n<b>ג</b> )<i>ובד\"ה ועשית ציץ:</i> תו\"א תצוה פג, ע\"ג ואילך."]]],[2001910209,"תרט\"ו דקל\"ה ע\"ב בד\"ה מה יפית<sup data-n=\"1788\">81</sup>) וכמ\"ש אהבתי אתכם אמר הוי'<sup data-n=\"1789\">82</sup>, ובחי' אהוי\"ר שמלמעלמ\"ט זהו בחי' המשכת אהרן כו', וזהו מ\"ש בזהר שיש ב' בחי' דחילו ורחימו ורחימו ודחילו<sup data-n=\"1790\">83</sup> כנגד ד' אותיות הוי', והיינו כנ\"ל שבחי' דחילו ורחימו הוא בחי' אהוי\"ר הבאה בעבודת האדם מלמטלמ\"ע והוא בחי' ו\"ה של ש' הוי' ובחי' רו\"ד הוא בחי' אהוי\"ר הבאה מלמעלמ\"ט בחי' י\"ה של ש' הוי', ובחי' אהבה זו הבאה מלמעלמ\"ט זהו בחי' אה\"ר שממשיך אהרן כה\"ג לנש\"י<sup data-n=\"1791\">84</sup>, אך א\"א לבוא לבחי' אה\"ר הבאה מלמעלה כ\"א שיהי' לו תחלה בחי' אהוי\"ר מלמטלמ\"ע ואז יוכל לקבל בחי' אהוי\"ר הבאה מלמעלה [ע\"ד מ\"ש בת\"א בד\"ה ויקהל<sup data-n=\"1792\">85</sup> שרצון התחתון הוא כלי לבחי' רצון העליון המאיר ומתגלה בשבת, וע\"ד בחי' חסד עולם דז\"א הוא כלי לבחי' רב חסד דא\"א<sup data-n=\"1793\">86</sup> כמ\"ש בכ\"ד וע' בד\"ה יביאו לבוש מל'<sup data-n=\"1794\">87</sup> שלא נדפס], וזהו ציץ ל' הארה והיינו שהוא בחי' הארת אור האה\"ר הבאה מלמעלמ\"ט.\n<b>והפי'</b> הב' הוא ציץ מל' מציץ, מציץ מן החרכים ל' הבטה וראי', הנה כתי' כי עין בעין יראו (ישעי' נ\"ב ח') וכתי' כי עין בעין נראה (שלח י\"ד י\"ד<sup data-n=\"1795\">88</sup>), נראה אותיות אהרן<sup data-n=\"1796\">89</sup>, והיינו כי אהרן ממשיך בחי' כי עין בעין. והענין הוא דהנה הבריאה",[["1788","81","<b>וע' בס' . . מה יפית</b>: אוה\"ת שה\"ש ח\"ב ע' תרטו ואילך."],["1789","82","<b>אהבתי אתכם אמר הוי'</b>: מלאכי א, ב. ראה פלח הרמון מג\"א כאן ע' שנא."],["1790","83","<b>דחילו ורחימו ורחימו ודחילו</b>: ראה זהר רע\"מ נשא קכג, סע\"א. לעיל מאמר ד\"ה והי' אור הלבנה רפ\"ג. וש\"נ."],["1791","84","<b>אה\"ר שממשיך אהרן כה\"ג לנש\"י</b>: ראה פלח הרמון מג\"א כאן ע' שנא ואילך."],["1792","85","<b>בת\"א בד\"ה ויקהל</b>: ויקהל פז, סע\"ד ואילך."],["1793","86","<b>חסד עולם דז\"א . . דא\"א</b>: ראה אגה\"ק ס\"י. הנסמן בסה\"מ תרכ\"ז כאן ע' קפ."],["1794","87","<b>בד\"ה יביאו לבוש מל'</b>: בסה\"מ שם בהערה כותב: כנראה הכוונה לד\"ה זה להצ\"צ . . ונדפס לקמן [ע' קצז ואילך] . . וראה בהנסמן שם בתחילת המאמר."],["1795","88","<b>כי עין . . שלח י\"ד י\"ד</b>: בדילוג — ראה גם לקמן בהביאור רפ\"ב. סה\"מ תרכ\"ז ע' קנג וע' קפ כאן. תו\"ח בא ח\"א קב, סע\"ב. וש\"נ."],["1796","89","<b>נראה אותיות אהרן</b>: ראה זהר אמור קג, א ובמק\"מ ובהרמ\"ז שם. מאמרי אדה\"א ויקרא ח\"ב ע' תשסז. וש\"נ. שמות ח\"ב ע' שמ. וש\"נ."]]],[2001910210,"יש מאין<sup data-n=\"1797\">90</sup> והיינו לפי שמלכותך מכ\"ע<sup data-n=\"1798\">91</sup> וכמ\"ש כי בי\"ה הוי' צור עולמים<sup data-n=\"1799\">92</sup> וארז\"ל במנחות<sup data-n=\"1800\">93</sup> ובמד\"ר ויקהל<sup data-n=\"1801\">94</sup> ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז שהוא רק משני אותיות, וכמשל ענין המלוכה הוא רק מלך שמו נק' עליהם<sup data-n=\"1802\">95</sup>, וזהו שאנו אומרים ישתבח שמך<sup data-n=\"1803\">96</sup>, והיינו בבחי'<sup data-n=\"1804\">97</sup> מל' כי המקור לכל התהוות הנבראים הוא מבחי' המל', וזהו מ\"ש לכו חזו מפעלות אלקי'<sup data-n=\"1805\">98</sup> אשר שם שמות א\"ת שַמות אלא שֵמות<sup data-n=\"1806\">99</sup> שהכל נברא רק מבחי' שם והארה, ולכן הוא בחי' יש מאין שנתהווה העולם ליש ודבר מבחי' אין. אך הנה כתי' כי אל דעות הוי'<sup data-n=\"1807\">100</sup>, שיש ב' דיעות ד\"ת וד\"ע, והיינו כי ד\"ת הוא כנ\"ל שלמטה היש ולמעלה האין<sup data-n=\"1808\">101</sup>, וד\"ע הוא בהיפוך שלמעלה הוא היש האמיתי ולמטה הוא בחי' אין, ובאמת צ\"ל איך שייך לומר שהעולם וכל הנבראים המה בחי' אין הלא אנו רואי' שלמטה הוא בחי' יש כו'. אך הענין הוא מאחר ששרש ומקור בחי' הנבראי' הוא בחי' אין בחי' שם והארה כנ\"ל שאינו תופס מקום כלל, דבאמת כולא קמי' כלא חשיב<sup data-n=\"1809\">102</sup> (רק שאינו מושג בד\"ת), א\"כ מה שנברא ונראה העולם ליש ודבר אינו שהיא באמת יש ודבר כי הלא גם מקור המהוה בחי' זו הוא ג\"כ רק בחי' אין, כ\"א המכוון כך הוא שהגם שנראה העולם לבחי' יש ודבר כו' מ\"מ יהי' בחי' ביטול היש לאין, והוא מחמת ההתבוננות איך<sup data-n=\"1810\">103</sup> שמקורה ושרשה הוא רק הארה בעלמא בחי' אין, וממילא דעת לנבון נקל<sup data-n=\"1812\">105</sup> שהיש בטל לאין, שהרי האין והיש הם פועל ונפעל שלא יעלה ע\"ד שום אדם שהנפעל יהי' חלוק ומשובח מן הפועל, ודי לבא מן הדין<sup data-n=\"1813\">106</sup> להיות כנדון, א\"כ מובן שהיש בטל לאין המהוה אותו,",[["1797","90","<b>הבריאה יש מאין</b>: ראה תו\"א בשלח סא, סע\"ד. לקו\"ת פ' ראה יט, ג ואילך."],["1798","91","<b>שמלכותך מכ\"ע</b>: תהלים קמה, יג. ראה לקו\"ת אמור לה, ב."],["1799","92","<b>כי בי\"ה . . עולמים</b>: ישעי' כו, ד."],["1800","93","<b>במנחות</b>: כט, ב."],["1801","94","<b>ובמד\"ר ויקהל</b>: בסה\"מ תרכ\"ז ע' קפ כאן: ובמד\"ר. ולעיל שם ע' קכט: ברבות בראשית פי\"ב דף ט\"ו ע\"ב [במהדורת אמשטרדם ת\"א, ולפנינו סימן י]."],["1802","95","<b>מלך שמו נק' עליהם</b>: ראה פיוט אדון עולם. סה\"מ תר\"ם ח\"א ע' רפו. וש\"נ."],["1803","96","<b>ישתבח שמך</b>: ברכת ישתבח."],["1804","97","<b>בבחי</b>: בסה\"מ תרכ\"ז ע' קנג וע' קפ כאן: בחי'."],["1805","98","<b>לכו חזו מפעלות אלקי'</b>: תהלים מו, ט. וראה במנחת שי שם. זהר בראשית נח, ב ובמפרשים שם. שה\"א מז, ב ובהערה 21. תו\"ח וארא ח\"א ס, ד. וש\"נ."],["1806","99","<b>א\"ת שמות אלא שמות</b>: ברכות ז, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשצב. וש\"נ. נ\"ך ע' תעב."],["1807","100","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11."],["1808","101","<b>שלמטה היש ולמעלה האין</b>: ראה גם פלח הרמון מג\"א כאן ע' שנב."],["1809","102","<b>כולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1810","103","<b>ההתבוננות איך</b>: בסה\"מ תרכ\"ז ע' קפ כאן: ההתבוננות זו עצמה מיני' ובי' איך. וראה שם ריש ע' רנד. בהערה הבאה."],["1812","105","<b>דעת לנבון נקל</b>: משלי יד, ו."],["1813","106","<b>ודי לבא מן הדין</b>: ב\"ק כד, סע\"ב (במשנה)."]]],[2001910211,"(ובמ\"א נת' שבחי' היש הוא בחי' כח אלקי המסתתר כמ\"ש אכן אתה אל מסתתר<sup data-n=\"1814\">107</sup>, אך זה הסבר בדרך אחרת להבין ענין בחי' יחודו ית' גם בעולמות הנבראים והנוצרי' והנעשי' כו'), וזהו דכתי' וכל צבא השמים לך משתחוים<sup data-n=\"1815\">108</sup> בבחי' ביטול היש כו'<sup data-n=\"1811\">104</sup>, ואח\"כ יוכל לבוא להשיג בחי' דיעה עליונה איך דכולא קמי' כל\"ח וכל מה שהוא קמי' יותר כלא חשיב יותר בבחי' ביטול אמיתי וזהו כי עין בעין נראה אותיות אהרן כי אהרן ממשיך שיומשך בחי' עין דלעילא בחי' ד\"ע בעין דלתתא בחי' ד\"ת, וזהו ציץ ל' הבטה וכמו שפרש\"י מציץ ל' ראה ראיתי כו' בחי' ראי' והיינו בחי' ראי' דדעת עליון.\n<b>ובאמת</b> ב' הפירושי' של ציץ הוא א'<sup data-n=\"1816\">109</sup> דהיינו כשיש בחי' ד\"ת היינו בחי' ביטול היש לאין שהוא בחי' אהוי\"ר הבאה מלמטלמ\"ע בעבודת האדם כנ\"ל (שהרי בחי' ואהבת את ה' אלקי'<sup data-n=\"1817\">110</sup> שבק\"ש שאת כולל יראה כנודע<sup data-n=\"1818\">111</sup> באה דוקא מהתבוננות בשכמל\"ו<sup data-n=\"1819\">112</sup>, כי אין הלכה כאנשי יריחו<sup data-n=\"1820\">113</sup> שהיו כורכי' את שמע, והיו סומכים פסוק ואהבת לאחד<sup data-n=\"1822\">115</sup> ולא היו אומרי' בשכמל\"ו<sup data-n=\"1821\">114</sup> כי רק משה אמר אחד ואהבת, כי משה מלגאו<sup data-n=\"1823\">116</sup> לכן לא אמר בשכמל\"ו כי הי' קשור בעצמותו ומהותו ית' שהוא בחי' יסו\"א<sup data-n=\"1824\">117</sup> הארת עצמיות חכ' ית', לכן לא הי' אהבתו הנפלאה בבחי' ואהבת שיהי' הוי' בבחי' אלקיך מבחי' בשכמל\"ו שהוא בחי' התפשטות מלכותו ית' מן אוא\"ס ב\"ה אלא הי' כורך את שמע ואחד פשוט<sup data-n=\"1825\">118</sup> לואהבת את ה' אלקיך, וכן היו עושי' אנשי יריחו, אלא שאין הלכה כמותם, כ\"א ההלכה היא שיהי' התקשרות דואהבת מן בחי' מדת מלכותו ית' שנעשה עתיק לעולם שלמטה הימנו<sup data-n=\"1826\">119</sup> (וכמאמר מלך יחיד<sup data-n=\"1827\">120</sup>)",[["1814","107","<b>אכן אתה אל מסתתר</b>: ישעי' מה, טו. ראה גם סה\"מ תרכ\"ט ע' קסג. וש\"נ. תר\"ם ח\"א ע' שי. וש\"נ."],["1815","108","<b>וכל צבא השמים לך משתחוים</b>: נחמי' ט, ו [ושם: וצבא — ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה להבין בתוס' וכו' ב' פי' בציץ על יד הערה 38. (בחלק ההנחות) הנחה ד\"ה שלש רגלים תחג לי על יד הערה 106. סה\"מ תרל\"ג ח\"ב ע' תקג. וראה גם תו\"א תשא פה, ד־ סה\"מ תרכ\"ז ע' קנד וע' קפא כאן: (וכ)ענין וכל צבא. לקמן בהביאור על יד הערה 62. לקמן מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' ובהערה לא. תו\"א מקץ לב, סע\"ב. לקו\"ת במדבר יז, א. תו\"ח בראשית א, ג. תרל\"ג ח\"א ע' רנט]."],["1811","104","<b>וממילא דעת . . היש כו'</b>: בסה\"מ תרכ\"ז כאן נדפס בפנים בין חצאי ריבוע [והרי הוא . . משתחוים] ובהערה לשם: ”קטע זה נרשם . . במהדו\"ק . . ואח\"כ העביר ע\"ז את הקולמוס כאן. וציין . . בנייר בפ\"ע . . ולע\"ע לא נמצא נייר זה\". ואולי הכוונה להבא להלן בפנים — ראה לעיל הערה 1."],["1816","109","<b>ב' הפירושי' . . א'</b>: ראה גם תו\"ח תצוה ח\"ב שנו, א. וראה גם שם שסג, ג."],["1817","110","<b>ואהבת את ה' אלקי'</b>: ואתחנן ו, ה."],["1818","111","<b>שאת כולל יראה כנודע</b>: ראה לקו\"ת ואתחנן ז, ד. בפלח הרמון בחוקותי ע' תפז כותב: ”כמבואר ברשימה דיונתי הנאמר [ע\"י כ\"ק אדמו\"ר הצ\"צ] בשנת תר\"ב\" — נדפס בפלח הרמון שה\"ש ע' מב."],["1819","112","<b>בשכמל\"ו</b>: פסחים נו, א."],["1820","113","<b>אין הלכה כאנשי יריחו</b>: ראה פסחים נה ב (במשנה). נו, א. ראה מאמרי אדה\"ז אתהלך לאזניא ע' מג. תו\"ח יתרו ח\"ב רנד, ב. וש\"נ."],["1822","115","<b>לאחד</b>: ואתחנן ו, ד."],["1821","114","<b>והיו סומכים . . בשכמל\"ו</b>: ראה ר\"ח שם."],["1823","116","<b>משה מלגאו</b>: ת\"ז תי\"ג כט, א. ראה לקו\"ת פינחס עח, ג ואילך."],["1824","117","<b>משה . . יסו\"א</b>: ראה גם לקו\"ש שמות כרך ו ע' 244 ואילך. לעיל על יד הערה 13 מלקו\"ת להאריז\"ל."],["1825","118","<b>פשוט</b>: כ\"ה בגוכתי\"ק."],["1826","119","<b>מלכותו ית' . . שלמטה הימנו</b>: ראה גם ע\"ח שער כסה\"כ שמ\"ו, פ\"ב ופ\"ה. מאמרי אדה\"ז ענינים ע' א. מאמרי אדה\"א בראשית ע' לז. וש\"נ."],["1827","120","<b>מלך יחיד</b>: ברכת ישתבח."]]],[2001910212,"וזהו שיעקב שהי' מלבר<sup data-n=\"1828\">121</sup> אמר בשכמל\"ו מאחר שכך עלה ברצונו הפשוט במח' תחלה, (כפרז\"ל<sup data-n=\"1829\">122</sup> בתחלת ס' אנשי<sup data-n=\"1830\">123</sup>, כי\"ק אזמ\"ו<sup data-n=\"1831\">124</sup>, ובמ\"א פי' רז\"ל<sup data-n=\"1832\">125</sup> שקודם חב\"ר<sup data-n=\"1833\">126</sup> שהיו נשמות גבוהות היו יכולים להגיע לואהבת ע\"י התבוננות שמע כו' אחד לבד<sup data-n=\"1834\">127</sup>, אבל אחר חב\"ר<sup data-n=\"1835\">128</sup> א\"י להגיע לואהבת אלא ע\"י בשכמל\"ו קבעומ\"ש<sup data-n=\"1836\">129</sup>), וענין בחי' התפשטות מלכותו ית' הוא בחי' קבעומ\"ש, שז\"ע בשכמל\"ו היינו בחי' ביטול\n\n<i>נרשם בשולי היריעה ולא נסמן מקומו בפנים:</i>\nברבות ויחי פצ\"ח<sup data-n=\"8278\">ד</sup> שאמרו השבטים ליעקב כשם כו' אף הוא פירש בשפתיו בשכמל\"ו וכ\"ה ס\"פ ואתחנן<sup data-n=\"8279\">ה</sup> רק שם אמרו שאמר בלחישה, ובפסחים פ\"ד דנ\"ו ע\"א ציקי קדירה עי' בנייר בפ\"ע<sup data-n=\"8280\">ו</sup>.\nלעיין בזה (ב<sup data-n=\"8281\">ז</sup>\nבתחלתו<sup data-n=\"8282\">ח</sup> ד\"ה אנשי יריחו בסופו<sup data-n=\"8283\">ט</sup> בס' אנשי יריחו פי' שיעקב מלבר לכן אמר בשכמל\"ו שזהו בפי' דברי הגמ' פסחים דנ\"ו שם הלשון אמרו יעקב, וע' בגמ' הטעם שאומרים בלחישה, ועוי\"ל לפי שבמד\"ר ס\"פ ואתחנןה אמרו שיעקב אמרו בלחישה, אך לפי שפי' בד\"ה אנשי יריחו הנ\"ל שמשה לא אמרו לפי שהי' מיסו\"א, צ\"ל הלא יעקב יו\"ד עקב<sup data-n=\"8284\">י</sup>, ויש ע\"ז כ\"פ ומהם יעקב יסו\"א<sup data-n=\"8285\">יא</sup> ממשיך עד העקב, יעקב יבקע כשחר<sup data-n=\"8286\">יב</sup> בקיעת החשך שיאיר בחי' וארוכתך בחי' א\"א<sup data-n=\"8287\">יג</sup>, וי\"ל שיעקב אמר זה לבניויד שהם י\"ב בקר<sup data-n=\"8289\">טו</sup> בבריאה<sup data-n=\"8288\">יד</sup> והוא עצמו הי' כורך את שמע, אך לפי מ\"ש בלק\"ת בד\"ה שמע בפ' ואתחנן די\"א ע\"ג שעד חורבן ב\"ר היו יכולים לבוא ואהבת מבחי' אחד, וכן אנשי יריחו כו' א\"כ אינו שייך שהשבטי' היו צריכין לבשכמל\"ו דוקא (אך באמת אינו קושיא כלל כמשי\"ת לקמן), וי\"ל שיעקב אמר זה נגד מה שראה שיהי' בסוף הדורות אחר חוב\"ר, וגם יש לחלק בין ישראל ליעקב, ישראל שיר אל<sup data-n=\"8290\">טז</sup> בפ' ואתחנן בד\"ה ואהבת סוף סעי' א'<sup data-n=\"8291\">יז</sup> אל נהירא דחכמתא<sup data-n=\"8292\">יח</sup>, ישראל כי שרית<sup data-n=\"8293\">יט</sup> לאחר הבירור מה שנשתלשל מש' אלקי', וקבלת ק\"ך צירופי' דאלקי'<sup data-n=\"8294\">כ</sup> אחרי'<sup data-n=\"8295\">כא</sup>, ואפי' ממ\"ח צירופי' אחרונים<sup data-n=\"8296\">כב</sup> שז\"ע ברזל שנת' בענין מחיצה של ברזל בד\"ה מגלה נקראת<sup data-n=\"8297\">כג</sup> כי נא' אליו כי שרית ותוכל, ועש\"ז נק' ישראל רק בשם יעקב זהו שייך לבשכמל\"ו.\nוע' בד\"ה אנשי יריחו הנ\"ל שמפרש בשכמל\"ו מלכותו ית' שנעשה עתיק<sup data-n=\"8298\">כד</sup> לאצי'<sup data-n=\"8299\">כה</sup> א\"כ אין קושי' כלל ממה שהובא לעיל מענין יבקעיב, וארוכתך (שזהו בלק\"ת פ' צו<sup data-n=\"8300\">כו</sup> בד\"ה ל' ענין משמח חתן) שי\"ל שע\"י בחי' יעקב עבדי קבעומ\"ש שנת' בד\"ה שמע שבלק\"ת פ' ואתחנן<sup data-n=\"8301\">כז</sup> עי\"ז ממשיך הבקיעה שיבקע בחי' ישת חשך סתרו<sup data-n=\"8302\">כח</sup> ויאיר בחי' ארוכתך, כי שמו שנקרא ישראל אפ\"ל שזהו כבר מבורר מאחר כי שריתיט ותוכל ויעקב יוד עקב יורד לברר בירורים ועי\"ז יהי' בקיעת החשך שיאיר אור בחי' וארוכתךיג בחי' א\"א.\nוע'<sup data-n=\"8303\">כט</sup> בד\"ה שיר כו' ממעמקי' בלקו\"ת<sup data-n=\"8304\">ל</sup> שבחי' ישראל לא חטא ותירץ ענין שובה ישראל.\nצ\"ע<sup data-n=\"8305\">לא</sup> מה שע\"י קבעומ\"ש זה בא ג\"כ לבחי' מאדךלב שלמעלה מהכלי (כי בכל לבבך פי' יחידה שבנפש<sup data-n=\"8307\">לג</sup> ובכל נפשךלב אהבה שמתקבל במוח בחי' כלי) אלא הכלי לזה הוא תושבע\"פ ע' בלק\"ת<sup data-n=\"8306\">לב</sup> ד\"ה שמע בסופו, ואולי יש לקשרו עם מה שא' יעקב בשכמל\"ו שז\"ע ציקי קדירה<sup data-n=\"8308\">לד</sup>, ודוקא ע\"י בירור דיעקב יוד בעקבי דוקא ציקי קדירה, עי\"ז יתעלה למעלה מבחי' ישראל עלה במח'<sup data-n=\"8309\">לה</sup> כ\"א לאשתאבא בגופא דמלכא<sup data-n=\"8310\">לו</sup> כמו שפי' רש\"י על מארז\"ל ע\"ש של הקב\"ה שיהי' שמם הוי'<sup data-n=\"8311\">לז</sup>, שזהו בחי' גבוה יותר מהפי' שהוי' יהי' בבחי' אלקיך אלקה שלך<sup data-n=\"8312\">לח</sup> כו', ומה שבא לבכל מאדך אין זה סותר למה שאה\"ר בא ע\"י אהרן דוקא שהרי מאדך הכל מלמטלמ\"ע, ואה\"ר דאהרן זהו מתנה מלמעלמ\"ט כמ\"ש באגה\"ק סי' י\"ח, ועוד דזהו הכל בבחי' מלמטלמ\"ע עצמו בבחי' ביטול היש לבד ועדיין לא הגיע לבחי' ביטול אמיתי דונחנו מ\"ה<sup data-n=\"8313\">לט</sup> דמשה ואהרן, וקרוב הדבר שבחי' בכל מאדך זה זהו לפי' המשנה בכל מאדך בכל ממונך<sup data-n=\"8314\">מ</sup>, מאחר שנותן יותר מרגילותו הרי כופה ומשבר א\"ע א\"כ זהו ע\"ד שפי' במ\"א בענין מס\"נ באחד מסירת הרצון<sup data-n=\"8315\">מא</sup> כי מה לי קטלא כולו או קטלא פלגא<sup data-n=\"8316\">מב</sup>, אבל מה שפי' במ\"א בכל מאדך אה\"ר<sup data-n=\"8317\">מג</sup>, זהו בעבודה בחי' היותר גבוה, וע' בד\"ה בך\"ה בכסליו<sup data-n=\"8318\">מד</sup> פי' צדקה קטרת שנעשה מדוממים<sup data-n=\"8319\">מה</sup> מעשה המצות, יש לחברו למ\"ש בד\"ה קחו מאתכם מעלת אתכפיא<sup data-n=\"8320\">מו</sup> שזהו עבודת עבד וכמ\"ש בד\"ה שמע הנ\"ל די\"א ע\"ג בסופו וז\"ל וכל דבר שאינו בביטול רצון אינו נק' עבודה כלל.",[["1828","121","<b>שיעקב שהי' מלבר</b>: ראה לעיל הערה 116."],["1829","122","<b>כפרז\"ל</b>: כפי' רבינו ז\"ל — כ\"ק אדמו\"ר הזקן."],["1830","123","<b>בתחילת ס' אנשי</b>: צילום ממנו בהספרי' 1003. נדפס בשינויים במאמרי אדה\"ז אתהלך לאזניא ע' מג.\nהטעם להשינויים — כי הוגהו מר' ליב מאהאליווער. שברוב המקומות הגי' רק בסגנון הלשון, ובכמה מקומות ערך מחדש את כל המאמר, בשינוי התחלת המאמר, קדימה ואיחור ועוד. ראה אתהלך לאזניא ע' רסג. ע' שיח — שיט מהדורת תשמ\"ב. וראה גם הערה כד."],["1831","124","<b>כי\"ק אזמ\"ו</b>: כתב יד קדש אדוני זקני מורי ורבי — כ\"ק אדמו\"ר האמצעי."],["1832","125","<b>ובמ\"א פי' רז\"ל </b> [ רבינו ז\"ל]<b></b>: לקו\"ת ואתחנן יא, ג ואילך [הועתק כאן בפנים בהוספות ובשינויים]."],["1833","126","<b>חב\"ר</b>: חורבן בית ראשון."],["1834","127","<b>שמע כו' אחד לבד</b>: בלקו\"ת שם: לבד שמע ישראל כו' ואהבת."],["1835","128","<b>חב\"ר</b>: שם: החורבן."],["1836","129","<b>קבעומ\"ש</b>: שם: שהוא קבלת עול מ\"ש.\n\n<b>ד</b> ) <b>ברבות ויחי פצ\"ח</b>: סימן ג.\n\n<b>ה</b> ) <b>ברבות . . ס\"פ ואתחנן</b>: פ\"ב, לה.\n\n<b>ו</b> ) <b>עי' בנייר בפ\"ע</b>: אולי הכוונה לפיסקא הבאה.\n\n<b>ז</b> ) <b>לעיין בזה (ב</b>: ראה לעיל בתחילת המאמר הערה 1.\n\n<b>ח</b> ) <b>בתחלתו</b>: תיבה זו נרשמה באמצע השיטה.\n\n<b>ט</b> ) <b>ד\"ה אנשי יריחו בסופו</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ע' מד.\n\n<b>י</b> ) <b>יעקב יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ.\n\n<b>יא</b> ) <b>יעקב יסו\"א</b>: ראה גם לקו\"ת בלק עב, ג. ביאוה\"ז תזריע עב, ג.\n\n<b>יב</b> ) <b>יעקב יבקע כשחר</b>: ישעי' נח, ח. ראה בהערה הבאה.\n\n<b>יג</b> ) <b>יעקב . . וארוכתך בחי' א\"א</b>: ראה לקו\"ת צו ח, סע\"ד ואילך (צויין אליו בפיסקא הבאה).\n\n<b>טו</b> ) <b>י\"ב בקר</b>: ראה מלכים-א ז, כה. מד. דברי הימים-ב ד, טו.\n\n<b>יד</b> ) <b>לבניו שהם י\"ב בקר בבריאה</b>: ראה זהר ויחי רמא, א.\n\n<b>טז</b> ) <b>ישראל שיר אל</b>: ראה ת\"ז בהקדמה ג, א. ת\"י כה, א. ע\"ח שער פרצופי זו\"ן של\"א, פ\"ה. תו\"ח בשלח ח\"א רמד, א ואילך.\n\n<b>יז</b> ) <b>בפ' ואתחנן . . א'</b>: בלקו\"ת שם יג, א.\n\n<b>יח</b> ) <b>אל נהירא דחכמתא</b>: ראה זהר לך צד, א. צו ל, ב לא, א. אחרי סה, א. מאמרי אדה\"א דרושי חתונה ח\"א ע' קצ. סה\"מ תרל\"ב ח\"א ס\"ע ר ואילך.\n\n<b>יט</b> ) <b>ישראל כי שרית</b>: וישלח לב, כט.\n\n<b>כ</b> ) <b>ק\"ך צירופי' דאלקי'</b>: ראה ע\"ח שער הזיווגים שט\"ו, פ\"ו. שער השמות שמ\"ד, פ\"ה. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז.\n\n<b>כא</b> ) <b>ק\"ך צירופי' דאלקי' אחרי'</b>: ראה לקו\"ת להאריז\"ל בשלח בסופו ד\"ה עמלק. מאו\"א מערכת מר אות צב. לקמן רפ\"ד. פ\"ו. לקמן מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' על יד הערה ד. אוה\"ת תצוה כאן ע' א'תרצא. ע' א'תשלט. סה\"מ תר\"ם ח\"א ע' קב. וש\"נ.\n\n<b>כב</b> ) <b>ממ\"ח צירופי' אחרונים</b>: ראה פע\"ח שחה\"מ שכ\"א, פ\"ה. שער הכוונות ענין הפסח דרוש א'. תו\"א יתרו קט, ד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'סא. סה\"מ תר\"ם ח\"א ע' שנה. וש\"נ.\n\n<b>כג</b> ) <b>שנת' בענין . . בד\"ה מגלה נקראת</b>: אולי הכוונה למאמר ד\"ה זה משנת תרט\"ז. וראה אוה\"ת שבהערה כא. פלח הרמון מג\"א כאן ס\"ע שנג ואילך.\n\n<b>כד</b> ) <b>בד\"ה אנשי יריחו . . עתיק לאצי'</b>: כ\"ה בבוך 1003 שבהערה 123. אבל במאמרי אדה\"ז אתהלך לאזניא ע' מד: עתיק דבריאה. ראה גם הערה 123.\n\n<b>כה</b> ) <b>מלכותו ית' שנעשה עתיק לאצי'</b>: ראה תו\"א מקץ לה, ד. לקו\"ת חוקת סז, ב. מאמרי אדה\"ז ענינים ע' א ובהערה שם ובמ\"מ לשם. וראה גם סה\"מ תר\"ם ח\"ב ע' תרכד. וש\"נ.\n\n<b>כו</b> ) <b>בלק\"ת פ' צו</b>: ח, סע\"ד ואילך.\n\n<b>כז</b> ) <b>בד\"ה שמע שבלק\"ת פ' ואתחנן</b>: ראה הערה 125.\n\n<b>כח</b> ) <b>ישת חשך סתרו</b>: תהלים יח, יב.\n\n<b>כט</b> ) <b>וע'</b>: נרשם בהיפך העמוד ולא צויין לאן שייך.\n\n<b>ל</b> ) <b>בד\"ה שיר. . בלקו\"ת</b>: דרושים לר\"ה סב, סע\"ג ואילך.\n\n<b>לא</b> ) <b>צ\"ע</b>: נרשם בגוכתי\"ק באותו עמוד עם ההגה שבאה כאן בפנים וביניהם הניח כמה שורות פנויים ובשולי היריעה נרשם זה ולא צויין מקומו בפנים.\n\n<b>לג</b> ) <b>בכל לבבך פי' יחידה שבנפש</b>: לקו\"ת שם, יא, ג.\n\n<b>לב</b> ) <b>לבחי' מאדך . . ובכל נפשך . . בלק\"ת</b>: ואתחנן יא, ד.\n\n<b>לד</b> ) <b>ציקי קדרה</b>: פסחים נו, א. ראה מאמרי אדה\"ז אתהלך לאזניא ע' מג. אוה\"ת בראשית ח\"א ע' 98 ואילך. תו\"ח ויקהל ח\"ב תד, ג ואילך.\n\n<b>לה</b> ) <b>ישראל עלה במח'</b>: ראה ב\"ר פ\"א, ד. לעיל מאמר ד\"ה הקבצו ושמעו רפ\"ב ובהנסמן שם.\n\n<b>לו</b> ) <b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם סה\"מ תר\"ם ח\"א ע' צז. וש\"נ.\n\n<b>לז</b> ) <b>שפי' רש\"י . . שיהי' שמם הוי'</b>: כ\"ה בכ\"מ — ראה לקמן מאמר ד\"ה וידבר כו' קדושים תהיו ובהערה 43.\n\n<b>לח</b> ) <b>שהוי' יהי' . . אלקה שלך</b>: ראה תו\"א תצוה פב, רע\"ג. לקו\"ת שה\"ש מב, ב.\n\n<b>לט</b> ) <b>דונחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 140.\n\n<b>מ</b> ) <b>בכל מאדך בכל ממונך</b>: ברכות נד, א. ראה גם סה\"מ תר\"ם ח\"ב ע' תרכה. וש\"נ.\n\n<b>מא</b> ) <b>מס\"נ באחד מסירת הרצון</b>: ראה תו\"א מקץ לו, ב. סהמ\"צ להצ\"צ ע' קפ.\n\n<b>מב</b> ) <b>מה לי קטלא . . פלגא</b>: ראה ב\"ק סה, א.\n\n<b>מג</b> ) <b>בכל מאדך אה\"ר</b>: ראה לקו\"ת מטות פא, סע\"ג ואילך. עקב טז, ג. פ' ראה לא, ד. סהמ\"צ להצ\"צ ע' קנד.\n\n<b>מד</b> ) <b>בד\"ה בך\"ה בכסליו</b>: תו\"א וישב כט, ג.\n\n<b>מה</b> ) <b>קטרת שנעשה מדוממים</b>: ראה גם תו\"א שם כט, ב. ש\"א יא, א ובהערה 28. סה\"מ תר\"ם ח\"ב ע' לג. תרמ\"ג ע' מו.\n\n<b>מו</b> ) <b>בד\"ה קחו מאתכם מעלת אתכפי'</b>: תו\"א ויקהל פט, ג ואילך. קיד, ג ואילך. ראה גם סה\"מ תרל\"ח ע' שמט. וש\"נ."]]],[2001910213,"הרצון גשמי שזהו בחי' עבודה וקבלת עול מלכותו ית' שאין מלך בלא עם<sup data-n=\"1837\">130</sup> לשון עוממות שהוא יש ודבר<sup data-n=\"1838\">131</sup>, ואעפ\"כ מבטל רצונו מכל וכל, וביטול רצון היינו כפשוטו",[["1837","130","<b>שאין מלך בלא עם</b>: בחיי וישב לח, ל. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["1838","131","<b>עם לשון עוממות שהוא יש ודבר</b>: ראה גם (בנוסף ללקו\"ת כאן) שער היחוד והאמונה פ\"ז. סה\"מ תרכ\"ט ע' שי. לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום הערה 19."]]],[2001910214,"לעשות הפך מה שהלב חומד הן בבחי' סור מרע הן בבחי' ועשה טוב<sup data-n=\"1839\">132</sup>, בסור מרע הוא בחי' קדש עצמך במותר לך<sup data-n=\"1840\">133</sup>, ובבחי' ועשה טוב ענין בחי' ההיפך הוא כמארז\"ל אינו דומה שונה פרקו<sup data-n=\"1841\">134</sup> מאה פעמים לשונה פרקו מ\"פ ואחד, שהפעם האחד שהוא יותר מרגילותו חשוב ממאה אשר הוא רגילותו, וכן בצדקה שהפרוטה שהוא נותן יותר מרגילותו חשוב ביותר מן הרגילות, וזהו קבעומ\"ש דבשכמל\"ו, ועי\"ז יבוא לואהבת את שכולל יראה ונמצא שע\"י בחי' ביטול היש לאין בחי' ד\"ת באים לבחי' אהוי\"ר כו') ואזי נמשך ע\"י אהרן כהנא רבא בחי' אה\"ר להיות עין בעין נראה שיאיר בחי' עין דלעילא בעין דלתתא, וזהו בחי' אה\"ר הבאה מלמעלה בבחי' מתנה וכמ\"ש עבודת מתנה אתן כו'.",[["1839","132","<b>סור מרע . . ועשה טוב</b>: תהלים לד, טו."],["1840","133","<b>קדש עצמך במותר לך</b>: ספרי פ' ראה יד, כא. יבמות כ, א. ראה תניא ספכ\"ז וספ\"ל. שע\"ת נז, ב. מאמרי אדה\"א שמות ח\"א ע' ה. וש\"נ."],["1841","134","<b>אינו דומה שונה פרקו</b>: ראה חגיגה ט, ב. הל' ת\"ת לאדה\"ז פ\"ב, ה\"ג. תניא פט\"ו. לקו\"ת פ' ראה כב, ב ואילך. לקו\"ש וארא ח\"א ע' 117 ואילך."]]],[2001910215,"ג) <b>והנה</b> כמ\"כ יש ב' בחי' אלו דד\"ת ודעת עליון בתפלה, כי הנה תחלה הוא בחי' שמע שם עיי\"ן<sup data-n=\"1842\">135</sup>, פי' עין הוא ז' מדות כשהם כלולים מיו\"ד ושם עי\"ן הוא בחי' הארה מעין דהיינו בחי' מל' שהוא בחי' אין שממנו נברא העולם ליש כו', וזהו שמקדימין פסוד\"ז דהיינו איך שהמלאכים וכל צבא השמים אומרים שירה ובטלים לפניו ית' שזהו מ\"ש הללוי' הללו את ה' מן השמים<sup data-n=\"1843\">136</sup>, הללו<sup data-n=\"1844\">137</sup> את שם ה' כי הוא צוה ונבראו<sup data-n=\"1845\">138</sup> כו', וזהו שאומרים עשר פעמים הללויה נגד עשרה מאמרות<sup data-n=\"1846\">139</sup> בכדי להתבונן כנ\"ל שכל צבא השמים המה בטלים ואזי גם הוא יוכל לבוא לבחי' ביטול היש שזהו ההתבוננות בבחי' שמע שם עי\"ן בחי' ביטול היש ד\"ת, ואח\"כ בחי' ישראל הוא למעלה מבחי' ד\"ת ע\"ד מ\"ש בן פורת יוסף<sup data-n=\"1847\">140</sup> בן פורת עלי עין למעלה",[["1842","135","<b>שמע שם עיי\"ן</b>: ואתחנן ו, ד. זהר רע\"מ פינחס רלו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשמא. וש\"נ. סה\"מ תרל\"ג ח\"א ע' רב ואילך. וש\"נ."],["1843","136","<b>הללוי' הללו את ה' מן השמים</b>: תהלים קמח, א."],["1844","137","<b>הללו</b>: בסה\"מ תרכ\"ז ע' קנד וע' קפא כאן: יהללו."],["1845","138","<b>יהללו . . צוה ונבראו</b>: תהלים שם, ה. ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 79."],["1846","139","<b>עשר פעמים . . עשרה מאמרות</b>: ראה גם (בנוסף להערה 137) תולעת יעקב — לר' מאיר ן' גבאי — סוד פסוקי דזמרה ד\"ה גרסינן בסופו (ירושלים תשכ\"ז ע' 22). סידור יעב\"ץ תפלת שחרית מזמור הללוי' הללו א-ל בקדשו."],["1847","140","<b>בן פורת יוסף</b>: ויחי מט, כב."]]],[2001910216,"מבחי' עין דד\"ת, וע\"י התבוננו' בבחי' ה' אלקינו ה' אחד הוא בחי' ד\"ע להכיר איך דכולא קמי' כל\"ח וזהו בחי' אחד שהוא ז' רקיעים וארץ<sup data-n=\"1848\">141</sup> עכ\"ז כולא קמי' כל\"ח ובטלי' לגבי בחי' אלף אלופו של עולם<sup data-n=\"1849\">142</sup> שהוא היש האמיתי כו', וכאשר מתחלה יש בחי' ד\"ת ביטול היש דהיינו בחי' יחו\"ת אזי יוכל לבוא לבחי' ד\"ע בחי' יחו\"ע<sup data-n=\"1850\">143</sup>.\n<b>ועפי\"ז</b> יובן ענין חטא דור המדבר במה שאמרו היש הוי' בקרבנו<sup data-n=\"1851\">144</sup> אם אין, וארז\"ל במד\"ר<sup data-n=\"1852\">145</sup> ובילקוט רמז רס\"ב<sup data-n=\"1853\">146</sup> משל לבן<sup data-n=\"1854\">147</sup> שהי' מורכב על כתפו של אביו ושאל איה אבא כו' השליך האב את הבן בא הכלב ונשכו, כך הקב\"ה הוציא את בנ\"י ממצרים ושאלו היש הוי' השליך אותם מיד ויבא עמלק<sup data-n=\"1855\">148</sup>. ולהבין ענין החטא שלהם, הענין הוא דהחטא שלהם הי' מה שלא האמינו שנבואת משה הי' גבוה משאר הנביאים (כמו אפי' אברהם יצחק ויעקב), ובאמת כתי' וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי<sup data-n=\"1856\">149</sup>, ופי' הרמב\"ן<sup data-n=\"1857\">150</sup> שם שדי הוא מקור לניסים מוסתרים אכן ש' הוי'<sup data-n=\"1858\">151</sup> הוא מקור לנסים הנגלים, ולהם הראו נסים נגלים יוצאים מדרכי הטבע לגמרי כמו יצ\"מ וקי\"ס שהם נסים בגלוי א\"כ הי' להם להאמין שנבואת משה הי' הגבה מכל הנביאים, והם לא האמינו ואמרו היש הוי' כו'. וע\"פ הקבלה היש הוי' בחי' ז\"א אם אין הוא בחי' מל'<sup data-n=\"1859\">152</sup>, והם לא ידעו אם נמשך מבחי' ז\"א ד\"ע או מד\"ת בחי' אין מל', וזהו החטא שלהם<sup data-n=\"1860\">153</sup> מיד ויבא עמלק כו', והיינו שקליפת עמלק היא מסתרת על בחי' ד\"ע שהוא הקליפה הלעו\"ז כו', שזהו ענין יודע את רבונו<sup data-n=\"1861\">154</sup> ומכוין למרוד בו, שהוא הלעו\"ז נגד בחי' ד\"ע כו'.\n<b>וזהו</b> מ\"ש הנה זה עומד<sup data-n=\"1862\">155</sup> אחר כתלינו משגיח מן החלונות מציץ מן החרכים, פי' כתלינו הנה כתי' ביחזקאל (סי' ד' ג') ונתתה אותה קיר ברזל בינך ובין העיר ולמדו רז\"ל מזה בברכות פ' אין עומדין משחרב בהמ\"ק חומת של ברזל<sup data-n=\"1863\">156</sup> מפסיק",[["1848","141","<b>אחד שהוא ז' רקיעים וארץ</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן — ראה לקמן בהביאור הערה 55."],["1849","142","<b>אלופו של עולם</b>: לשון ב\"ר פ\"כ, ב."],["1850","143","<b>יחו\"ת . . יחו\"ע</b>: זהר בהקדמה יב, א."],["1851","144","<b>היש הוי' בקרבנו</b>: בשלח יז, ז."],["1852","145","<b>במד\"ר</b>: ראה שמו\"ר פכ\"ו, ב."],["1853","146","<b>ובילקוט רמז רס\"ב</b>: ראה ילקוט שמעוני בשלח שם."],["1854","147","<b>לבן</b>: בסה\"מ תרכ\"ז כאן ע' קפב: לבן מלך. אבל שם ס\"ע קנד כבפנים."],["1855","148","<b>ויבא עמלק</b>: בשלח יז, ח."],["1856","149","<b>וארא . . לא נודעתי</b>: וארא ו, ג."],["1857","150","<b>ופי' הרמב\"ן</b>: וארא שם, ב. ראה גם אוה\"ת וארא ריש ע' קלז [ושם: הרמב\"ן ר\"פ שמות]. אחרי כרך ב ע' תקסד [ושם: ואי' ברמב\"ן]. פ' ראה ע' תשפג־ תהלים (יהל אור) ע' קנה (ושם: הרמב\"ן והבחיי ר\"פ וארא). פ' ראה ע' תשפט [ושם: הרמב\"ן בפי' החומש]."],["1858","151","<b>שם שדי . . ש' הוי'</b>: ראה גם סה\"מ תרכ\"ט ע' מט. וש\"נ. ס\"ע צו ואילך. תר\"ל ע' סב. סה\"מ מלוקט ח\"ה ע' קלח ואילך."],["1859","152","<b>היש הוי' בחי' ז\"א . . מל'</b>: ראה זהר אד\"ר נשא קכט, א. שלח קנח, ב. אוה\"ת תצוה כאן ע' א'תרצח וע' א'תשמה. (וראה גם מאמרי אדה\"א בראשית ע' קצח. וש\"נ)."],["1860","153","<b>החטא שלהם</b>: ראה אוה\"ת שם. פלח הרמון מג\"א כאן ע' שנה."],["1861","154","<b>עמלק . . יודע את רבונו</b>: ראה תו\"א תצוה פג, סע\"ד. פה, ד. לעיל מאמר ד\"ה זכור את יום השבת פ\"ד הערה טו."],["1862","155","<b>הנה זה עומד</b>: שה\"ש ב, ט."],["1863","156","<b>בברכות . . חומת של ברזל</b>: ראה שם לב, ב."]]],[2001910217,"בין ישראל לאביהם שבשמים, ולכאו' צ\"ל הלא מצינו קיר לשבח כמ\"ש גבי אלישע נעשה נא עלית קיר קטנה ונשים לו שם כסא ושולחן ומטה ומנורה<sup data-n=\"1864\">157</sup>, ואיתא בזהר שזהו בחי' ד' תיקוני שכינתא<sup data-n=\"1865\">158</sup>, וגם ארז\"ל ע\"פ ויסב חזקיהו פניו אל הקיר<sup data-n=\"1866\">159</sup> מכאן למתפלל שלא יהי' דבר חוצץ בינו לבין הקיר<sup data-n=\"1867\">160</sup> כו'. והענין הוא דהנה איתא בזהר שקיר הוא בל' יון<sup data-n=\"1869\">162</sup> אדון<sup data-n=\"1868\">161</sup> והיינו בחי' שם אדנ\"י<sup data-n=\"1870\">*163</sup> שזהו ההפרש בין ש' הוי' לש' אד' כי ש' הוי' כשמו כן הוא בלא קץ ותכלה ואם הי' בריאות<sup data-n=\"1871\">163</sup> העולמות מש' הוי' לא הי' העולם בבחי' יש ודבר כ\"א בבחי' ביטול, וכדי שיהי' העולמות בבחי' יש זהו ע\"י ש' אד'<sup data-n=\"1872\">164</sup> שמסתיר ומעלים על אור קדושת שם הוי' כדי שיהי' מקור לעולמות הנבראים ונפרדים כו' כנ\"ל, והנה זהו עבודת האדם להמשיך בחי' ש' הוי' להיות יחוד הוי' ואלקים (כי שם אד' וש' אלקים הכל אחד<sup data-n=\"1873\">165</sup>) כמ\"ש שמש ומגן הוי' אלקים<sup data-n=\"1874\">166</sup>, וזהו כותל דקדושה כי כותל הוא כ\"ו ת\"ל<sup data-n=\"1875\">167</sup>, כ\"ו הוא גימט' של ש' הוי'<sup data-n=\"1876\">168</sup> ת\"ל גימט' ה\"פ אלקים<sup data-n=\"1877\">169</sup>, להיות יחוד הוי' ואלקים, וזהו מ\"ש ויסב חזקי' פניו אל הקיר והיינו שהמשיך בחי' פניו שהוא מ\"ש יאר הוי' פניו<sup data-n=\"1878\">170</sup> בבחי' קיר בחי' אדון ש' אד'<sup data-n=\"1879\">171</sup>, וכמ\"כ המתפלל צריך שלא יהי' דבר חוצץ בינו לבין הקיר כו' כי",[["1864","157","<b>נעשה נא . . ומטה ומנורה</b>: וכ\"ה גם בסה\"מ תרכ\"ז כאן ע' קנה וע' קפב — מלכים-ב ד, י [ושם: מטה ושלחן וכסא ומנורה]."],["1865","158","<b>ומטה . . ד' תיקוני שכינתא</b>: ראה זהר תרומה קלג, א. מאמרי אדה\"א דברים ח\"ב ע' תח ואילך. וש\"נ. תו\"ח וארא ח\"א עד, סע\"ב. וש\"נ. הנסמן בסה\"מ תרכ\"ז כאן ע' קנה."],["1866","159","<b>ויסב חזקיהו פניו אל הקיר</b>: ישעי' לח, ב."],["1867","160","<b>מכאן למתפלל . . לבין הקיר</b>: ראה ברכות ה, ב. אוה\"ת ישעי' כרך א ע' רכח ואילך."],["1869","162","<b>בל' יון</b>: אור החמה לזהר שם."],["1868","161","<b>שקיר הוא בל' יון אדון</b>: ראה זהר ויחי רכח, ב. ר\"ח ע\"ז יא, ב ד\"ה יום תגלחת. אוה\"ת ישעי' שם. תצוה כאן ע' א'תשלז."],["1870","*163","<b>אדון . . שם אדנ\"י</b>: נסמן בסמוך הערה 171."],["1871","163","<b>בריאות</b>: בסה\"מ תרכ\"ז כאן: בריאת. ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 117."],["1872","164","<b>בריאות העולמות מש' הוי' . . ש' אד'</b>: ראה גם לעיל מאמר ד\"ה ראה קראתי בשם ספ\"ב ופ\"ג."],["1873","165","<b>שם אד' וש' אלקים הכל אחד</b>: ראה לקו\"ת ש\"ש סה, ד. לעיל מאמר ד\"ה ראה קראתי בשם ובהערה 94."],["1874","166","<b>שמש ומגן הוי' אלקים</b>: תהלים פד, יב."],["1875","167","<b>כותל הוא כ\"ו ת\"ל</b>: ראה זהר רע\"מ משפטים קטז, רע\"א. אוה\"ת ישעי' שם ע' רכט."],["1876","168","<b>כ\"ו הוא . . ש' הוי'</b>: ראה זהר שם. שו\"ע (ואדה\"ז) או\"ח הל' ציצית סכ\"ד, ס\"ה (ס\"ז)."],["1877","169","<b>ת\"ל גימט' ה\"פ אלקים</b>: מאו\"א מערכת כותל אות טז.\nמאו\"א זה הובא באוה\"ת ישעי' שם [ושם חסר. ובבוך 1133 ע' קעב גוכתי\"ק הצ\"צ ניתוסף (אחרי תיבת ”אלקים\"): (הג\"ה והוא ג\"כ גימ' שקל וגימ' נפש וגימט' משפט עכ\"ה).\nוכן באוה\"ת שם שו\"ה תל — ”אליו דוקא\" בבוך הנ\"ל: אליו שהיא המ' עם הצדיק שע\"י מתייחדים שניהם ובודאי שנק' היא כותל בהיות לה כל הכבוד הזה דוקא.\nוכן באוה\"ת שם שו\"ה פונים — ”בו והוא\" בבוך הנ\"ל: בו והטעם כי השפע והמזון מהיסוד למטה והעיקר ביסוד עכ\"ל וכ\"כ במא\"א אות ת' סכ\"ג תל יסוד שהכל פונים בו.\nוכן באוה\"ת שם שו\"ה ומצד — ”כ\"ו שם הוי'\" בבוך הנ\"ל הנה תיבות אלו נרשמו בגוכתי\"ק עה\"ג מוקפים בעיגול שהכוונה למחוק תיבות אלו. וכנראה שהמעתיק לא הבין והעתיקם."],["1878","170","<b>יאר הוי' פניו</b>: נשא ו, כה."],["1879","171","<b>אדון ש' אד'</b>: ראה זהר בראשית טז, סע\"ב. שמות יג, א. שער היחוד והאמונה רפ\"ז. ברכות ז, ריש ע\"ב. אוה\"ת ש\"ש ע' א'תפז ואילך. וראה גם אוה\"ת ויצא ח\"א רא, ב."]]],[2001910218,"המכוון הוא להמשיך בחי' הוי' באמרו ברוך אתה הוי', ברוך לשון המשכה<sup data-n=\"1880\">172</sup> בשם אד', לכן צריך שלא יהי' דבר חוצץ כו', וזהו כתלינו כותל דקדושה.\n(ד) <b>והנה</b> לעו\"ז<sup data-n=\"1881\">173</sup> הוא בחי' כותל דעמלק המסתיר ומעלים שלכן נק' קיר ברזל כי ברזל הוא ב\"פ ק\"ך<sup data-n=\"1882\">174</sup> והיינו נגד בחי' ק\"כ צירופי אלקיםכ דקדושה ונגד ק\"כ צירופי אלקים אחריםכא, ולכן הוא מסתיר ומעלים לגמרי. וזהו מ\"ש במד\"ר ס\"פ תרומה<sup data-n=\"1883\">175</sup> ע\"פ וזאת התרומה אשר תקחו מאתם זהב וכסף ונחושת<sup data-n=\"1884\">176</sup>, זהב זו בבל כסף זו מדי נחושת זו יון, אבל ברזל אין כתיב כאן, והיינו כי ברזל הוא נגד מחריבי בהמ\"ק<sup data-n=\"1886\">178</sup> שא\"א לבררה כלל, וכמשארז\"ל במד\"ר שם שגם לע\"ל<sup data-n=\"1885\">177</sup> לא יקובל ממנה נדבה כו', והיינו כמ\"ש ראשית גוים עמלק ואחריתו עדי אובד<sup data-n=\"1887\">179</sup>, והיינו שאחרית של עמלק היינו מחריבי בהמ\"ק א\"א לברר אותה כלל כ\"א שברתו<sup data-n=\"1888\">180</sup> זהו תיקונו כמשי\"ת לקמן.\n<b>וזהו</b> דכתיב (מ\"א וא\"ו ז') והבית בהבנותו אבן שלימה כו' והמקבת וכל כלי ברזל<sup data-n=\"1889\">181</sup> לא נשמע בבית בהבנותו וכמו שארז\"ל (מדות פ\"ג משנה ד') שהברזל פוסל בנגיעה, והיינו מטעם הנ\"ל שמבחי' ברזל א\"א לברר כלל, וזהו בחי' עמלק כי חושבנא דדין כחושבנא דדין<sup data-n=\"1890\">182</sup> שברזל עם הכולל גימ' עמלק<sup data-n=\"1891\">183</sup>, שזהו מ\"ש מלחמה להוי' בעמלק<sup data-n=\"1892\">184</sup> והיינו כמו שארז\"ל אין השם שלם ואין הכסא שלם<sup data-n=\"1893\">185</sup> עד שימחה זרעו של עמלק, פי' אין השם שלם שי\"ה אינו מאיר בו\"ה<sup data-n=\"1894\">186</sup>, פי' יו\"ד ה' של ש' הוי'",[["1880","172","<b>ברוך ל' המשכה</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' רפ\"ג. וש\"נ."],["1881","173","<b>לעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["1882","174","<b>ברזל הוא ב\"פ ק\"כ</b>: מאו\"א מערכת ברזל אות מה [ושם: ע\"ה עם הכולל]. הובא באוה\"ת תצוה כאן ע' א'תרצב וע' א'תשלט."],["1883","175","<b>במד\"ר ס\"פ תרומה</b>: ראה שם פל\"ה, ה."],["1884","176","<b>וזאת התרומה . . וכסף ונחושת</b>: תרומה כה, ג."],["1886","178","<b>נגד מחריבי בהמ\"ק</b>: בשמו\"ר שם: שנמשל בו אדום שהחריבו בהמ\"ק. ראה הערה בסה\"מ תרכ\"ז כאן ע' קנו."],["1885","177","<b>ברזל . . שא\"א לבררה כלל . . שגם לע\"ל</b>: ראה גם פלח הרמון מג\"א כאן ע' שנד. סה\"ש תשנ\"ב ח\"א ע' 232 וע' 235 ובהערות שם."],["1887","179","<b>ראשית גוים . . עדי אובד</b>: בלק כד, כ. ראה גם לעיל הערה 34."],["1888","180","<b>שברתו</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן ע' קפג. אבל בע' קנו: שבירתו."],["1889","181","<b>והמקבת וכל כלי ברזל</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן ע' קפג וע' קנו. ועד\"ז לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה להבין בתוס' וכו' ב' פי' בציץ על יד הערה 80. במלכים שם: ומקבות והגרזן כל כלי ברזל.\nראה גם לקמן בהביאור פ\"ד. אוה\"ת תצוה כאן ע' א'תרצב. ע' א'תשלח. ע' א'תשלט. ע' א'תשמא. מג\"א ריש ע' ריז: וכל כלי ברזל."],["1890","182","<b>חושבנא דדין כחושבנא דדין</b>: ע\"פ איכ\"ר פ\"א, כ. ב\"ר פס\"ח, יב כגי' הערוך מערכת סולם. בחיי ולק\"ט ויצא כח, יב."],["1891","183","<b>שברזל עם הכולל גימ' עמלק</b>: ראה גם אוה\"ת תצוה כאן ע' א'תרצא וע' א'תשלט. סה\"מ תר\"ם ח\"ב ע' תשנה. וש\"נ. לקמן בהביאור פ\"ד ובהנחה שם על יד הערה 76."],["1892","184","<b>מלחמה להוי' בעמלק</b>: בשלח יז, טז."],["1893","185","<b>אין השם . . הכסא שלם</b>: ראה תנחומא ס\"פ תצא. רש\"י ולקח טוב ס\"פ בשלח. לקו\"ש י\"ג סיון כרך כג ע' 268 הערה 33."],["1894","186","<b>שי\"ה אינו מאיר בו\"ה</b>: ראה תו\"א מג\"א צה, ג. לקו\"ת פ' ראה יח, ג. מאמרי אדה\"א שמות ח\"ב ע' תפב ואילך. דברים ח\"ב ע' שסז ואילך. ראה גם לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך על יד הערה 100 ואילך."]]],[2001910219,"הוא בחי' סוכ\"ע כי בינה מקור המקיפים<sup data-n=\"1895\">187</sup> ועמלק מונע הגילוי מבחי' יו\"ד ה' בו\"ה, וכמו\"כ אין הכסא שלם כי כסא הוא כס א'<sup data-n=\"1896\">188</sup>, פי' שמכוסה בחי' אלף אלופו ש\"ע, כי הנה צריך להיות נכון כסאך מאז<sup data-n=\"1897\">189</sup>, פי' שכדי שיהי' נכון כסאך זהו מאז דוקא היינו כשמאיר מא' בז' ז' מדות<sup data-n=\"1898\">190</sup> ועמלק הוא היפך זה ונק' ע\"ש עמלק מפני שעמלק הוא ראשית גוים כמ\"ש ראשית גוים עמלק, פי' גוים הם ז' מדות הרעות בחי' ז' אומות<sup data-n=\"1899\">191</sup> הכנעני כו' והפריזי<sup data-n=\"1900\">192</sup> וראשית גוים אלו זהו עמלק<sup data-n=\"1901\">193</sup> דוקא, וזהו מארז\"ל הקנאה והתאוה והכבוד<sup data-n=\"1902\">194</sup> כו' הוא בחי' מדות רעות וכבוד הוא בחי' לבושי' שהוא היפך לבושי כה\"ג שהי' בקדושה, וזהו אין השם שלם ואין הכסא שלם עד שימחה זרעו של עמלק, ולאחר שימחה זרעו של עמלק אז אח\"כ יהי' הגילוי בחי' י\"ה בו\"ה.\n<b>ובזה</b> יובן מה שחטא שאול במה שרצה להקריב קרבנות<sup data-n=\"1903\">195</sup> משלל עמלק, והיינו כנ\"ל שעמלק הוא קיר ברזל היפך בחי' בהמ\"ק דקדושה שלכן לא הי' ברזל בבנין בהמ\"ק והברזל פוסל בנגיעה לכן א\"א להביא קרבנות ג\"כ משלל עמלק כי א\"א להעלות בחי' עמלק כלל, וזהו שאמר לו שמואל מאסת את דבר ה' שהוא היפך מבחי' בהמ\"ק<sup data-n=\"1904\">196</sup>, ולכן משחרב בהמ\"ק כותל של ברזל<sup data-n=\"1905\">197</sup> מפסיק בין ישראל לאביהם<sup data-n=\"1906\">198</sup> כו', כי כשזה נופל זה קם<sup data-n=\"1907\">199</sup>, ופי' בין ישראל לאביהם שההפסקה היא מחמת ישראל<sup data-n=\"1908\">200</sup> כי לפניו ית' אין דבר חוצץ כי כחשכה כאורה<sup data-n=\"1909\">201</sup> אכן מחמת בחי' נש\"י הוא ההפסק, שזהו מ\"ש עוונותיכם המה מבדילים<sup data-n=\"1910\">202</sup> שע\"י העון הוא מסך",[["1895","187","<b>בינה מקור המקיפים</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."],["1896","188","<b>כסא כס אלף</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קמו. הנסמן בסה\"מ תרל\"ח ע' רפז."],["1897","189","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["1898","190","<b>מא' בז' ז' מדות</b>: ראה גם לעיל מאמר ד\"ה זכור את יום השבת ובהערה 45."],["1899","191","<b>ז' מדות . . ז' אומות</b>: ראה תו\"א מג\"א צה, א. צט, סע\"א. מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. ש\"א סא, ב ובהערה 20. תו\"ח יתרו ח\"ב ער, ג. וש\"נ."],["1900","192","<b>הכנעני כו' והפריזי</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן ע' קנז וע' קפג. ראה יהושע ג, י [ושם: ואת הפריזי]. שמות ג, ח. יז. תשא לג, ב [ושם נמנו ששה אומות]."],["1901","193","<b>וראשית גוים אלו זהו עמלק</b>: ראה גם אוה\"ת תצוה כאן ע' א'תרצד וע' א'תשמא."],["1902","194","<b>הקנאה והתאוה והכבוד</b>: אבות פ\"ד, מכ\"א."],["1903","195","<b>שחטא שאול . . קרבנות</b>: ראה גם סה\"מ תרכ\"ז כאן ע' קפג בשולי היריעה."],["1904","196","<b>מאסת את דבר ה' . . בהמ\"ק</b>: ראה גם סה\"מ תרכ\"ז כאן ע' קפד בשולי היריעה."],["1905","197","<b>משחרב בהמ\"ק כותל של ברזל</b>: ראה גם אוה\"ת תצוה כאן ע' א'תרצא שמשחרב בהמ\"ק יש כותל ומחיצה . . דברכות דף ל\"ב ע\"ב. לעיל הערה 156. פסחים פה, ב."],["1906","198","<b>כותל . . בין ישראל לאביהם</b>: ראה גם פלח הרמון מג\"א כאן ס\"ע שנד ואילך."],["1907","199","<b>כשזה נופל זה קם</b>: ראה רש\"י תולדות כה, כג."],["1908","200","<b>שההפסקה היא מחמת ישראל</b>: ראה גם תו\"ח תצוה ח\"ב כאן שסה, א. אוה\"ת תצוה כאן ע' א'תרצא וע' א'תשלח ואילך. סה\"מ ליקוט ח\"ב ע' קמז [המשך תרס\"ו מהדורת תשנ\"ט ע' תרי]."],["1909","201","<b>כחשכה כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["1910","202","<b>עוונותיכם המה מבדילים</b>: ישעי' נט, ב [ושם: היו — וכ\"ה גם בסה\"מ תרכ\"ז כאן ע' קנז וע' קפד]."]]],[2001910220,"מבדיל בחי' עמלק קיר ברזל. והעצה לזה הוא בחי' תשובה שע\"י לב נשבר ונדכה<sup data-n=\"1912\">204</sup> עי\"ז שוברים הכותל להיות מציץ מן החרכי'<sup data-n=\"1911\">203</sup> ומשגיח מן החלונות<sup data-n=\"1913\">205</sup>, והיינו אף שאין שוברים כל הכותל עכ\"פ עושים עי\"ז חלונות וחרכים להיות מאיר אור א\"ס ב\"ה ע\"י חלונות וחרכים כנ\"ל, וכמו שע\"י החלון מאיר בחי' השמש, כמ\"כ ע\"י חלונות אלו מאיר בחי' שמש הוי' כו'. וכדי לשבר את הכותל של ברזל הנ\"ל להיות נעשה בה חלונות וחרכים זהו ע\"י בחי' משה, וזהו ועשית ציץ כו' שמשה הוא העושה ומשבר בחי' כותל דעמלק, ולכן תלוי מלחמת עמלק במשה כמ\"ש והי' כאשר ירים משה ידו<sup data-n=\"1914\">206</sup> וגבר ישראל וכאשר יניח כו'. וביאור הענין הנה התורה נק' תורת משה כמ\"ש זכרו תורת משה עבדי<sup data-n=\"1915\">207</sup>, וכמ\"ש תורה צוה לנו משה<sup data-n=\"1916\">208</sup>, וצ\"ל מפני מה נק' התורה תורת משה, הנה ארז\"ל במד\"ר פ' ויקרא<sup data-n=\"1917\">209</sup> ע\"פ גבורי כח עושי דברו לשמוע בקול דברו<sup data-n=\"1918\">210</sup> בנוהג שבעולם משאוי שקשה לאחד נוח לשנים, לשנים נוח לארבעה, שמא תאמר משאוי שקשה לס' רבוא נוח לאחד, כך ס' רבוא ישראל לא יכלו לקבל הדבור מפי הקב\"ה שנאמר אם יוספים אנחנו<sup data-n=\"1919\">211</sup> ומשה שמע הדיבור מפי הקב\"ה וחיה וזהו גבורי כח כו' לשמוע בקול דברו, פי' שמע הדבור הוא בחי' דבר ה', והנה הדיבור הוא גילוי ההעלם שהוא גילוי המחשבה כו', ופי' בקול דברו היינו בפנימיות הקול<sup data-n=\"1920\">212</sup> דהיינו מה שמאיר בבחי' הקול ובחי' זו לא יוכלו נש\"י לקבל כי זהו בחי' פנימיות דבר ה' הוא בחי' ד\"ע כ\"א משה שהי' מן המים משיתיהו<sup data-n=\"1921\">213</sup>, פי' בחי' מים עליונים שלמעלה מן הרקיע המבדיל ופרסא ראשונה לכן הי' יכול לקבל בחי' זו, ולכן נמשכה התורה ג\"כ ע\"י משה דוקא עד שנק' תורת משה עבדי כי הוא עלה שמים וירד<sup data-n=\"1922\">214</sup> כו', ומחמת שהי' בחי' גבוה מאד מן המים משיתיהו לכן הי' יכול ג\"כ להעביר קליפת עמלק, והיינו מחמת עוצם הגילוי שהמשיך משה ממילא נדחה הרע של עמלק, וכמו שע\"י האור ממילא נדחה החושך, ולכן תלוי מלחמת עמלק במשה דוקא, וזהו ועשית ציץ פי' שמשה הוא העושה הציץ לאהרן כהנא רבא להיות כי משה המשיך בחי' תורה עי\"ז ממילא נדחה החשך, זהב טהור הוא ע\"ד מ\"ש ממולח טהור קדש<sup data-n=\"1923\">215</sup> פי' מעורב טהור בקדש להיות",[["1912","204","<b>לב נשבר ונדכה</b>: תהלים נא, יט. ראה גם סה\"מ תר\"ם ח\"ב ע' תקמ הערה ז."],["1911","203","<b>לב נשבר . . החרכי' . . מן החלונות</b>: ראה לקמן בהביאור ספ\"ד. סה\"מ ליקוט ח\"ב ע' קמח [המשך תרס\"ו מהדורת תשנ\"ט ע' תריא]."],["1913","205","<b>מציץ מן החרכי' . . החלונות</b>: ראה לקו\"ת שמע\"צ צא, ג ואילך."],["1914","206","<b>והי כאשר ירים משה ידו</b>: בשלח יז, יא."],["1915","207","<b>זכרו תורת משה עבדי</b>: מלאכי ג, כב."],["1916","208","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["1917","209","<b>במד\"ר פ' ויקרא</b>: ראה שם פ\"א, א [בשינויים]. ילקוט שמעוני ויקרא א, א (רמז תכז]. ראה גם לקו\"ת במדבר יד, א. אוה\"ת תצוה כאן ע' א'תשמח."],["1918","210","<b>גבורי כח . . לשמוע בקול דברו</b>: תהלים קג, כ."],["1919","211","<b>אם יוספים אנחנו</b>: ואתחנן ה, כב."],["1920","212","<b>בקול . . בפנימיות הקול</b>: ראה לקו\"ת פ' ראה כג, סע\"א ואילך."],["1921","213","<b>מן המים משיתיהו</b>: שמות ב, י. ראה לקמן בהביאור פ\"ה. מאמרי אדה\"א שמות ח\"ב ע' שצד ואילך. וש\"נ. תו\"ח שמות ח\"א מג, א. וש\"נ. ראה גם פלח הרמון מג\"א כאן ע' שנו."],["1922","214","<b>עלה שמים וירד</b>: משלי ל, ד ובמפרשים שם."],["1923","215","<b>ממולח טהור קדש</b>: תשא ל, לה. ראה גם לקו\"ת ויקרא בהוספות נא, ב. נשא כט, ד."]]],[2001910221,"נמשך בחי' קדש בטהור שבחי' זו היא שרש נש\"י כמ\"ש נשמה שנתת בי טהורה היא<sup data-n=\"1924\">216</sup>.\n(ה) <b>ופתחת</b> עליו פתוחי חותם<sup data-n=\"1925\">217</sup>, הנה ארז\"ל חותמו של הקב\"ה אמת<sup data-n=\"1926\">218</sup> אני ראשון ואני אחרון<sup data-n=\"1927\">219</sup> ומבלעדי אין אלקים, ואין אמת אלא תורה<sup data-n=\"1928\">220</sup>, ונמשלה לחותם כמו החותם כאשר היא חקוקה על האבן טוב הנה מחמת רוב בהירות האבן אין יכולים לקרות האותיות כ\"א עד שיחתום בהחותם על השעוה הנה מחמת גסות השעוה ניכרים האותיות הטיב<sup data-n=\"1929\">221</sup>, אך עכ\"פ הנה האותיות שעל השעוה הם האותיות ממש שעל האבן טוב, כך יובן בנמשל למעלה שהתורה הגם שירדה למטה ונתלבשה בדברים גשמיים הנה עכ\"ז שורש התורה היא היא ממש כמו שהיא הגבה למעלה רק שנתלבשה בדברים גשמי' כו', ולכן ע\"י בחי' התורה נדחה הרע של עמלק, וזהו חותם אותיות חומת<sup data-n=\"1930\">222</sup> והיינו שע\"י החותם דתורה נדחה בחי' החומת בחי' קיר ברזל דעמלק. אך הנה כ\"ז הוא בחי'<sup data-n=\"1931\">223</sup> תורת משה דהיינו כשלומד התורה בבחי' ביטול כמו משה שהי' בבחי' ביטול כמ\"ש ונחנו מהלט, כמו\"כ צ\"ל למוד התורה ג\"כ בבחי' ביטול. קדש להוי'<sup data-n=\"1932\">224</sup> פי' בפרד\"ס<sup data-n=\"1934\">226</sup> שהוא בחי' המשכת קדש להוי'<sup data-n=\"1933\">225</sup>. וביאור הענין הנה יש קדש וקדוש, קדוש הוא בחי' קדש וא\"ו<sup data-n=\"1935\">227</sup>, המשכת בחי' הוא\"ו כדי שיהי' אחריו בחי' ה' אחרונה שזהו מה שאומרים קדוש ק\"ק ה' צבאות<sup data-n=\"1936\">228</sup>, והיינו שכדי שיהי' בחי' ה' צבאות זהו ע\"י בחי' וא\"ו, וזהו קדש וא\"ו היינו המשכת הוא\"ו, משא\"כ בחי' קדש הוא מובדל. והנה כתי' שאו ידיכם קדש<sup data-n=\"1937\">229</sup> וברכו את הוי', וזהו בחי' קדש להוי' המשכת בחי' קדש להוי' בבחי' ברכה כמ\"ש וברכו את הוי' שזהו בחי' ברכה והמשכה בשם הוי'. ועוי\"ל בפי' קדש להוי'<sup data-n=\"1938\">230</sup> ע\"ד משארז\"ל קדש למד מלמטה והוי' מלמעלה<sup data-n=\"1939\">231</sup> א\"כ ש' הוי' גבוה מבחי' קדש, אך באמת שניהם אמת, כי",[["1924","216","<b>נשמה . . טהורה היא</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם סה\"מ תר\"ם ח\"א ע' נב. וש\"נ."],["1925","217","<b>ופתחת עליו פתוחי חותם</b>: המשך הכתוב ועשית ציץ זהב טהור — תצוה כח, לו."],["1926","218","<b>חותמו של הקב\"ה אמת</b>: שבת נה, א."],["1927","219","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו. ב\"ר פפ\"א, ב."],["1928","220","<b>ואין אמת אלא תורה</b>: ראה ירושלמי ר\"ה פ\"ג, ה\"ח. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שסט."],["1929","221","<b>הטיב</b>: בסה\"מ תרכ\"ז כאן: היטב."],["1930","222","<b>חותם אותיות חומת</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"ד. מבו\"ש ש\"ו, ח\"א דרוש ח. הנסמן בסה\"מ תרל\"ח ע' קפא הערה 1367."],["1931","223","<b>הוא בחי'</b>: בסה\"מ תרכ\"ז כאן: הוא כשהתורה הוא בחי'."],["1932","224","<b>קדש להוי'</b>: המשך הכתוב ועשית ציץ — תצוה כח, לו."],["1934","226","<b>בפרד\"ס</b>: בסה\"מ תרכ\"ז כאן ע' קפה: בפרדס. ובע' קנט כבפנים. כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["1933","225","<b>פי' בפרד\"ס . . קדש להוי'</b>: ראה שם שעה\"כ שכ\"ג, פי\"ח מערכת ציץ. אוה\"ת תצוה כאן ע' א'תשלב ואילך."],["1935","227","<b>קדש . . קדוש . . וא\"ו</b>: ראה לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י הערה 112."],["1936","228","<b>קדוש ק\"ק ה' צבאות</b>: ישעי' ו, ג."],["1937","229","<b>שאו ידיכם קדש</b>: תהלים קלד, ב. ראה לקו\"ת שה\"ש כא, סע\"ב ואילך."],["1938","230","<b>ועוי\"ל בפי' קדש להוי'</b>: ראה תו\"א תצוה כאן פג, ג. פד, א. אוה\"ת תצוה כאן ע' א'תשלד."],["1939","231","<b>קדש למד . . מלמעלה</b>: שבת סג, ב. סוכה ה, א. ראה גם תו\"ח תצוה ח\"ב שנו, א הערה 3."]]],[2001910222,"הנה כתי' ויקרא הוי' הוי'<sup data-n=\"1940\">232</sup> שיש ב' שמות הוי' שם הוי' דלעילא ושם הוי' דלתתא, והנה לגבי בחי' ש' הוי' דלתתא שהוא מקור להתהוות העולמות כנ\"ל א\"כ קדש להוי' הוא בחי' המשכה בשם הוי', אך לגבי ש' הוי' דלעילא הנה בחי' קדש למטה במדרגה ולכן קדש למד מלמטה והוי' מלמעלה כו'. והי' על מצח אהרן כו' תמיד לרצון<sup data-n=\"1941\">233</sup>, פי' מצח חופה על המוחין פי' להיות כי אף כשמתבונן הטיב ומוליד בנפשו בחי' אהוי\"ר אשר עי\"ז מאיר בחי' אה\"ר, הנה הוא רק בשעת התפלה אבל אחר התפלה חולפת ועוברת האה\"ר לזה הוא בחי' המצח בחי' נצחון, והיינו שמחמת ההתבוננות יהי' נעשה אצלו הסכם חזק להיות יתד תקוע במקום נאמן<sup data-n=\"1942\">234</sup>, וזהו תמיד לרצון שההסכם שנעשה הוא תמיד כו', שגם לאחר התפלה שחולף ועובר ההתבוננות מ\"מ ישאר ההסכם הנעשה ע\"י התבוננות התפילה כו'.\n(וא\"ו) <b>ומעתה</b> יובן מ\"ש ויקרא אל משה, ובבלעם נא' ויקר אלקים כו' לשון טומאה כמ\"ש אשר לא יהי' טהור מקרה לילה שלכאו' צ\"ל איך נופל הלשון מקרה על נבואה שבלעם הי' נביא בלעו\"ז נגד בחי' משה בקדושה<sup data-n=\"1943\">235</sup>, הנה על עמלק אמרו<sup data-n=\"1944\">236</sup> שהוא כקוף בפני אדם [והיינו כמ\"ש במאו\"א אות קוף סי' א'<sup data-n=\"1945\">237</sup> הובא בעה\"כ של הסה\"ד<sup data-n=\"1946\">238</sup> שס\"א נגד הקדושה הם כקוף בפני האדם<sup data-n=\"1947\">239</sup>, והוא היפך ה\"א דקדושה<sup data-n=\"1948\">240</sup>], פי' קוף בפני האדם כי הנה איתא בספרי'<sup data-n=\"1949\">241</sup> שהקוף הוא היפך בחי' הה\"א<sup data-n=\"1950\">242</sup>, כי הה\"א הוא בחי' ג' קוין<sup data-n=\"1951\">243</sup> ב' קוין מחוברים רומזים לבחי' מחשבה ודבור דקדושה והקו הנפסק רומז לבחי' המעשה דקדושה ועמלק הוא היפך זה ממש שזהו פי' כקוף כמו תמונת קוף הוא ג\"כ ב' קוין מחוברים אכן קו השלישי נמשך למטה, והיינו שממשיך המח' דיבור ומעשה בקליפות, וזהו כקוף בפני האדם, כי אדם",[["1940","232","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה תו\"א בשלח סא, ד ואילך. סה\"מ תרל\"ח ע' נה. וש\"נ. לעיל מאמר ד\"ה והי' אור הלבנה פ\"ג. לקמן בהביאור סוף פיסקא קדש להוי'."],["1941","233","<b>והי' על מצח . . תמיד לרצון</b>: תצוה כח, לח. ראה תו\"א תצוה פג, ד. לקמן בהביאור פיסקא זו. סה\"מ תרכ\"ט ע' עו ואילך. וש\"נ."],["1942","234","<b>יתד תקוע במקום נאמן</b>: ע\"פ ישעי' כב, כה. כג."],["1943","235","<b>שבלעם הי' . . משה בקדושה</b>: ראה לעיל פ\"א. וש\"נ. מאמרי אדה\"א ויקרא ח\"א ע' שלז."],["1944","236","<b>על עמלק אמרו</b>: ראה גם סה\"מ תרכ\"ז כאן ס\"ע קפה."],["1945","237","<b>במאו\"א אות קוף סי' א'</b>: הועתק לשונו באוה\"ת שמואל-ב ע' נ — נמצא בבוך 1133 גוכתי\"ק ל, ב.\n[ושם שו\"ה גם נדפס ר\"ק וצ\"ל: ר\"ן. שם שו\"ה הוא\"ו נדפס י וצ\"ל: ו. וכן צ\"ל בספר הערכים חב\"ד מערכת אותיות התורה אות קו\"ף ריש ע' שכז. שם שו\"ה דם נדפס י וצ\"ל: ו]."],["1946","238","<b>הובא בעה\"כ של הסה\"ד</b>: בשינויים קלים — בערכי הכינויים של הסדר הדורות אות קוף בתחילתו."],["1947","239","<b>שס\"א נגד . . האדם</b>: שם: וקו\"ף נק' ס\"א כקוף בפני אדם הפך הקדושה."],["1948","240","<b>והוא היפך ה\"א דקדושה</b>: שם: גם אות זו הפך ה\"ה (הה') [וזה הובא שם לפני הקטע שלפנ\"ז]."],["1949","241","<b>איתא בספרי'</b>: ראה זהר תרומה קמח, ב. מאו\"א ועה\"כ שם. זהר הרקיע (יא, א) לבראשית ג, א [שער מאמרי רשב\"י שם (מ, א)]. הדרת מלך סי' ע\"ד וסי' ע\"ה."],["1950","242","<b>שהקוף הוא היפך בחי' הה\"א</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תקצח. אוה\"ת תרומה ע' א'תקיד — ע' א'תקטו. תצוה ע' א'תשנא."],["1951","243","<b>הה\"א . . ג' קוין</b>: ראה תו\"א מג\"א צה, סע\"ב. לקו\"ת בלק סז, סע\"א. אוה\"ת שם."]]],[2001910223,"הוא ג\"כ מחדו\"מ<sup data-n=\"1952\">244</sup> א' בחי' מחשבה ד\"מ הוא דבור ומעשה, ועמלק הוא בחי' קוף שממשיך בחי' מחדו\"מ בקליפות, וזהו עמלק עמל ק', פי' שהעמל שלו להמשיך בחי' הקוף דהיינו להיות רגליה יורדות מות<sup data-n=\"1953\">245</sup>, וזהו העיקר העמל שלו שזהו מ\"ש ורהבם עמל ואון<sup data-n=\"1954\">246</sup> כו'.\n<b>ולכן</b> נק' נבואה שלו ע\"ד מקרה כו', כי הנה איתא בס\"י ברית כרותה<sup data-n=\"1955\">247</sup> בין עשר אצבעות ידיו ובין עשר אצבעות רגליו ברית הלשון מכוון כנגד ברית המעור, והיינו שכמו שיש פגם בברית המעור כן יש פגם בברית הלשון, ולכן איתא בספרים שכאשר פוגם בברית הלשון אזי יוכל לבוא ח\"ו לפגם ברית המעור<sup data-n=\"1956\">248</sup>, והיינו כמו שהפגם ברית המעור הוא כאשר יוצא השפע פנימיות לחיצוניות כן הוא ממש ברית הלשון כאשר מדבר דברים בטלים אשר לא לה' המה וכ\"ש רכילות ולה\"ר שנמשך ג\"כ בחי' הדבור שלו לבטלה שהדבור הוא ג\"כ שפע פנימיות שנלקחה מן עצם הנפש כמ\"ש ויהי האדם לנפש חיה ות\"י לרוח ממללא<sup data-n=\"1957\">249</sup> כו', כך יובן למעלה ג\"כ שכאשר נמשך השפעת בחי' דבר נבואה לבלעם הוא כדוגמת מקרה כו', והיינו שנמשך הארת הדבור למקום הקליפות ויקר אלקים שבחי' זו נמשך מחמת בחי' אלקים כי יש ק\"כ צירופי אלקיםכ דקדושה, ולעו\"ז יש ק\"כ צירופי אלקים אחריםכא דקליפה, והנה מבחי' מ\"ח צירופים אחרוניםכב יכול בלעם ג\"כ לקבל ולכן נק' בחי' מקרה כו', משא\"כ גבי משה כתי' ויקרא ל' חיבה וכמ\"ש בזהר ל' אוקיר אנוש מפז ל' יקר, והנה יקר וקיר דקדושה גימט' כתר<sup data-n=\"1958\">*250</sup> ולעו\"ז קרי דעמלק ובלעם וקיר ברזל גימט' כרת* כתר<sup data-n=\"1959\">250</sup> דקליפה, והיינו שע\"י בחי' משה כתר<sup data-n=\"1961\">251</sup> דקדושה נדחה בחי' כרת כתר דקליפה בחי' עמלק<sup data-n=\"1960\">*251</sup>.",[["1952","244","<b>אדם . . מחדו\"מ</b>: ראה גם לקו\"ת בהעלותך לא, ג. מאמרי אדה\"א הנחות תקע\"ז ע' טו. וש\"נ. סה\"מ תרל\"ח ע' שעט. וש\"נ."],["1953","245","<b>רגליה יורדות מות</b>: לשון הכתוב משלי ה, ה."],["1954","246","<b>ורהבם עמל ואון</b>: תהלים צ, י."],["1955","247","<b>איתא בס\"י ברית כרותה</b>: ראה שם בסופו. פ\"א, מ\"ג."],["1956","248","<b>איתא בספרים . . בברית הלשון . . המעור</b>: ראה ראשית חכמה שער הקדושה פי\"א (קסז, א ואילך). פי\"ז (רט, ג). של\"ה שער האותיות אות ש (קח, א). כש\"ט קה\"ת סשי\"ח. או\"ת משפטים קה\"ת לה, ד. מאמרי אדה\"ז תקס\"ד ע' לט-מ. כתובים ח\"א ע' עג. אוה\"ת בחוקותי כרך ג' ריש ע' תתקלז (בספרים). סה\"מ תרכ\"ז כאן ע' קפו. תר\"ם ח\"א ס\"ע רכג ואילך."],["1957","249","<b>ויהי האדם . . ות\"י לרוח ממללא</b>: בראשית ב, ז ובתרגום יונתן שם (וכ\"ה גם בסה\"מ תרכ\"ז כאן. תרל\"ה ח\"א ע' רכט. לקמן מאמר ד\"ה וענין מתיבתא דרקיע על יד הערה 38. ד\"ה להבין וכו' זאת תהי' תורת המצורע על יד הערה 59).\nויש להעיר שבכ\"מ מציינים לתרגום אונקלוס — ראה תו\"א מקץ מב, ריש ע\"ב. לקו\"ת בחוקותי מה, ד. ועוד. סה\"מ תרכ\"ז ע' קלה. ע' רלד."],["1958","*250","<b>יקר וקיר . . גימט' כתר</b>: הובא גם לקמן בהביאור מאמר ד\"ה להבין וכו' בענין הציץ על יד הערה 245. ועד\"ז לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ועשית ציץ על הערה 110."],["1959","250","<b>קרי . . וקיר . . גימט' . . כתר</b>: הובא גם לקמן שם על יד הערה 243. וראה גם לקמן בהנחה שם על יד הערה 111."],["1961","251","<b>משה כתר</b>: ראה לקו\"ש שמות כרך ו ע' 244 ואילך."],["1960","*251","<b>כרת כתר</b>: נסמן לקמן שם הערה 244."]]],[2001910224,"<b>הו</b> מגלה נקראת באחד עשר כו' בחמשה עשר לא פחות ולא יותר, כי הנה אחד עשר הוא בחי' ו\"ה וחמשה עשר הוא בחי' יו\"ד ה'<sup data-n=\"1963\">252</sup>, והנה כתי' מלחמה להוי' בעמלק<sup data-n=\"1962\">*252</sup>, וארז\"ל אין השם שלם כו', ולכן ע\"י נס דפורים שנהרג המן<sup data-n=\"1964\">253</sup> שהי' מעמלק<sup data-n=\"1965\">254</sup> הי' חבור בחי' ו\"ה בי\"ה וזהו כרכים המוקפים חומה קורים בט\"ו, והיינו כי הקפת החומה תלוי ביהושע בן נון, שיהושע הי' לעומת בחי' קיר ברזל, כי יהושע הי' מל'<sup data-n=\"1966\">255</sup> דקדושה בחי' לבנה<sup data-n=\"1967\">256</sup> כמארז\"ל פני יהושע כפני לבנה<sup data-n=\"1968\">257</sup>, ולכן תלוי מלחמת עמלק גם ביהושע כמ\"ש ויחלוש יהושע את עמלק<sup data-n=\"1969\">258</sup> [וכמ\"ש בזח\"ב דס\"ה ע\"ב שמשה הי' לקרבא דלעילא ויהושע לקרבא דלתתא] ולכן כרכים המוקפים חומה<sup data-n=\"1970\">259</sup> קורים בט\"ו זהו ע\"ד בן כרך שראה את המלך שנבואת ישעי' הי' בבריאה<sup data-n=\"1972\">261</sup> שראה השרפים שאומרים<sup data-n=\"1973\">262</sup> קדוש ורוצים ליבטל כו' כי אימא מקננא בכורסייא<sup data-n=\"1974\">263</sup> ולכן קורי' בט\"ו בחי' י\"ה, משא\"כ כפרים ועיירות גדולות<sup data-n=\"1975\">264</sup> קורים בי\"ד והכפרים מקדימים ליום הכניסה זהו ע\"ד בן כפר<sup data-n=\"1971\">260</sup> שראה את המלך כו'.",[["1963","252","<b>אחד עשר . . ו\"ה . . יו\"ד ה'</b>: של\"ה תצוה שכט, א. פ' זכור של, ב. לקמן בהביאור על יד הערה 249. ובהנחה שם על יד הערה 116. אוה\"ת מגילת אסתר ע' רעח [נדפס גם בסה\"מ תרכ\"ט ס\"ע פו]. סה\"מ תרכ\"ז כאן."],["1962","*252","<b>כתר . . עמלק</b>: ראה גם סה\"מ תרכ\"ז כאן ע' קפז. מאמרי אדה\"א שמות ח\"ב ע' תצה. וש\"נ."],["1964","253","<b>נס דפורים שנהרג המן</b>: תלאוהו ביום ב' דפסח — ראה שו\"ע אדה\"ז הל' פסח סת\"צ, ס\"ב."],["1965","254","<b>המן שהי' מעמלק</b>: אסתר ג, א ובתרגום שם. ראה לקו\"ש פ' זכור כרך ג ע' 913 הערות 1-2."],["1966","255","<b>יהושע הי' מל'</b>: ראה גם תו\"ח בשלח ח\"א קנח, ב."],["1967","256","<b>מל' . . לבנה</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ב מערכת לבנה."],["1968","257","<b>פני יהושע כפני לבנה</b>: ב\"ב עה, סע\"א. ראה מאמרי אדה\"א נ\"ך ע' תסא ואילך."],["1969","258","<b>ויחלוש יהושע את עמלק</b>: בשלח יז, יג. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקלה."],["1970","259","<b>כרכים המוקפים חומה</b>: ראה אוה\"ת מגילת אסתר ע' רעו ואילך [נדפס גם בסה\"מ תרכ\"ט ע' פד ואילך]."],["1972","261","<b>שנבואת ישעי' הי' בבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להנ\"ל יבמות מט, ב ד\"ה מנשה. תו\"ח בא ח\"א קיד, סע\"ג. וש\"נ. סה\"מ תרמ\"ז ע' קלו. ע' קמב. סה\"מ ליקוט ח\"ג (מאמר ד\"ה בגמ' יבמות . . ע\"פ ואראה תרמ\"ט) ע' ו."],["1973","262","<b>השרפים שאומרים קדוש</b>: ישעי' ו, ב-ג. ראה חולין צא, ב ואילך ובתוד\"ה ברוך (שם צב, רע\"א)."],["1974","263","<b>אימא מקננא בכורסייא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["1975","264","<b>כפרים ועיירות גדולות</b>: ראה לעיל הערה 259."],["1971","260","<b>בן כרך . . בן כפר</b>: ראה חגיגה יג, ב."]]],[2001910225,"<h3>להבין וכו' בענין הציץ</h3>\n<b></b><b>בס\"ד ש\"פ צו פ' פרה לא הוע'</b>\n<b>להבין</b> שרשי וביאור הדברים בענין הציץ<sup data-n=\"1976\">1</sup> (שנת' שיש ב' פירושים בציץ, הא' לשון הארה<sup data-n=\"1977\">2</sup> מל' נץ החמה<sup data-n=\"1978\">3</sup> יציץ ופרח<sup data-n=\"1979\">4</sup>, והיינו אור האה\"ר ובהג\"ה<sup data-n=\"1980\">5</sup> אהבה בתענוגים, הב' ל' מציץ מן החרכים<sup data-n=\"1982\">7</sup> שפי' רש\"י לשון ראי'<sup data-n=\"1981\">6</sup> מל' ראו ראיתי<sup data-n=\"1983\">8</sup>), הנה ציץ וציצית איתא ברע\"מ סוף פ' שלח לך דקע\"ד סע\"ב שהציץ הוא עלמא דאתי<sup data-n=\"1984\">9</sup>, וציצית בחי' מל'<sup data-n=\"1985\">10</sup> נוקבא<sup data-n=\"1986\">11</sup> שמקבלת מבחי' ציץ שהוא עלמא דאתי בחי' בינה<sup data-n=\"1987\">12</sup>, והיינו בחי' הארת הכתר שהוא בחי' עת\"י וא\"א<sup data-n=\"1988\">13</sup> המאיר בבינה שהוא עולם התענוג<sup data-n=\"1989\">14</sup>, וזהו שכ' ברע\"מ ציץ דאיהי<sup data-n=\"1990\">15</sup> סימן דעלמא עילאה דאתעטר בי' כהנא",[["1976","1","<b>להבין שרשי וביאור הדברים בענין הציץ</b>: מאמר זה הוא מיוסד על הנחת כ\"ק אדמו\"ר מהר\"ש ממאמר אביו כ\"ק אדמו\"ר הצ\"צ משנת תרט\"ז והוא ביאור על מאמר ד\"ה מגילה נקראת שנדפס לפנ\"ז.\nמדרוש הצ\"צ הנ\"ל ישנם ג' הנחות והם: א) הנחת כ\"ק אדמו\"ר מהר\"ש נמצאת בס' ”מאלמים אלומים\" 1029 כז, ב ואילך (ספר זה ”מאלמים אלומים\" כולל הנחות כ\"ק אדמו\"ר מהר\"ש שנרשמו בגוכתי\"'ק מדרושי אביו כ\"ק אדמו\"ר הצ\"צ משנת תרט\"ז).\nב) הנחת ר' הלל (בתוס' הגהותיו) נדפסה בפלח הרמון ע\"ס שמות — מג\"א ע' שס ואילך בכותרת: ”ליל ב' י\"א אדר שני רחבו\"ת לפ\"ק ביאור על מאמר הנ\"ל\". ומציין אלי' ומעתיק ממנה בהמאמר כאן — לקמן על יד הערות מד-מו. וראה גם שם על יד הערה לט.\nג) ועוד הנחה מדרוש הנ\"ל נמצא בבוך 739 שז, ב והיא הנחת של ר' דוב [בעריל] קאליסקער [ראה גם לעיל מאמר ד\"ה קדש ישראל לה' בהערה 1].\nהמאמר נרשם בגוכתי\"ק בכותרת בס\"ד. ואח\"כ הועתק בכת\"י מעתיק בהוספת הגהות בגוכתי\"ק ובראשו נרשם: לא הוע'.\nדרוש זה שנרשם כמאמר אחד ללא ציון הן בהמאמר והן במפתח של הבוך שהי' עוד פתיחה, הנה מהנחות בנו כ\"ק אדמו\"ר מהורש\"ב [שנדפסו לקמן בחלק ההנחות] אנו יודעים שדרוש זה נאמר בשתי פעמים, היינו פעם הראשון בפתיחה זו נאמרו ד\"פ הראשונים בש\"פ צו. ובפעם השני מפ\"ה ואילך ובפתיחה ועשית ציץ זהב טהור ונאמר בש\"פ שמיני. ויש לציין שבהמאמר נסמנו רק ה\"פ ומפיסקא ”ופתחת עליו פתוחי חותם\" בא ללא ציון פרקים.\nהנחות כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסו לקמן בחלק הנחותיו כנ\"ל [ומשם נעתק התאריך ”שבת פ' צו פ' פרה\" שבריש המאמר כאן. וכן לקמן ריש פ\"ה התאריך ”ש\"פ שמיני\"].\nמאמר זה נזכר בסה\"מ תרמ\"ז ע' פט."],["1977","2","<b>בציץ הא' לשון הארה</b>: ראה גם תו\"א תצוה פג, א. תו\"ח תצוה ח\"ב שנו, א. שסג, ג."],["1978","3","<b>נץ החמה</b>: ברכות ח, ב. ט, ב. ועוד."],["1979","4","<b>יציץ ופרח</b>: ישעי' כז. ו."],["1980","5","<b>ובהג\"ה</b>: לעיל בהמאמר מגילה נקראת פ\"ב."],["1982","7","<b>מציץ מן החרכים</b>: שה\"ש ב, ט."],["1981","6","<b>הב' . . לשון ראי'</b>: ראה אוה\"ת תצוה ע' א'תרפט שמציין לזהר ויקהל דרי\"ז, ב ע\"פ ויעש את הציץ, ציץ אסתכלותא. תו\"ח תצוה ח\"ב שנו, א. שסג, ג."],["1983","8","<b>ראו ראיתי</b>: שמות ג, ז [ושם: ראה ראיתי — וכ\"ה לעיל בהמאמר מגילה נקראת פ\"ב]."],["1984","9","<b>שהציץ הוא עלמא דאתי</b>: ראה לשון הרע\"מ הועתק בסמוך בפנים."],["1985","10","<b>וציצית בחי' מל'</b>: ראה מאו\"א מערכת ציצית אות כב. בהערה הבאה."],["1986","11","<b>וציצית . . נוק'</b>: רע\"מ שם קעה, רע\"א. תו\"ח תצוה ח\"ב כאן שנט, א. וש\"נ."],["1987","12","<b>עלמא דאתי בחי' בינה</b>: ראה זהר תוספתא וארא כז, סע\"ב. רע\"מ משפטים קטו, סע\"ב. תצא רעח, א."],["1988","13","<b>הכתר . . עת\"י וא\"א</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["1989","14","<b>בבינה שהוא עולם התענוג</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' הערה 118."],["1990","15","<b>דאיהי</b>: ברע\"מ שם: דאיהו."]]],[2001910226,"רבא, פי' שע\"י הכה\"ג הנושא הציץ מאיר בחי' עת\"י וא\"א שמאירים בעלמא עילאה גם בעלמא תתאה<sup data-n=\"1991\">16</sup>. והענין הוא להיות כי עלמא תתאה הוא בחי' אימא תתאה<sup data-n=\"1992\">17</sup> מקבלת מבחי' ז\"א שהוא מקור לגבול, וכמ\"ש בפרקי היכלות שיעור קומה<sup data-n=\"1993\">18</sup> של יוצר בראשית רל\"ו אלפים ריבו (כן נמצא במ\"א) רבבות פרסאות (ואם<sup data-n=\"1994\">19</sup> היות שהפרסאות הוא פרסאות שלמעלה, וענין בחי' המספר ברל\"ו אלפים ריבו רבבות פרסאות זהו ג\"כ שם שעולה מספרו כך, וכמ\"ש גדול אדונינו ורב כח<sup data-n=\"1995\">20</sup>, ורב כח עולה מספר רל\"ו<sup data-n=\"1996\">21</sup>, ומ\"מ אינו בחי' גבול עדיין, ועכ\"ז) הנה הוא מקור לגבול, אמנם ע\"י הציץ מאיר מעלמא עילאה בחי' בינה<sup data-n=\"1997\">22</sup> הארת הענג המלובש בבינה, והיינו בחי' א\"א ועת\"י* (וזהו דכתיב ולתבונתו אין מספר<sup data-n=\"1998\">23</sup> שמצד בחי' התגלות עת\"י המאיר בבינה אינו שייך בחי' מספר, וז\"ע בחי' האה\"ר ואהבה בתענוגים שממשיך אהרן כהנא רבא ע\"י הציץ, שזהו פי' ציץ לשון הארה כו', ומעתה יובן גם פי' ציץ לשון ראיה) שז\"ע וישע ה' אל הבל<sup data-n=\"1999\">24</sup> כו' שהוא בחי' ש\"ע נהורין<sup data-n=\"2000\">25</sup>, כי בז\"א הוא רק ק\"נ נהורין<sup data-n=\"2001\">26</sup> (ולכן\n\n*)<i>נרשם בשולי היריעה:</i>\nהארת<sup data-n=\"8321\">א</sup> הענג מבחי' כתר א\"א ועת\"י המלובש בבינה הם בל\"ג, זהו ביאור על האה\"ר שנמשך ע\"י אהרן שהיא בל\"ג וגם אהבה בתענוגים שנת' בההג\"ה ג\"כ בכלל זה.",[["1991","16","<b>בעלמא עילאה . . תתאה</b>: ראה בהערות הבאות."],["1992","17","<b>עלמא תתאה . . תתאה</b>: ראה זהר בראשית לד, א ובמק\"מ שם. אוה\"ת (יהל אור) תהלים ס\"ע תטו ואילך."],["1993","18","<b>בפרקי היכלות שיעור קומה</b>: ראה לעיל מאמר ד\"ה ועבדתם את ה\"א בסופו. וש\"נ."],["1994","19","<b>ואם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["1995","20","<b>גדול אדונינו ורב כח</b>: תהלים קמז, ה."],["1996","21","<b>ורב כח עולה מספר רל\"ו</b>: ראה לקו\"ת ויקרא בהוספות נד, ב מפרקי היכלות. מאמרי אדה\"א דברים ח\"ג ע' תתיט בהערה."],["1997","22","<b>מעלמא עילאה בחי' בינה</b>: ראה לעיל הערה 17. אוה\"ת תצוה כאן ס\"ע א'תשלב ואילך."],["1998","23","<b>ולתבונתו אין מספר</b>: המשך הכתוב גדול אדונינו ורב כח [בתהלים שם: לתבונתו. אבל כ\"ה גם בזהר תרומה קעא, ב. לקו\"ת ברכה צג, ד. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 11. מאמרי אדה\"א בראשית ע' עח. וש\"נ. סה\"מ תרל\"ח ע' ז. וש\"נ]."],["1999","24","<b>וישע ה' אל הבל</b>: בראשית ד, ד. ראה גם לקו\"ת ויקרא בהוספות נא, ב. פינחס עז, סע\"ב. שה\"ש ב, ב. מ, א. וראה גם תו\"א ויצא כב, רע\"א."],["2000","25","<b>ש\"ע נהורין</b>: ראה זהר אד\"ר נשא קכח, ב. ע\"ח שער א\"א שי\"ג, פי\"ד. אוה\"ת מטות ע' א'רעב. המשך תער\"ב ח\"ב ע' א'רה."],["2001","26","<b>ק\"ן נהורין</b>: ראה זהר אד\"ר נשא קלה, סע\"ב. ע\"ח והמשך תער\"ב שם. תו\"א ויחי מח, ב. לקו\"ת מסעי צג, סע\"ג. וש\"נ. פלח הרמון שה\"ש צח, א.\n\n<b>א</b> ) <b>הארת</b>: נרשם בשולי היריעה ללא ציון מקמו בפנים, ואולי שייך כאן או לעיל על יד הערה 13. ובצד הימני של העמוד בהפסק קו נרשם הוראה להמעתיק: ג\"ז לרשום בשפולי העמוד.\nהערה זו וכן הערה הבאה לאחרי' לא נרשמו מקומם בהמאמר, ובכת\"י מעתיק [ראה לעיל הערה 1] העתיקם בשני קטעים זאח\"ז מתחילה הערה השני' ואח\"כ הערה זו ובגוכתי\"ק הוסיף קו בין שני הקטעים."]]],[2001910227,"נק' זעיר אנפין* לפי שנשאר ארך אורות<sup data-n=\"2002\">27</sup> מהש\"ע נהורין שלא נמשכו בו) אשר מזה מסתעף שיהי' מקור לגבול, לזה הו\"ע וישע כו' אל הבל שיומשך בחי' ש\"ע נהורין שמאירים בעלמא עילאה, ונק' בחי' הארת פנים כמ\"ש יאר ה' פניו אליך<sup data-n=\"2003\">28</sup> פי' כי הנה הפנים הוא פנוי משערות שהוא בחי' תיקון ואמת<sup data-n=\"2004\">29</sup>, כי הנה הי\"ב תיקוני דיקנא הם בחי' שערות<sup data-n=\"2005\">30</sup> שהם ממותרי מוחין<sup data-n=\"2006\">31</sup> (כנודע שגידול השערות הם ממותרי מוחין ולכן גם למטה באדם צמיחת הזקן הוא אחר שיש לו גדלות המוחין וכמבואר בש\"ע או\"ח סי' נ\"ג ס\"ח לענין ש\"ץ<sup data-n=\"2008\">33</sup> שהשנים שראוי להתמלאות בהם זקנו הוא אחר עשרים שנה<sup data-n=\"2007\">32</sup>) אך בחי' הארת פנים הוא פנוי משערות כמ\"ש חכמת אדם תאיר פניו<sup data-n=\"2009\">34</sup> שהיא בחי' תיקון ואמת להיות מאיר בז\"א שהוא בחי' יעקב<sup data-n=\"2010\">35</sup> ועז\"נ תתן אמת ליעקב<sup data-n=\"2011\">36</sup> שהוא בחי' הארת פנים הנ\"ל (וכמ\"ש מזה בלק\"ת בביאור אלה מסעי, השלישי פ\"ה<sup data-n=\"2012\">37</sup>, והגם שבחי' תיקון השלישי מיגת\"ד ג\"כ פנוי משערות כמ\"ש בזהר באד\"ר דקל\"א א', מ\"מ שאני תיקון השביעי תיקון ואמת שבו נמשך ומתגלה אור הח\"ס כמו שחכמת אדם תאיר פניו, פניו דוקא<sup data-n=\"2013\">38</sup> ששם עיקר גילוי החיות, ובא\n\n*)אנפין<sup data-n=\"8322\">ב</sup> הוא בחי' הפנימיות דאוא\"ס רק שמלובש בבחי' קטנות וזהו זעיר וזהו זעיר<sup data-n=\"8323\">ג</sup> אנפין והקטנות הוא לפי שהכלים דז\"א הגם שאינם בבחי' גבול מ\"מ הם מקור לגבול.",[["2002","27","<b>ארך אורות</b>: ראה ע\"ח שם. קול ברמה לזהר אד\"ר נשא קכח, ב. זהר הרקיע בראשית ע' כז [צ\"ל: כח]. לקו\"ת במדבר יא, ד. מסעי שם. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 17."],["2003","28","<b>יאר הוי' פניו אליך</b>: נשא ו, כה."],["2004","29","<b>הנה הפנים . . תיקון ואמת</b>: ראה זהר אד\"ר נשא קלא, א. קלג, ב. ע\"ח שער א\"א שי\"ג, פ\"ט. לקו\"ת מסעי צג, א ואילך."],["2005","30","<b>הי\"ב תיקוני דיקנא . . שערות</b>: בזהר אד\"ר נשא קלא, א (המצויין בסמוך בפנים) נמנו י\"ג ת\"ד. ואולי מפני שאומר כאן שתי' הז' הוא פנוי משערות. אבל ראה בסמוך בפנים אודות תי' הג'. וכן יש להעיר גם מתי' הה' ותי' הי\"ב. וראה גם קול ברמה לאד\"ר שם ודף לד, א-ב. זהר הרקיע לזהר תרומה (ספדצ\"נ פ\"ת) קעז, א. ע\"ח שם. מבוא שערים ש\"ג ח\"ב, פי\"א."],["2006","31","<b>שערות שהם ממותרי מוחין</b>: ראה ע\"ח שער א\"א שי\"ג, פי\"א. מבוא שערים ש\"ה ח\"א, פי\"ג. לקו\"ת ברכה צה, רע\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תשעח. וש\"נ. נ\"ך ס\"ע קעו ואילך. תו\"ח ח\"ש קכג, סע\"ג ואילך."],["2008","33","<b>לענין ש\"ץ</b>: תיבות אלו הם הוספה על לשון לקו\"ת."],["2007","32","<b>ולכן גם . . שנה</b>: לשון לקו\"ת מסעי (המצויין בסמוך בפנים) צב, ד."],["2009","34","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["2010","35","<b>בז\"א . . יעקב</b>: ראה ע\"ח שער פרצופי זו\"ן של\"א, פ\"א. שער הקליפות שמ\"ח, פ\"ג. שער הפסוקים וישלח לב, כט. שער היחוד ע' קלג ואילך. לקו\"ת הנסמן בפנים."],["2011","36","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["2012","37","<b>בלקו\"ת . . מסעי . . פ\"ה</b>: צג, ג."],["2013","38","<b>והגם שבחי' . . פניו דוקא</b>: ע\"פ לשון לקו\"ת מסעי צג, ב.\n\n<b>ב</b> ) <b>אנפין</b>: נרשם בצד הימני של העמוד בהפסק קו בשורה זו, וגם נרשם קו ממעל לתיבות אלו, וברוחב העמוד נרשם מלמעלמ\"ט הוראה להמעתיק: לרשום זה למטה בשפולי העמוד.\nלקטע זה ראה גם פלח הרמון מג\"א כאן ע' שמ.\n\n<b>ג</b> ) <b>וזהו זעיר וזהו זעיר</b>: כ\"ה בגוכתי\"ק."]]],[2001910228,"מעצמיות בחי' ח\"ס כמו שצהיבת הפנים בא משכל חדש דוקא כמו שמצינו בר' אבוה שצהבו פניו מחמת שמצא תוספתא חדתא<sup data-n=\"2014\">39</sup> שמכח החידוש שנתחדש לו ממקור השכל הוא בחי' ח\"ס בחי' משכיל בא לו צהיבת הפנים כו') ועד\"ז יובן ענין הציץ שהוא בחי' אסתכלותא דעלמא עילאה בעלמא תתאה<sup data-n=\"2015\">40</sup> דהיינו בחי' הארת פנים ע\"י בחי' עיינין (היינו בחי' ההסתכלות הנ\"ל בחי' ראיה כו').\n(ב) <b>וביאור</b> הענין הנה כתי' כי עין בעין נראה<sup data-n=\"2016\">41</sup> כו', פי' עין הוא לשון נבואה כמ\"ש עין יעקב<sup data-n=\"2017\">42</sup> שהוא בחי' נבואה (כמארז\"ל במד\"ר תצוה פל\"ח<sup data-n=\"2018\">43</sup>, אין עין אלא נבואה) וע\"ד שארז\"ל ראתה שפחה על הים<sup data-n=\"2019\">44</sup> מה שלא ראו כו' שהוא ג\"כ בחי' נבואה שנק' בשם ראי', (וכמו שאמר שמואל על עצמו אנכי הרואה<sup data-n=\"2020\">45</sup> וכמ\"ש כי לנביא היום יקרא לפנים הרואה (ש\"א ט' ט'), והיינו כי נבואה הוא בחי' גילוי ההעלם, וכמו בענין האתונות שנאבדו לקיש אבי שאול (בש\"א ט'<sup data-n=\"2021\">46</sup> ) שאמר לו שמואל שנמצאו האתונות<sup data-n=\"2022\">47</sup>, שגילה לו מה שהי' נעלם ממנו, וכן ענין ראתה שפחה\n\n<i>נרשם בשולי היריעה:</i>\nע'<sup data-n=\"8324\">ד</sup> בס' הדרת מלך<sup data-n=\"8325\">ה</sup> דצ\"ב סע\"א<sup data-n=\"8326\">ו</sup> בשם הע\"ח<sup data-n=\"8327\">ז</sup> בענין הסתכלות מצחא דז\"א<sup data-n=\"8328\">ח</sup> או או\"א בעתיקא והב' הוא הסתכלות עתיק בהם, ושם אם ההסתכלות הוא במצח או בעיינין, ושם הסתכלות עין א' או ב' עיינין, ומזה יובן משנת\"ל ספ\"א ענין הסתכלות דעלמא עילאה בעלמא תתאה ע\"י בחי' עיינין ובחי' ש\"ע נהורין שביאר בהדרת מלך דצ\"ב ע\"ב<sup data-n=\"8329\">ט</sup>.",[["2014","39","<b>בר' אבוה . . תוספתא חדתא</b>: ראה ירושלמי שבת פ\"ח, ה\"א. לקו\"ת שם. מאמרי אדה\"א קונטרסים ע' שדמ. וש\"נ. ש\"א יב, ב. תו\"ח יתרו ח\"ב רסז, ג. הנסמן בסה\"מ תרכ\"ז ע' פז."],["2015","40","<b>הציץ . . אסתכלותא דעלמא עילאה בעלמא תתאה</b>: השווה אוה\"ת תצוה כאן ע' א'תרפט. סה\"מ תרכ\"ט ע' צ. וראה גם לקמן ספ\"ג."],["2016","41","<b>כי עין בעין נראה</b>: שלח יד, יד [בדילוג — ראה גם לעיל בהמאמר מגילה נקראת ובהערה 88]."],["2017","42","<b>עין יעקב</b>: ברכה לג, כח."],["2018","43","<b>במד\"ר תצוה פל\"ח</b>: סימן ד. מובא גם לקמן במאמר ד\"ה הים ראה וינוס על יד הערה 81."],["2019","44","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. תו\"ח בשלח ח\"א קצד, ב ואילך. סה\"מ תרל\"א ח\"א ע' רסד ואילך. לעיל מאמר ד\"ה אז ישיר בתחילתו."],["2020","45","<b>אנכי הרואה</b>: שמו\"א ט, יט."],["2021","46","<b>בש\"א ט'</b>: פסוק ג."],["2022","47","<b>שנמצאו האתונות</b>: שם, כ.\n\n<b>ד</b> ) <b>ע'</b>: בגוכתי\"ק נרשמה הערה זו רק לקמן בפ\"ה בע' הראשון בשולי הגליון [ועפ\"ז מובנת בפשטות מ\"ש כאן בהערה ”משנת\"ל ספ\"א\"]. אבל בכת\"י מעתיק [ראה לעיל הערה 1] הנה 1) באה הערה זו כאן. 2) שם ברפ\"ה כתבה ונמחקה. 3) בע' שלאח\"ז כתבה עוה\"פ — ונדפסה שם עוה\"פ.\n\n<b>ה</b> ) <b>בס' הדרת מלך</b>: לר' שלום בוזאגלו אמשטרדם תקכ\"ו (בעל מקדש מלך).\n\n<b>ו</b> ) <b>דצ\"ב סע\"א</b>: סימן קס.\n\n<b>ז</b> ) <b>בשם הע\"ח</b>: שער א\"א שי\"ג, ספי\"ג (בשינויים).\n\n<b>ח</b> ) <b>מצחא דז\"א</b>: שם: (ה)ז\"א.\n\n<b>ט</b> ) <b>דצ\"ב ע\"ב</b>: ע\"ח שם, פי\"ד."]]],[2001910229,"היינו שבשעת קרי\"ס נתגלה גם לשפחה גילוים מה שלא נתגלו לנביאים כו', ולכן נק' נבואה בשם עין יעקב ע\"ש שהעין הוא כלי הראי' שבה רואים כו'). והנה בבחי' עין יש שני בחי' עין, והיינו בחי' עין דלתתא שהוא בחי' דעת תחתון בחי' יחו\"ת, והב' הוא עינא דלעילא<sup data-n=\"2023\">48</sup> בחי' ד\"ע<sup data-n=\"2024\">49</sup> בחי' יחו\"ע<sup data-n=\"2025\">50</sup> כו', והיינו שבחי' עין דלתתא הוא השגת בחי' ביטול היש לאין, וזהו בחי' יחו\"ת, שהגם שנתהוה בחי' היש הגשמי עכ\"ז ידע ויתבונן היטב שכל עיקר המכוון מבחי' התהוות היש הוא בכדי שיהי' ביטול היש לאין, וזהו שארז\"ל איזהו חכם<sup data-n=\"2026\">51</sup> הרואה את הנולד פי' שע\"י חכמתו ידע שכל עיקר מכוון מבחי' הנולד הוא בחי' היש הנולד מאין לא שישאר בבחי' יש ודבר נפרד ח\"ו כ\"א שהיש יהי' בטל לאין (וזהו הרואה את הנולד פי' וענין הראי'\n\nשכל<sup data-n=\"8330\">י</sup> ענין התהוות בחי' היש, הוא בכדי שיהי' בחי' ביטול היש לאין, וזהו שארז\"ל איזהו חכם הרואה את הנולד שיראה בחכמתו איך שהנולד הוא בחי' היש עיקר המכוון במה שנולד הוא בכדי שיהי' ביטול היש לאין, וזהו בחי' עינא דלתתא בחי' יחו\"ת, היינו שיש מציאות היש רק שהוא בטל לאין ועיקר המכוון מהתהוותו הוא בכדי שיהי' הבחי' ביטול היש לאין, וזהו היחוד דיחו\"ת, ויש בחי' עינא דלעילא שהוא בחי' ד\"ע שהוא איך דכולא קמיה כלא ממש חשיב, והגם שנברה\"ע ליש ודבר, מ\"מ יבין היטיב שבאמת לאמיתו הוא כולא קמיה כלא חשיב מפני כי שרש ומקור בחי' היש זה הוא בטל לגמרי כמ\"ש במ\"א, וכ\"ש בחי' היש שנתהוה הוא בטל כו', וז\"ע בחי' ה' אחד שבק\"ש שהוא בחי' יחו\"ע שאותיות חי\"ת דל\"ת שבתיבת אחד רומזים שהגם שנברה\"ע בחי' ז' רקיעים וארץ שזהו ח' דאחד, וד' דאחד הוא בחי' ד' רוחות העולם, עכ\"ז הם בטלים לאלף הוא בחי' אלופו ש\"ע ואינם תופסים מקום כלל, שז\"ע בחי' דיעה העליונה שלמעלה היש ולמטה אין, ופי' כי עין בעין היינו שיאיר בחי' עינא דלעילא בחי' ד\"ע בעינא דלתתא בחי' ד\"ת, וזהו שנת\"ל עין הוא לשון נבואה, היינו כמו שנבואה הוא בחי' גילוי ההעלם כן בחי' ד\"ע הוא נעלם מהנבראים שמשיגים רק בחי' ד\"ת לבד, והנבואה פי' הגילוי הוא שיתגלה בחי' ד\"ע בד\"ת שז\"ע כי עין בעין וזהו ע\"י הציץ שהוא בחי' הסתכלות עינא עילאה בעינא תתאה, היינו ד\"ע בד\"ת.",[["2023","48","<b>עין דלתתא . . עינא דלעילא</b>: ראה זהר אד\"ר נשא קל, א."],["2024","49","<b>דעת תחתון . . ד\"ע</b>: באוה\"ת סוכות ע' א'תשל בשם האריז\"ל [ראה תניא — אגה\"ק — עם מ\"מ הגהות והע\"ק סט\"ו ד\"ה דעת תחתון דעת עליון]. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11."],["2025","50","<b>יחו\"ת . . יחו\"ע</b>: זהר בהקדמה יב, א."],["2026","51","<b>איזהו חכם</b>: תמיד לב, א. ראה תניא פמ\"ג. מאמרי אדה\"א דברים ח\"א ע' רכא. וש\"נ. שע\"ת עא, ג ובהערה 23. תו\"ח תצוה ח\"ב שכט סע\"ד ואילך.\n\n<b>י</b> ) <b>שכל</b>: נרשם בע' קטן בפ\"ע בכותרת: לביאור דציץ בס' מאלמים אלומים [ראה לעיל הערה 1] ומציין הע' והשיטה איפה ששייך הוספה זו בס' הנ\"ל. השווה הנרשם כאן להנרשם בפנים."]]],[2001910230,"הוא שיתגלה ההעלם כנ\"ל שכמו הנבואה נק' בשם ראיה לפי שמגלה ההעלם, כמ\"כ כאן בענין בחי' ביטול היש, שהיש נראה ונגלה לעין כל, ובחי' ביטולו לבחי' האין אינו נראה כ\"כ ולכן נק' העלם, וזה שיתראה ויתגלה ההעלם היינו בחי' ביטול היש זהו נק' בשם ראיה, וזהו עינא תתאה בחי' ד\"ת יחו\"ת, בחי' ביטול היש לאין כו'), וענין בחי' עינא דלעילא בחי' ד\"ע הוא איך דכולא קמיה כלא חשיב<sup data-n=\"2027\">52</sup> שאף שנבה\"ע ליש ודבר עכ\"ז באמת לאמיתו הוא כלא וכאין ממש מפני כי שרש ומקור המהוה בחי' היש זה הוא בטל בתכלית<sup data-n=\"2028\">53</sup> (וכ\"ש בחי' ההתהוות שהוא בחי' היש שנתהוה הוא כלא וכאין נגדו ית' שהוא ית' הוא היש האמיתי וכל מה שלמטה הוא אין), וז\"ע הוי' אחד<sup data-n=\"2029\">54</sup> שאומרים בק\"ש שאותיות ח\"ד שבתיבת אחד רומזים לז' רקיעים וארץ וד' רוחות העולם<sup data-n=\"2030\">55</sup>, והיינו הגם שנתהוה ז\"ר וארץ וד\"ר העולם עכ\"ז הם בטלים בתכלית לבחי' האלף הוא אלופו ש\"ע<sup data-n=\"2031\">56</sup>, ואינם תופסים מקום כלל (מאחר שגם שרש בחי' ז\"ר וארץ הגשמיים אלו הם בטלים לגמרי כמ\"ש לך ה' הגדולה כו' לך ה' הממלכה<sup data-n=\"2032\">57</sup> כו'), שזהו בחי' ד\"ע שלמעלה היש ולמטה אין וכולא קמי' כלא חשיב (וכל הקרוב יותר אליו ית' דהיינו מי שהוא קמי' יותר משיג יותר, איך שהוא כלא ממש חשיב).\nג) <b>(והנה</b><sup data-n=\"2033\">*58</sup> ב' בחי' עין אלו זהו בחי' שילוב הוי' בש' אד', ושילוב ש' אד' בש' הוי'<sup data-n=\"2034\">58</sup>, וכנודע בענין השילובים שאות הראשונה גוברת, שזהו כלל בפע\"ח<sup data-n=\"2035\">59</sup>, ולכן בענין שילוב ש' הוי' בש' אד' שאות הראשון הוא האלף דש' אד' לכן ש' אד' גובר, ובבחי' שילוב ש' אד' בש' הוי' שאות הראשון הוא היו\"ד דש' הוי' לכן ש' הוי' גובר, ונודע כי ש' הוי' הוא בחי' יחו\"ע וש' אד' הוא בחי' יחו\"ת<sup data-n=\"2036\">60</sup>, שהם בחי' עין דלעילא ועין דלתתא, ולפי משנ\"ת לעיל שעין הוא בחי' נבואה בחי' גילוי ההעלם, א\"כ בענין שילוב ש' הוי' בש' אד' ששם אד' גובר לכן נראה למטה הבריאה ליש ודבר וכנודע שענין ש' אד' הוא בחי' אנת אשתמודע אדון<sup data-n=\"2037\">61</sup>, שענין בחי' האדנות זהו על בחי' עם נפרדים דוקא, מלאכים ונשמות דבי\"ע, שהרי על בנים אינו שייך בחי' האדנות כלל, ובחי' ביטול היש להיות וכל צבא השמים לך משתחוים<sup data-n=\"2038\">62</sup>,",[["2027","52","<b>דכולא קמיה כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["2028","53","<b>שרש ומקור . . בטל בתכלית</b>: ראה גם לעיל בהמאמר מגילה נקראת פיסקא והפי' הב' ובהנסמן שם ובריש המאמר שם."],["2029","54","<b>הוי' אחד</b>: ואתחנן ו, ד."],["2030","55","<b>ח\"ד . . לז' . . וד' רוחות העולם</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. סה\"מ תר\"ם ח\"א ע' קט הערה 50."],["2031","56","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["2032","57","<b>לך ה' הגדולה . . הממלכה</b>: דבהי\"א כט, יא."],["2033","*58","<b>(והנה</b>: סיום הסוגר הוא בסיום הפרק."],["2034","58","<b>שילוב הוי' בש' אד' . . הוי'</b>: ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. לקו\"ת ש\"ש סה, ד ובהנסמן במ\"מ שם סד, ב. תו\"ח וארא ח\"א נ, א הערה 32."],["2035","59","<b>שאות הראשונה גוברת . . בפע\"ח</b>: כ\"ה בלקו\"ת שם (סה, ד). ובמ\"מ לשם מציין למ\"ח מסכת או\"א פ\"ג, מ\"ה. ראה גם שער היחוד והאמונה פ\"ז ע' פב. תו\"א מקץ מג, א. סה\"מ תרל\"ב ח\"א ע' סה."],["2036","60","<b>הוי' . . יחו\"ע . . אד' . . יחו\"ת</b>: ראה שער היחוה\"א פ\"ז. לקו\"ת שם."],["2037","61","<b>אנת אשתמודע אדון</b>: ת\"ז בהקדמה יז, רע\"ב. ראה תו\"א מג\"א קיז, ג. לקו\"ת אמור לב, ב. שער היחוה\"א רפ\"ז."],["2038","62","<b>וכל צבא השמים לך משתחוים</b>: נחמי' ט, ו [ושם: וצבא — ראה לעיל בהמאמר מגילה נקראת הערה 108].\nראה מאמרי אדה\"א בראשית ע' נז. וש\"נ. תו\"ח בראשית א, ג ובהערה 42."]]],[2001910231,"וכן ביטול היש דאדם וכל הנבראים שבעשיה ובעוה\"ז הגשמי, וכמו סיבוב והילוך השמש שמסבבת ממזרח למערב ושוקעת ז\"ע ההשתחוואה שלה למערב לפי ששכינה<sup data-n=\"2040\">64</sup> במערב<sup data-n=\"2039\">63</sup> כמ\"ש בד\"ה משכני אחריך נרוצה<sup data-n=\"2041\">65</sup>, זהו מבחי' ש' הוי' שמשולב בש' אד', אך זהו אינו נראה ונגלה כ\"כ כ\"א שזהו בהעלם, וענין בחי' יחו\"ת הוא שיתגלה ההעלם היינו בחי' הביטול שנמשך מבחי' ש' הוי' שמשולב בש' אד', שאם היות שנתהוה ליש ודבר מבחי' ש' אד' המסתיר על ש' הוי' מ\"מ יהי' בבחי' ביטול היש שזה נמשך מבחי' ש' הוי' שמשולב בש' אד', וזהו יחו\"ת בחי' גילוי ההעלם ראי' דד\"ת בחי' איזהו חכם הרואה את הנולד בחי' היש שנתהוה מש' אד' שעיקר המכוון שיהי' בטל לאין והיינו שיהי' יש ובטל*.\n<b>וענין</b> שילוב ש' אד' בש' הוי' שאות ראשונה הוא בחי' היו\"ד דש' הוי' גובר שהוא בחי' יחו\"ע איך שקמיה כלא ממש חשיב וש' אד' הוא שרש ומקור המהוה היש הוא משולב בו ומיוחד בתכלית היחוד כביטול אור השמש בשמש כמ\"ש בסש\"ב ח\"ב פ\"ז, אלא שאצלינו נבראי' בע\"ג דהיינו הנשמה המלובשת בגוף ונה\"ב אינו מושג זה, נמצא זהו אצלינו בהעלם, וכמ\"ש בת\"א בד\"ה בך\"ה בכסליו (דף מ\"ט ע\"א<sup data-n=\"2042\">66</sup>) שזהו\n\nואפ\"ל<sup data-n=\"8331\">יא</sup> שז\"ע דכתי' ביום עשות ה' אלקי' ארץ ושמי'<sup data-n=\"8332\">יב</sup> שהכוונה על התראות היש וביטול היש.\n*)והגם<sup data-n=\"8333\">יג</sup> שזהו דבר והיפוכו דהיינו להיות יש ועכ\"ז יהי' בטל לאין אך זהו מחמת שהמשל ופחד עמו עושה שלום<sup data-n=\"8334\">יד</sup> בין שני הפכים ואינם מנגדים כלל כמ\"ש בלק\"ת בביאור שובה ישראל דרוש הראשון<sup data-n=\"8335\">טו</sup>.",[["2040","64","<b>ששכינה במערב</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרכו ואילך."],["2039","63","<b>השמש . . ההשתחוואה . . במערב</b>: ראה ב\"ב כה, א. בהערה שלפנ\"ז."],["2041","65","<b>ששכינה במערב . . משכני אחריך נרוצה</b>: ראה סה\"מ תר\"ל ע' רעא ואילך. ע' רעט ואילך."],["2042","66","<b>וכמ\"ש בת\"א . . מ\"ט ע\"א</b>: במהדורת קה\"ת וישב כט, ב.\n\n<b>יא</b> ) <b>ואפ\"ל</b>: נרשם בשולי היריעה (ללא ציון מקומו בפנים), כן בא בצד הימני של העמוד הוראה להמעתיק (נרשם מלמעלמ\"ט ובהפסק קו): לרשום למטה. הערה זו לא הועתקה בכת\"י מעתיק (ראה לעיל הערה 1).\n\n<b>יב</b> ) <b>ביום עשות . . ושמי'</b>: בראשית ב, ד.\n\n<b>יג</b> ) <b>והגם</b>: בכת\"י מעתיק [ראה לעיל הערה 1] בצד הימני של העמוד באה הוראה להמעתיק בגוכתי\"ק (נרשם מלמעלמ\"ט ובהפסק קו): מן [תיבת] והגם עד [תיבת] הראשון בשיטה [המתחלת שבכת\"י מעתיק] בביאור כן הוא אך ל\"נ [ לא נאמר] ואצ\"ל [ ואין צריך להעתיק]. אך לא הו\"ע כלל. וראה לעיל בריש המאמר שהמאמר לא הועתק.\n\n<b>יד</b> ) <b>שהמשל ופחד . . שלום</b>: איוב כה, ב.\n\n<b>טו</b> ) <b>בלק\"ת . . הראשון</b>: ש\"ש סה, ד."]]]]});
